P.entries["quest:1519"] = {n="Call of Earth",s="Call of Earth este un rit sacru de initiere samanica, care pune la incercare rabdarea, rezistenta si respectul initiatului fata de lumea naturala. Raspunzand chemarii pamantului si acceptand sapta elementala, cel care cauta porneste intr-o renastere spirituala, menita sa-i ingaduie comuniunea directa cu temelia intregii vieti.",h="Call of Earth este un rit sacru de initiere samanica, care pune la incercare rabdarea, rezistenta si...",kw={"chemarea Pamantului","Mama Pamant","elemente","rabdare","renastere","sapta","Shaman","rezistenta"},ang={["class:Shaman"]="Acest ritual marcheaza un prag hotarator in pregatirea unui saman, cand comuniunea cu pamantul ii confera putere, rezistenta si o intelegere spirituala profunda.",["faction:Horde"]="Traditiile samanice care unesc Horde se bazeaza pe elemente, incepand cu rezilienta statornica a pamantului.",["race:Tauren"]="Venerarea Earth Mother este esentiala in cultura tauren, transformand aceasta incercare intr-o celebrare a credintelor stramosesti fundamentale."},sec={{t="Temelia tuturor lucrurilor",b="Call of Earth este un rit formativ pentru un saman care invata sa intre in legatura cu fortele primordiale ale lumii. Pamantul este socotit cel mai indaratnic si mai intelept dintre toate elementele, temelia statornica a existentei. Proba subliniaza ca natura se misca in cicluri deliberate de eroziune si renastere, transformand muntii in deserturi si raurile in canioane de-a lungul nenumaratelor veacuri. Pentru a auzi glasul pamantului, un initiat trebuie sa intruchipeze aceeasi rabdare neclintita."},{t="Sapta si renasterea",b="Raspunsul la aceasta chemare este considerat o renastere spirituala, care il schimba pe cautator in mod irevocabil, facandu-l incapabil sa revina la ignoranta de odinioara. Dupa ce isi dovedeste pregatirea si respectul fata de legile Earth Mother, initiatul primeste un sapta de pamant. Acest elixir special deschide o noua cale a perceptiei, permitandu-i samanului sa patrunda tainele fundamentale ale fortei, rezistentei si protectiei elementale."}},faq={{q="Ce este Call of Earth?",a="Call of Earth este o proba spirituala sacra pentru un shaman aspirant. Ea pune la incercare rabdarea si pregatirea cautatorului de a intra in comuniune directa cu elementul pamantului si de a-i asculta intelepciunea eterna.",al={"ce este Call of Earth","misiunea pamantului pentru Shaman","scopul Call of Earth"}},{q="Ce reprezinta elementul pamantului in traditia samanica?",a="Pamantul este temelia tuturor lucrurilor, intruchipand puterea, rezistenta si rabdarea. Considerat cel mai incapatanat si intelept dintre elemente, ne invata ca toate lucrurile se erodeaza si renasc de-a lungul timpului.",al={"ce reprezinta pamantul","povesti despre elementul pamant","sensul pamantului, samanism"}},{q="Ce este o sapta?",a="O sapta este o licoare elementala pregatita de un mentor saman. Daca o bea sau o accepta, cel care o cauta deschide o cale spirituala, acordandu-si simturile pentru a percepe si a interactiona cu spiritele elementale.",al={"ce este o sapta","sapta pamantului","ce face sapta"}},{q="Cine este Earth Mother pomenita in incercare?",a="Earth Mother este sursa fundamentala a vietii si a echilibrului, venerata mai ales de samanii tauren. Ea ii ocroteste pe cei care-i respecta legile si le da intelepciune mai multa celor care trateaza pamantul cu respect.",al={"cine este Earth Mother","povestea lui Earth Mother","legatura cu Earth Mother"}},{q="Ce se intampla dupa ce raspunzi chemarii?",a="Incheierea acestei etape inseamna ca cel care cauta este pregatit pentru urmatorul pas al caii sale. Reprezinta o renastere spirituala, dupa care un shaman nu se mai poate intoarce la nestiinta, pe masura ce i se dezvaluie noi taine ale pamantului.",al={"ce se intampla dupa ce o termini","dupa call of earth","renasterea prin call of earth"}},{q="De ce este nevoie de rabdare pentru a comunica cu pamantul?",a="Pamantul urmeaza cicluri de eroziune si renastere, in care muntii se transforma treptat in deserturi, iar raurile sapa canioane. Un saman trebuie sa-si stapaneasca rabdarea si rezistenta pentru a se armoniza cu asemenea ritmuri trainice.",al={"de ce pamantul cere rabdare","rabdarea si pamantul"}}},fp="13,291,28.468.0,21.416.0,26.183.0,60.205.0,16.187.0,47.209.0,37.219.0,51.200.0"}
P.entries["quest:152"] = {n="The Coast Isn't Clear",s="De-a lungul tarmului vestic din Westfall, marinarii naufragiati se confrunta cu triburile de murloc de pe plaje. Captain Grayson de la Westfall Lighthouse cere ajutor pentru curatarea coastei, astfel incat supravietuitorii sa poata ajunge in siguranta la tarm.",h="De-a lungul tarmului vestic din Westfall, marinarii naufragiati se confrunta cu triburile de murloc de pe...",kw={"captain grayson","alergator de coasta","marea cea mare","murloc","oracol","naufragii","vanator al mareelor","westfall lighthouse"},ang={["faction:Alliance"]="In lipsa armatei Stormwind din Westfall, People's Militia se straduieste sa protejeze fermele din interiorul tinutului. Apararea coastei le revine unor aliati precum Captain Grayson.",["race:Human"]="Ca Human, stii ca vasele comerciale si pescarii au navigat de multa vreme pe apele din Westfall. Tarmul stapanit de murloci este un semn amar al granitelor pierdute ale regatului."},sec={{t="Un cimitir de corabii",b="Coasta vestica din Westfall a inghitit nenumarate corabii. Recifurile, furtunile naprasnice si stancile colturoase sfarama navele de bancurile de nisip. Supravietuitorii se pot agata de epave si se pot tara pana la tarm, sperand sa fie salvati. Dar triburile de murloc stapanesc plajele si nu au mila de naufragiati."},{t="Santinela fantomatica",b="Captain Grayson ingrijeste Westfall Lighthouse de pe un promontoriu izolat la sud-vest de continent. Moartea l-a legat de post, dar el vegheaza in continuare asupra corabiilor care trec si a marinarilor aflati la nevoie. Murloc fac tarmul ucigas, de la Coastrunner din nord pana la Tidehunter, Warrior si Oracle din sud. Grayson le cere calatorilor sa curete coasta."}},faq={{q="Cine este Captain Grayson?",a="Captain Grayson este capitanul spectral al marii care bantuie Westfall Lighthouse. Inca se simte legat de datoria de a-i proteja pe marinarii care navigheaza prin apele primejdioase si pe cei care supravietuiesc unui naufragiu.",al={"captain grayson","fantoma din far","paznicul farului din westfall"}},{q="De ce vrea Grayson sa curete coasta de murloci?",a="Grayson vrea ca Murloc sa fie alungati, deoarece marinarii naufragiati ajung adesea la tarm de-a lungul coastelor din Westfall. Murloc napadesc plajele de la nord la sud si ii omoara pe supravietuitorii care ajung pe uscat.",al={"de ce ucizi murlocii din westfall","motivul coast isn't clear","de ce cureti coasta"}},{q="Unde se gasesc acesti murloci diferiti?",a="Murloc Coastrunners traiesc de obicei de-a lungul coastei nordice din Westfall. Murloc Warriors, Oracles si Tidehunters se aduna in asezari si tabere de pe plajele sudice.",al={"locatiile murlocilor din westfall","unde se gasesc coastrunners","unde se gasesc tidehunters"}},{q="Este Captain Grayson ostil fata de Alliance sau Horde?",a="Captain Grayson este neutru. Datoria sa fata de marinari trece dincolo de granitele politice, iar el le cere tuturor calatorilor capabili sa ajute la securizarea coastei.",al={"Grayson este prietenos","factiunea lui Grayson","poate Horde sa faca aceasta misiune"}},{q="Trebuie sa reaprinzi mai intai farul pentru aceasta misiune?",a="Nu. Captain Grayson iti cere sa cureti coasta, indiferent daca ai ajutat sau nu la reaprinderea Westfall Lighthouse.",al={"trebuie sa fac mai intai Keeper of the Flame","conditie prealabila pentru Coasta nu e sigura"}},{q="Lucreaza murlocii pentru Defias Brotherhood?",a="Nu. Murloc actioneaza pe cont propriu si ataca pe oricine intra pe terenurile lor de vanatoare de pe tarm. Defias Brotherhood opereaza in apropiere, in regiunea Moonbrook si in golfurile sudice.",al={"sunt defias aliati cu murlocii","legatura dintre defias si murloci"}}},fx={["9a80f3b4"]={q="Ce murloci ameninta tarmul din Westfall?",a="Vanati murlocii care misuna pe plajele vestice din Westfall: Coastrunners dau tarcoale valurilor din nord, alaturi de Warriors, Tidehunters si Oracles, care s-au instalat mai la sud. Acesti pradatori acvatici isi fac cuib printre epavele de pe coasta, pandesc corabiile esuate si ataca pe oricine are nenorocul sa fie adus de valuri la mal.",al={"ce murloci omor","cine sunt murlocii de pe coasta","tinte murloc de pe coasta din Westfall"}},["49634979"]={q="De ce are Captain Grayson nevoie de un aventurier care sa lupte cu murlocii?",a="Captain Grayson este o fantoma nelinistita, legata de stancile pustii ale Westfall Lighthouse. Neputand sa cutreiere singur tarmul si dupa ce garnizoana Stormwindului a parasit regiunea, lasand-o prada banditilor, se bazeaza in intregime pe aventurieri aflati in trecere, precum tine, pentru a apara plajele in numele marinarilor supravietuitori.",al={"de ce nu ucide Grayson murloci","de ce are Grayson nevoie de mine","de ce nu curata garzile coasta"}}},fp="21,199,20.266.0,19.360.0,23.182.0,57.176.0,42.168.0,52.135.0,56.111.0,51.176.0"}
