P.entries["quest:1522"] = {n="Apelul focului",s="Un saman iti vede puterea pe pamant si te trimite la Kranal Fiss in Barrens. El te poate invata caile focului.",h="Un saman iti vede puterea pe pamant si te trimite la Kranal Fiss in Barrens.",kw={"sterile","apel de foc","rascruce de drumuri","pamant","foc","kranal fiss","saman"},ang={["class:Shaman"]="Ca saman, esti trimis la Kranal Fiss pentru a invata caile focului dupa ce ai aratat puterea pe pamant."},sec={{t="Kranal Fiss",b="Kranal locuieste la nord de Crossroads. Samanul spune ca este usor de gasit, dar te avertizeaza sa nu mergi prea departe sau vei ajunge pe taramurile elfilor."}},faq={{q="Cine este Kranal Fiss?",a="Kranal Fiss este un saman din Barrens care va poate invata caile focului",al={"cine e Kranal","Kranal"}},{q="Unde pot gasi Kranal?",a="Kranal locuieste la nord de Crossroads din Barrens.",al={"Locatia Kranal","unde e Kranal"}},{q="De ce sunt trimis la Kranal?",a="Samanul va vede puterea pe pamant si crede ca sunteti gata sa vorbiti cu Kranal, care va poate invata caile focului.",al={"de ce Kranal","antrenament la foc"}}},fp="12,116,11.141.0,19.74.0,24.52.0,30.123.0"}
