P.entries["quest:1581"] = {n="Elixirs for the Bladeleafs"}
P.entries["quest:1582"] = {n="Moonglow Vest"}
P.entries["quest:159"] = {n="Juice Delivery",s="Juice Delivery este o insarcinare intre Darkshire si marginea vestica a Duskwood. Tavernkeep Smitts iti incredinteaza o licoare puternica, cunoscuta drept Zombie Juice, pe care trebuie s-o duci la pustnicul retras Abercrombie. Desi se presupune ca bautura il va tine de cald batranului tremurand, taria ei neobisnuita starneste mirarea.",h="Juice Delivery este o insarcinare intre Darkshire si marginea vestica a Duskwood.",kw={"abercrombie","darkshire","duskwood","juice delivery","scarlet raven","tavernkeep smitts","zombie juice"},ang={["faction:Alliance"]="Cetatenii din Darkshire se bazeaza pe curieri curajosi ai Alliance pentru a strabate drumurile pline de primejdii din Duskwood, desi increderea acordata oricarui pustnic din padure poate duce la necazuri neasteptate.",["profession:Cooking"]="Reteta lui Tavernkeep Smitts pentru Zombie Juice se bazeaza in mare masura pe ingrediente intepatoare si neobisnuite, punand la incercare limitele a ceea ce poate fi numit bautura de taverna."},sec={{t="Un amestec indoielnic",b="Tavernkeep Smitts din Darkshire prepara o bautura legendara, cunoscuta colocvial drept Zombie Juice. Cand comanda este in sfarsit gata, Smitts ii intinde sticla cu un avertisment sever sa o manuiasca cu grija, remarcand ca licoarea e suficient de tare incat sa-i ridice pe morti. Pentru un aventurier obosit, care face comisioane printr-o padure bantuita, livrarea unei bauturi spirtoase de mare tarie unui singuratic excentric pare un gest caritabil obisnuit."},{t="Greseala pustnicului",b="Ducand bautura exploziva spre vest, trecand pe langa worgenii urlatori si mortii nelinistiti, ajungi direct la coliba lui Abercrombie, de la marginea padurii. Dupa ce primeste sticla, pustnicul firav pretinde ca are nevoie de bautura doar ca sa-si incalzeasca oasele dureroase in noptile inghetate si innecate in ceata din Duskwood. Totusi, cand o ia in primire, aproape ca-i multumeste calatorului pentru 'neghiobie', apoi se grabeste sa se corecteze si sa-i laude 'bunatatea' - o scapare de-o clipa, care sugereaza ca in mintea pustnicului se petrece mult mai mult decat pregatirea unei bauturi de seara."}},faq={{q="Ce este Zombie Juice?",a="Zombie Juice este o bãuturã extrem de tare, preparatã de Tavernkeep Smitts la Scarlet Raven Tavern din Darkshire. Desi este consideratã o bãuturã alcoolicã puternicã, Smitts spune cã e suficient de tare ca sã-i trezeascã si pe morti, ceea ce o face mult mai volatilã decat tãriile obisnuite.",al={"povestea sucului de zombie","ce este sucul lui Smitts","bautura lui Abercrombie"}},{q="Cine comanda Zombie Juice?",a="Abercrombie, un batran pustnic excentric care locuieste intr-o coliba izolata, aproape de granita vestica a Duskwood, a solicitat livrarea.",al={"cine vrea sucul","pentru cine este juice delivery"}},{q="De ce doreste Abercrombie bautura?",a="Abercrombie sustine ca are nevoie de bautura ca sa se incalzeasca in noptile umede si geroase din Duskwood. Totusi, scaparea lui de la gura, cand primeste sticla, sugereaza ca are planuri mult mai sinistre pentru licoare.",al={"de ce are abercrombie nevoie de suc","raceala lui abercrombie"}},{q="Cine prepara Zombie Juice?",a="Tavernkeep Smitts, hangiul care administreaza Scarlet Raven Tavern, in inima Darkshire, prepara personal bautura, cu conditia sa primeasca ingredientele intepatoare necesare.",al={"cine face bautura de zombi","barmanul Smitts"}},{q="Unde este coliba lui Abercrombie?",a="Coliba lui Abercrombie se afla izolata in vestul tinutului Duskwood, chiar la nord de Raven Hill Cemetery.",al={"locatia lui Abercrombie","unde este coliba lui Abercrombie"}},{q="Ce face Abercrombie in continuare dupa ce primeste sucul?",a="Dupa ce obtine Zombie Juice, Abercrombie continua sa profite de calatorii creduli, trimitandu-i in Raven Hill Cemetery sa adune coaste de ghoul pentru o efigie macabra despre care pretinde ca va tine strigoii la distanta.",al={"urmatoarea misiune dupa Juice Delivery","ce se intampla in continuare"}}},fx={["9f2016f2"]={q="De ce vrea Tavernkeep Smitts ca sucul sa fie livrat?",a="Smitts administreaza Scarlet Raven Tavern din Darkshire si si-a incheiat partea sa din intelegere, preparand licoarea puternica ceruta de Abercrombie. Bautura este imbuteliata si gata, iar singurul sau interes este sa vada ca se respecta comanda promisa si ca aceasta ii este luata de pe maini. Pe parcurs, te avertizeaza sa manevrezi cu grija bautura volatila.",al={"de ce vrea Smitts sa se faca acest lucru","motivul lui Tavernkeep Smitts","de ce sa livrezi suc de zombie"}},["6bab1f80"]={q="De ce pune Smitts un aventurier sa livreze sucul in loc sa mearga el insusi?",a="Tavernkeep Smitts trebuie sa se ocupe de barul de la Scarlet Raven Tavern, iar sa rataceasca pe drumurile intunecate din Duskwood este mult prea primejdios pentru un hangiu obisnuit. Schitul lui Abercrombie se afla dincolo de padurile umbrite, langa Raven Hill, intr-o zona plina de strigoi si fiare salbatice, pe care numai un calator inarmat o poate strabate in siguranta.",al={"de ce eu, Smitts","de ce nu poate Smitts sa livreze sucul","de ce nu merge hangiul"}}},fp="14,317,20.410.0,17.548.1,21.267.0,28.133.0,36.222.0,27.171.0,29.89.0,56.205.0"}
P.entries["quest:1598"] = {n="The Stolen Tome",s="In Northshire Valley, un warlock novice Human este trimis sa recupereze un tom interzis si sa-si dovedeasca priceperea. Drusilla La Salle spera sa obtina Powers of the Void de la Defias, al caror tabara se afla in vii.",h="In Northshire Valley, un warlock novice Human este trimis sa recupereze un tom interzis si sa-si dovedeasca...",kw={"defias brotherhood","drusilla la salle","northshire abbey","hot de rand","powers of the void","carte furata","podgorii","imp al warlockului"},ang={["class:Warlock"]="Ca Warlock, dovedesti ca poti traversa terenuri periculoase fara sa te clintesti. Daca pui mana pe tom, vei invata ritualurile necesare pentru a-ti chema primul imp.",["faction:Alliance"]="Ca membru al Alliance, trebuie sa te strecori cu grija pe langa paladinii si clericii din Northshire, folosindu-te de greselile proscrisilor pentru a pune mana pe cunostinte oculte restrictionate.",["race:Human"]="Ca human, vezi cat de departe ajunge Defias Brotherhood in Northshire, unde chiar si elevii manastirii fura texte sacre si se alatura insurectiei."},sec={{t="O oportunitate interzisa",b="Warlock din tinuturile Stormwind isi ascund mestesugul si isi feresc cercetarile de privirile iscoditoare. Northshire Abbey pazeste grimoriile interzise in arhivele sale. Drusilla La Salle, indrumatoarea Warlock de pe domeniul abatiei, ravneste la Powers of the Void, dar nu-si poate risca intrarea in aripa protejata a bibliotecii, ca sa nu starneasca suspiciunile clericilor si ale celor din ordinul Paladin."},{t="Oportunismul Defias",b="Un novice de la manastire se alatura Defias Brotherhood si fura mai multe texte de mare valoare inainte sa plece. Fuge la Northshire Vineyards si se refugiaza in apropierea taberei Defias. Hotii isi ascund prada intr-un cort de campanie, fara sa stie ce pericol ascund artele intunecate din carte."},{t="Prima Binding",b="Recuperarea tomului pune la incercare curajul unui warlock novice si deschide calea catre cunoasterea intunecata. Infruntarea taberei de banditi si intoarcerea cu textul indeplinesc ambitia Drusillei si dovedesc ca discipolul este pregatit. Ea il rasplateste cu ritualurile intunecate necesare pentru a invoca si a supune un imp, primul demon pe care un ucenic invata sa-l controleze."}},faq={{q="Ce inseamna Powers of the Void?",a="Powers of the Void este un grimoar interzis despre magia intunecata si controlul planurilor. Pastrat intr-o aripa pazita a bibliotecii de la Northshire Abbey, contine cunostinte pe care Drusilla La Salle le doreste pentru studiile si invataturile sale.",al={"powers of the void carte","ce este cartea","ce a furat novicele"}},{q="De ce nu a furat Drusilla La Salle cartea ea insasi?",a="Drusilla La Salle trebuie sa-si protejeze reputatia la Northshire Abbey. Daca ar intra in arhivele securizate ale bibliotecii, i-ar alerta pe clerici. Cand un novice a furat tomul si s-a alaturat Defias, ea a avut ocazia sa puna mana pe el fara sa-si compromita pozitia, prin intermediul unui ucenic.",al={"de ce nu l-a furat Drusilla","de ce sa ma trimita pe mine"}},{q="Unde este ascuns volumul furat?",a="Defias au ascuns tomul intr-un cort din tabara lor din Northshire Vineyards, la est de abatie.",al={"unde este cartea","locatia tomului","cortul cu tomul furat"}},{q="De ce s-a alaturat un novice din Northshire Defias Brotherhood?",a="Nemultumirea si conflictele din tot regatul ii imping pe muncitori, fermieri si studenti ai bisericii sa se alature Defias Brotherhood. Novicele si-a abandonat juramintele, a furat cateva carti importante din biblioteca, apoi a fugit la banditii din vie.",al={"de ce s-a alaturat Novice factiunii Defias","tradatorul din abatie, Defias","cine a furat cartea"}},{q="Ce recompensa primeste un Warlock pentru recuperarea tomului?",a="Inapoierea tomului dovedeste ca elevul are curajul si rezistenta necesare pentru a practica artele intunecate. Drusilla il rasplateste pe ucenic cu invataturile necesare pentru a invoca un imp, primul sau demon.",al={"ce inveti","recompensa misiunii de Warlock","de ce sa faci aceasta misiune"}},{q="Stiu membrii Defias sa foloseasca aceasta carte?",a="Banditii privesc cartile furate ca pe o prada valoroasa de la manastire. Desi Defias angajeaza vrajitori renegati, novicele si tovarasii sai au varat tomul intr-o lada din cort, in loc sa-i stapaneasca secretele intunecate.",al={"pot defias folosi tomul","ce fac defias cu cartea"}}},fx={["1f0061ae"]={q="De ce vrea Drusilla La Salle Powers of the Void?",a="Drusilla a ravnit indelung la cunoasterea interzisa ascunsa in Powers of the Void, dar aceasta era pastrata intr-o aripa securizata si protejata a bibliotecii din Northshire Abbey, unde nu putea ajunge fara sa atraga banuieli. Faptul ca a pus un novice ratacit s-o fure i-a oferit ocazia perfecta de a pune in sfarsit mana pe secretele intunecate si, in acelasi timp, de a-ti pune la incercare taria de a studia artele vrajitoriei.",al={"de ce vrea drusilla cartea","motivul lui drusilla la salle","de ce sa furi tomul"}},a46315b9={q="Impotriva cui esti trimis pentru a recupera tomul?",a="Esti trimis impotriva banditilor Defias Brotherhood, aflati in tabara din Northshire Vineyards. Un novice ratacitor de la manastire a furat mai multe volume valoroase din biblioteca protejata, apoi a fugit sa li se alature rebelilor si a ascuns tomul printre corturile lor.",al={"cine a luat cartea","defias in podgorii","cine a furat Powers of the Void"}}},fp="15,206,23.341.0,18.270.0,17.315.0,31.215.0,52.243.0,32.99.0,56.231.0,55.179.0,39.219.0"}
P.entries["quest:16"] = {n="Give Gerard a Drink",s="La Maclure Vineyards, Gerard Tiller munceste zile intregi pe camp si are nevoie de apa proaspata de izvor. Da mere la schimb pentru apa adusa de calatorii aflati in trecere.",h="La Maclure Vineyards, Gerard Tiller munceste zile intregi pe camp si are nevoie de apa proaspata de izvor.",kw={"mere","troc","Elwynn Forest","Gerard Tiller","podgoriile Maclure","apa de izvor racoritoare"},ang={["faction:Alliance"]="Sprijinirea fermierilor din Elwynn in locuri precum Maclure Vineyards ajuta la aprovizionarea gospodariilor si garnizoanelor din padure, in timp ce regatul se apara.",["race:Human"]="Ca Human care incepe in Northshire, ajutorul dat vecinilor precum Gerard Tiller arata spiritul comunitar care tine Elwynn unit."},sec={{t="Munca insetata pe campurile cu vita-de-vie",b="Fermele din Elwynn Forest furnizeaza cereale, fructe si legume locuitorilor si garnizoanelor din Stormwind. Cultivarea pamantului sub cerul liber este o munca fierbinte si istovitoare. Gerard Tiller petrece zile lungi cu mainile in pamant la Maclure Vineyards, tinand daunatorii la distanta si ingrijind recolta. Pentru ca are prea putin timp sa mearga la fantanile din oras, se bazeaza pe recruti aflati in trecere, care ii aduc apa curata de izvor ca sa-si poata continua munca."},{t="Economia trocului",b="Gerard face troc cu provizii in loc de monede. Calatorii cu flacoane in plus de Refreshing Spring Water le pot schimba pe mere proaspete din livada. Regatul isi intinde resursele ca sa mentina ordinea si sa-si hraneasca armata, asa ca trocul direct intre micii proprietari de pamant si recruti ramane o modalitate practica de a se descurca in Elwynn rural."}},faq={{q="Cine este Gerard Tiller?",a="Gerard Tiller este fermier la Maclure Vineyards, in sudul tinutului Elwynn Forest. El ingrijeste campurile si livezile care aprovizioneaza locuitorii din zona.",al={"Gerard Tiller","cine este Tiller","Gerard"}},{q="De ce are Gerard nevoie de apa?",a="Sa muncesti toata ziua pe campuri, sub soare, este istovitor. Gerard se bazeaza pe calatorii aflati in trecere pentru apa proaspata de izvor, ca sa se poata hidrata fara sa-si intrerupa treburile.",al={"de ce apa de izvor","ii este sete lui gerard","de ce are nevoie de bautura"}},{q="Unde se gaseste Refreshing Spring Water?",a="Negustorii de mancare si bautura si hangiii din Elwynn Forest vand de obicei Refreshing Spring Water. Brother Danil o vinde in interiorul Northshire Abbey.",al={"unde gasesc apa","sursa apei de izvor","cum obtin apa"}},{q="Se poate repeta acest schimb?",a="Da. Gerard continua sa lucreze pe camp si va schimba mere proaspete din livada pe sticle de apa in plus, daca ai de prisos.",al={"misiune repetabila","pot face asta din nou","preda mai multa apa"}},{q="Ce ofera Gerard in schimbul bauturii?",a="Gerard da un Mar Rosu Stralucitor la schimb pentru apa proaspata.",al={"recompensa lui Gerard","ce primesc","recompensa trocului"}},{q="Unde se afla Gerard?",a="Gerard se afla in afara hambarului de la Maclure Vineyards, in sudul Elwynn Forest.",al={"locatia lui Gerard Tiller","unde este Gerard","unde este ferma"}}},fx={d51fec31={q="La ce se foloseste Apa de Izvor Racoritoare?",a="Munca la campurile din Maclure Vineyards este istovitoare, iar Gerard Tiller are nevoie doar de o rezerva sigura de apa proaspata si curata, ca sa-si potoleasca setea in timp ce lucreaza sub soare. In loc sa-si lase recoltele nesupravegheate ca sa-si aduca singur apa, se bucura sa faca troc cu calatorii care au ceva in plus.",al={"utilizarea apei de izvor racoritoare","de ce apa de izvor","apa de izvor a lui gerard"}}},fp="19,156,35.392.0,21.324.0,21.139.0,27.168.0,43.149.0,25.113.0,47.48.0,24.78.0"}
P.entries["quest:160"] = {n="Note to the Mayor",s="Note to the Mayor este o misiune a Alliance din Duskwood, care il leaga pe excentricul pustnic Abercrombie de conducerea din Darkshire. Dupa ce-l ajuta pe batranul retras, aventurierilor li se cere sa-i inmaneze personal un mesaj primarului Lord Ello Ebonlocke. Totusi, scrisoarea trezeste imediat suspiciune, nu simpatie.",h="Note to the Mayor este o misiune a Alliance din Duskwood, care il leaga pe excentricul pustnic Abercrombie de...",kw={"Abercrombie","Darkshire","Duskwood","Ello Ebonlocke","scrisoare","primar","nota pentru primar"},ang={["faction:Alliance"]="Supravietuirea din Darkshire depinde de descifrarea tulburarilor stranii inainte ca acestea sa treaca de perimetrul Night Watch, ceea ce face din aceasta scrisoare suspecta o problema urgenta de securitate pentru agentii Alliance.",["race:Human"]="Curierii Human care slujesc Night Watch si casa Ebonlocke isi dau repede seama ca batranul si ciudatul pustnic de la marginea Duskwood i-a inselat."},sec={{t="Un mesaj prietenos?",b="Dupa ce-l ajuti pe Abercrombie sa-si recupereze cufarul furat de ogrii din Vul'Gol Ogre Mound, sihastrul te trimite inapoi pe drumurile invaluite in ceata, spre oras. Ranjind de incantare, Abercrombie sustine ca el si primarul Lord Ello Ebonlocke sunt vechi prieteni. Insista ca, atunci cand va afla ce a reusit aventurierul sa faca, primarul va fi la fel de incantat ca si el."},{t="Conducere nedumerita",b="La sosirea in primaria din Darkshire, realitatea contrazice afirmatiile lui Abercrombie. Lord Ello Ebonlocke nu-si aminteste de nimeni pe nume Abercrombie. Desfacerea pergamentului nu face decat sa adanceasca misterul: departe de a fi un salut calduros intre vechi tovarasi, textul este scris intr-un alfabet stravechi si indescifrabil, care il lasa complet nedumerit pe primarul din Darkshire."}},faq={{q="Cine trimite Note to the Mayor?",a="Abercrombie, un pustnic excentric care traieste intr-o coliba singuratica la marginea vestica a Duskwood, iti da scrisoarea dupa ce ii recuperezi bunurile furate de ogrii din zona.",al={"cine ii da biletul primarului","cine incepe misiunea bilet pentru primar","expeditorul scrisorii lui abercrombie"}},{q="Sunt Abercrombie si primarul Ebonlocke cu adevarat prieteni?",a="Nu. Desi Abercrombie sustine ca sunt vechi cunostinte, primarul Lord Ello Ebonlocke nu a auzit niciodata de el si isi exprima uluirea deplina la primirea mesajului.",al={"se cunosc","este abercrombie prieten cu primarul","relatia dintre abercrombie si ello ebonlocke"}},{q="Ce scrie in bilet?",a="Nota este scrisa intr-o limba straveche si obscura, pe care nici curierul, nici primarul Ebonlocke nu o pot descifra, asa ca primarul cauta ajutor pentru traducere.",al={"ce scrie in nota lui abercrombie","poate ello sa citeasca nota","in ce limba este scrisoarea"}},{q="Unde se afla Lord Ello Ebonlocke?",a="Primarul Lord Ello Ebonlocke se afla in Darkshire Town Hall, in partea de est a orasului, de-a lungul drumului principal din Duskwood.",al={"unde este primarul","locatia lui Ello Ebonlocke","unde predau biletul pentru primar"}},{q="Ce se intampla dupa ce primarul Ebonlocke primeste scrisoarea?",a="Deoarece Lord Ebonlocke nu poate citi scrierea misterioasa, iti cere sa gasesti pe cineva care poate interpreta textul, ceea ce duce la misiunea Translate Abercrombie's Note.",al={"ce urmeaza dupa note to the mayor"}},{q="De ce radea Abercrombie cand ti-a dat scrisoarea?",a="Rasul incantat al lui Abercrombie sugereaza ca intentiile sale sunt cu mult mai intunecate decat o simpla revedere cu o veche cunostinta, prevestind necazuri sinistre pentru Darkshire.",al={"de ce rade Abercrombie","Abercrombie este rau","nota despre rasul lui Abercrombie"}}},fx={["7816d016"]={q="De ce te trimite Abercrombie cu scrisoarea in loc sa o duca el insusi?",a="Abercrombie traieste ca un pustnic firav si singuratic, izolat in padurile bantuite departe, la vest de Darkshire. Trimitandu-si mesajul printr-un calator care tocmai l-a ajutat, fara sa banuiasca nimic, isi poate transmite surpriza sumbra direct la primaria orasului, fara sa puna piciorul in apropierea Night Watch din Darkshire sau a consiliului local, de care se fereste.",al={"de ce sa-i duc biletul primarului","de ce nu livreaza abercrombie scrisoarea","de ce e pus jucatorul sa livreze scrisoarea"}}},fp="17,319,19.373.0,18.368.1,32.178.0,53.164.0,28.159.0,37.126.0,55.168.0,57.165.1"}
P.entries["quest:1618"] = {n="Gearing Redridge",s="Gearing Redridge este o misiune de fierarie a Alliance oferita de Tormus Deepforge in Ironforge. Fierarii aspiranti forjeaza echipamente trainice din cupru pentru a sprijini garnizoana asediata din Lakeshire si a-l ajuta pe fierarul local Verner Osgood sa apere regiunea de orcii si gnoll-ii ostili.",h="Gearing Redridge este o misiune de fierarie a Alliance oferita de Tormus Deepforge in Ironforge.",kw={"orci blackrock","fierarie","gnoli","baros greu de cupru","lakeshire","redridge","centura de cupru runata","stonewatch","tormus deepforge","verner osgood"},ang={["faction:Alliance"]="Livrarea ilustreaza ajutorul reciproc esential dintre Ironforge si asezarile umane greu incercate din sud, venind in ajutor acolo unde conducerea dezbinata din Stormwind a ramas in urma.",["profession:Blacksmithing"]="Aceasta sarcina marcheaza un ritual de trecere pentru fierarii ucenici, punandu-ti la incercare capacitatea de a produce in masa arme rezistente si armuri de protectie, la cerere, pentru un front de lupta activ.",["race:Dwarf"]="Mestesugul piticilor sta la baza efortului de razboi al Alliance, iar Tormus se asigura ca maestrii din Ironforge isi folosesc talentul pentru a-si ajuta aliatii aflati la ananghie.",["race:Human"]="Pentru oamenii regatelor sudice, primirea unor lucrari metalice faurite in Khaz Modan le ofera ajutorul atat de necesar impotriva ramasitelor agresive ale Blackrock."},sec={{t="Un apel intre regate",b="Desi Great Forge din Ironforge rareori se odihneste, fierarii pitici stiu ca luptele de pe linia intai a Alliance se intind mult dincolo de Dun Morogh. In Redridge Mountains, asezarea umana Lakeshire se afla in permanenta sub asediu, fiind tinta incursiunilor regulate ale orcilor Blackrock care pornesc din Stonewatch Keep si a haitelor de gnolli care infesteaza crestele nordice. Cum intaririle regale din Stormwind sosesc greu, proviziile locale raman periculos de putine."},{t="Nicovalele din Lakeshire",b="Fierarul din Lakeshire, Verner Osgood, lucreaza aproape singur la forja sa in aer liber, incercand sa repare armuri zdrobite si sa inlocuiasca arme rupte. Vazand povara de pe umerii omologului sau uman, Tormus Deepforge le cere fierarilor in formare sa livreze direct in Lakeshire patru centuri din cupru runic si patru ciocane grele din cupru. In schimbul intaririi rezervelor de aparare ale militiei, Verner le impartaseste cu placere calatorilor mestesugari tehnici de comert mai rafinate."}},faq={{q="Cine incepe misiunea Gearing Redridge?",a="Tormus Deepforge, un fierar pitic de la Great Forge din Ironforge, le ofera aceasta misiune fierarilor Alliance care au atins un nivel suficient de pricepere in meseria lor.",al={"cel care da misiunea Gearing Redridge","cine da misiunea Gearing Redridge","misiunea lui Tormus"}},{q="De ce are Lakeshire nevoie de arme si armuri din Ironforge?",a="Lakeshire este atacat necontenit de orcii din Blackrock care ocupa Stonewatch Keep, precum si de gnolii locali agresivi. Singurul fierar al orasului, Verner Osgood, este coplesit de reparatia armelor si faurirea armurilor pentru militie.",al={"de ce are Redridge nevoie de echipament","de ce are Lakeshire nevoie de arme","lipsa de provizii in Redridge"}},{q="Cine primeste transportul in Redridge?",a="Transportul este livrat lui Verner Osgood, fierarul local aflat langa forja din orasul de pe malul lacului, Lakeshire.",al={"unde predau misiunea Gearing Redridge","locatia lui Verner Osgood","predarea misiunii la fierarul din Redridge"}},{q="Ce echipament trebuie faurit pentru aceasta sarcina?",a="Trebuie sa aduci patru centuri din cupru runic si patru ciocane grele din cupru. Acestea dovedesc atat maiestria in confectionarea armurii, cat si priceperea in faurirea armelor grele.",al={"obiecte necesare pentru Gearing Redridge","materiale pentru Gearing Redridge","ce sa confectionez pentru Tormus"}},{q="Ce amenintari tulbura Redridge in aceasta perioada?",a="Principalele pericole care ameninta Lakeshire sunt clanurile de orci Blackrock, care se intaresc in Stonewatch Keep, si haitele violente de gnoll care dau tarcoale poalelor nordice ale muntilor.",al={"dusmanii din Redridge","cine ataca Lakeshire","amenintarile din Redridge"}},{q="Ce recompensa ofera Verner Osgood in schimb?",a="Scapat de povara agitata de a echipa de la zero fiecare strajer, Verner isi face timp sa te invete tehnici avansate de fierarie.",al={"pregatirea lui verner osgood","recompensa pentru gearing redridge","ce primesc"}}},fx={ba6aca96={q="De ce vrea Tormus Deepforge ca acest lucru sa fie facut?",a="Tormus Deepforge intelege ca aliatii umani din Ironforge sunt greu incercati si isi duc propriile lupte disperate. In timp ce Blackrock clan lanseaza raiduri neincetate asupra Lakeshire, Tormus incearca sa intareasca legaturile dintre dwarves si oameni, oferindu-i ajutor esential in fierarie unui aliat coplesit de greutati.",al={"de ce sa ajuti Redridge","motivul lui Tormus Deepforge","de ce sa trimiti provizii la Redridge"}},e26bdf46={q="La ce foloseste Runed Copper Belt?",a="Aceste curele vrajite ofera o intarire esentiala armurii aparatorilor din Lakeshire. Cum fierarii locali sunt coplesiti de repararea echipamentului stricat, curelele rezistente, mestesugite cu grija, ii ajuta sa-i protejeze pe gardienii orasului si pe membrii militiei in confruntarile neintrerupte cu orcii Blackrock si gnolii.",al={"la ce foloseste cureaua de cupru runica","de ce curele de cupru runice","scopul curelei de cupru runice"}},["61555f3e"]={q="La ce foloseste Heavy Copper Maul?",a="Ciocanele grele din cupru le ofera aparatorilor din prima linie a Lakeshire arme rezistente si devastatoare. Aparatorii din Redridge se confrunta fara incetare cu orci Blackrock inarmati si gnolli Redridge vigurosi, asa ca armele grele, cu cap bont, sunt indispensabile efortului lor de razboi.",al={"scopul barosului greu din cupru","de ce baroase grele din cupru","baros greu din cupru redridge"}},["330fd0fb"]={q="De ce are nevoie Tormus Deepforge de tine, in loc sa le livreze el insusi?",a="Tormus este un fierar iscusit, care instruieste ucenici si administreaza Great Forge of Ironforge, o functie esentiala pe care nu o poate parasi pentru a calatori in tinuturile oamenilor. Incredintarea transportului unui fierar aspirant ii ajuta pe aliatii acestora si iti da totodata prilejul sa inveti tehnici de mestesugarit de la Verner Osgood.",al={"de ce ma trimit la Redridge","de ce nu poate Tormus sa livreze","de ce eu pentru Gearing Redridge"}}},fp="16,277,22.481.0,23.464.0,38.157.0,57.240.0,38.124.0,43.144.0,49.188.0,47.146.0"}
P.entries["quest:162"] = {n="Rise of the Silithid",s="Senior Surveyor Fizzledowser te indeamna sa duci raportul despre amenintarea insectelor la Gracina Spiritmight, o invatata si istoric night elf din Darnassus.",h="Senior Surveyor Fizzledowser te indeamna sa duci raportul despre amenintarea insectelor la Gracina...",kw={"darnassus","fizzledowser","gracina","analiza insectelor","silithid","spiritmight","tanaris","temple of the moon"},sec={{t="Un invatat in Darnassus",b="Fizzledowser vrea ca raportul sa ajunga la cineva care cunoaste bine asemenea chestiuni. Gracina Spiritmight este o invatata night elf care a petrecut mult timp studiind formele de viata specifice ecosistemului din Azeroth si este, de asemenea, istoric. Fizzledowser spera ca ea va putea stabili care este cu adevarat pericolul si, mai presus de toate, cum ar putea fi oprit. Din cate stia Fizzledowser, ea locuia in Temple of the Moon din Darnassus."},{t="Raspunsul Gracinei",b="Gracina spune ca night elves cunosc groaza descrisa in raport si crede ca Fizzledowser a facut bine trimitandu-l, impreuna cu tine. Aceste creaturi vor devora repede desertul Tanaris si se numara printre cele mai mari amenintari cu care se va confrunta cineva. Sunt silithid, uneltele uneia dintre cele mai cumplite amenintari la adresa Horde si Alliance deopotriva. Gracina deplange faptul ca nimeni nu a fost destul de intelept ca sa-si dea seama mai devreme."}},faq={{q="Cine este Gracina Spiritmight?",a="Un invatat si istoric Night Elf, care a petrecut mult timp studiind formele de viata specifice ecosistemului din Azeroth.",al={"povestea lui Gracina Spiritmight","cine este Gracina","carturara din Temple of the Moon"}},{q="Cine te trimite la Gracina?",a="Senior Surveyor Fizzledowser iti da raportul de analiza a insectelor si iti cere sa i-l duci.",al={"de unde provine raportul","originea raportului de analiza a insectelor"}},{q="Unde poate fi gasita Gracina Spiritmight?",a="In Temple of the Moon din Darnassus, dupa ultimul cuvant al lui Fizzledowser.",al={"unde este gracina","locatia lui gracina spiritmight","gaseste-l pe gracina spiritmight"}},{q="Ce a precedat aceasta calatorie spre Darnassus?",a="Urmeaza Insect Part Analysis.",al={"misiunea precedenta","ce a dus la rise of the silithid","misiunea anterioara pentru gracina"}}},fp="20,151,22.429.0,16.395.1,27.122.0,25.97.0,39.68.0,43.32.0"}
P.entries["quest:163"] = {n="Raven Hill",s="Zvonurile despre umbre schimbatoare si lumina tremuranda la ferestrele asezarii parasite Raven Hill au pus Night Watch in alerta. La porunca lui Elaine Carevin din Darkshire, calatorii sunt trimisi spre vest, prin padurile bantuite, sa infrunte prezenta sinistra care s-a adapostit printre ruine.",h="Zvonurile despre umbre schimbatoare si lumina tremuranda la ferestrele asezarii parasite Raven Hill au pus...",kw={"calor","darkshire","duskwood","elaine carevin","jitters","night watch","raven hill"},ang={["class:Paladin"]="Pregatit sa vaneze mortii-vii nelinistiti care bantuie cimitirul invecinat, un paladin care cerceteaza relatari despre aparitii sinistre l-ar putea descoperi, pe neasteptate, pe Jitters, un om viu si tremurand de frica.",["faction:Alliance"]="Night Watch din Duskwood primeste putin spre deloc ajutor din partea garnizoanei din Stormwind, fiind nevoita sa se bazeze pe eroi calatori din Alliance pentru a cerceta amenintarile sinistre din colturile ruinate ale tinutului."},sec={{t="Ochi in vest",b="Pentru rangerii din Night Watch, marginea vestica indepartata din Duskwood a fost de multa vreme lasata in stapanirea mortilor si a salbaticiei. Insa o parasire totala ar fi fost de preferat activitatii neasteptate. Calor, un strajer care patruleaza drumurile mohorate, a observat timp de doua nopti la rand miscare printre casele tacute din Raven Hill, insotita de licarirea tulburatoare a unui felinar intr-o fereastra. Intr-un tinut bantuit de ghoul-i, schelete si bestii, orice semn inexplicabil de viata trebuie cercetat fara intarziere."},{t="Un pustnic tulburat",b="Cei care se asteapta sa se lupte cu un demon aparut din senin sau cu un razboinic mort-viu in Raven Hill descopera o realitate mult mai jalnica. Ghemuit de groaza printre ruinele darapanate se afla Jitters, un vagabond complet debusolat, care tremura la fiecare fosnet din intuneric. In timp ce protesteaza frenetic ca nu exista nicio amenintare in afara de 'harmless Jitters', delirul sau febril sugereaza ca stie mult mai multe despre cosmarul care mistuie Duskwood decat indrazneste sa spuna."}},faq={{q="Cine te trimite sa investighezi Raven Hill?",a="Elaine Carevin, o locuitoare din Darkshire care o ajuta pe Night Watch, le cere calatorilor carora le pasa de siguranta din Duskwood sa cerceteze aparitiile tulburatoare semnalate in vest.",al={"cine ofera misiunea de la raven hill","cine da misiunea de la raven hill","misiunea lui elaine carevin"}},{q="Ce a vazut de fapt Calor in Raven Hill?",a="Calor a raportat ca a vazut umbre miscandu-se in asezarea abandonata doua nopti la rand, precum si o lanterna sau lumanare arzand la una dintre ferestrele cladirilor, in noaptea de dinainte.",al={"ce a vazut calor","observatia lui calor in raven hill","umbrele din raven hill"}},{q="Ce monstru bantuie ruinele?",a="Tocmai asta esti trimis sa descoperi. Calor a zarit doar umbre in miscare si o lumina la fereastra; orice s-ar ascunde in cladirile parasite din Raven Hill trebuie gasit de aproape.",al={"cine bantuie raven hill","ce se afla in raven hill","este real monstrul din raven hill"}},{q="Cine este Jitters?",a="Jitters este un vagabond sperios si paranoic, care traieste ingrozit in vestul Duskwood. Desi pretinde ca e cu totul inofensiv, vinovatia sa apasatoare si vorbele agitate sugereaza ca e amestecat in misterele mai intunecate ale regiunii.",al={"povestea lui jitters","cine este jitters din duskwood","de ce se ascunde jitters"}},{q="Unde se afla Raven Hill?",a="Raven Hill se afla in partea indepartata de vest a Duskwood, chiar la sud de cimitirul urias, napadit de strigoi, care ii poarta numele.",al={"locatia Raven Hill","unde gasesc Raven Hill","harta Raven Hill"}},{q="De ce este Night Watch atat de ingrijorata de umbrele miscatoare?",a="Darkshire abia face fata rascoalelor scheletice, worgenilor salbatici si paianjenilor panditori. Orice semn de miscare organizata sau locuitori neobisnuiti in vestul parasit ar putea prevesti un atac asupra asezarilor locuite ramase.",al={"de ce le pasa de raven hill","night watch si raven hill"}}},fx={["2c575d43"]={q="De ce vrea Elaine Carevin ca Raven Hill sa fie investigat?",a="Elaine Carevin este hotarata sa pastreze siguranta in Duskwood. Cum Night Watch este deja coplesita de ororile care se strecoara prin paduri, luminile stranii si umbrele miscatoare din asezarea parasita Raven Hill nu pot fi ignorate. Are nevoie de cineva care sa afle daca o noua amenintare prinde radacini la marginea vestica a tinutului.",al={"de ce te trimite Elaine","motivul lui Elaine Carevin","de ce investighezi Raven Hill"}},["2a1c77d7"]={q="De ce ii cere Elaine Carevin ajutor unui aventurier in locul celor din Night Watch?",a="Night Watch este periculos de slabita numeric si abia reuseste sa apere imprejurimile Darkshire si sa pazeasca drumurile. Cu toti aparatorii apti de lupta ocupati sa tina piept strigoilor, paianjenilor si worgenilor, Elaine se bazeaza pe calatori capabili, dispusi sa se aventureze in ruinele paraginite din Raven Hill.",al={"de ce eu la raven hill","de ce nu trimite elaine pe cei din night watch","de ce sa ceara ajutorul unui aventurier"}}},fp="10,297,16.493.0,16.438.1,40.178.0,42.178.0,35.190.1,15.230.1,28.138.0,57.237.0"}
P.entries["quest:1638"] = {n="A Warrior's Training",s="In Goldshire, A Warrior's Training ii trimite pe tinerii Warrior la Stormwind, ca sa invete sa reziste pe campul de lupta. Lyria Du Lac ii indruma catre Pig and Whistle Tavern din Old Town, unde veteranul Harry Burlguard le ofera o instruire experimentata.",h="In Goldshire, A Warrior's Training ii trimite pe tinerii Warrior la Stormwind, ca sa invete sa reziste pe...",kw={"Bartleby","Goldshire","Harry Burlguard","Lyria Du Lac","Old Town","Pig and Whistle","Stormwind","antrenament","Warrior"},ang={["class:Warrior"]="Ca Warrior, acest rit marcheaza trecerea de la recrut al militiei locale la soldat recunoscut oficial de Alliance. Deschide calea catre posturi avansate si tehnici defensive.",["faction:Alliance"]="In calitate de recrut Alliance, poti duce intelepciunea practica despre lupte corp la corp, invatata de la veterani precum Harry Burlguard, spre granitele disputate, alaturi de tacticile invatate din carti.",["race:Human"]="Ca luptator Human, drumul tau duce de la apararea pastorala din Elwynn pana in Old Town, leaganul ancestral al traditiei martiale a clasei muncitoare din Stormwind."},sec={{t="Din Elwynn in Old Town",b="Dupa ce luptatorii aspiranti dovedesc ca stapanesc bine bazele impotriva amenintarilor din Elwynn Forest, instructorii lor vad ca nu prea mai au ce sa-i invete pe maestrii de exercitii din Goldshire. Lyria Du Lac trimite recruti in Stormwind, spre cartierul dur din Old Town. Luptatori veterani se aduna acolo pentru a-si impartasi experienta de lupta, departe de disciplina rigida a garnizoanei regale."},{t="Lectiile veteranului",b="Harry Burlguard, un veteran batran de razboi, isi are cartierul la Pig and Whistle Tavern. El pune la incercare curajul unui Warrior cu bautura zdravana si probe practice de rezistenta, nu cu exercitii de parada. Inainte sa-i invete manevre defensive care ii ajuta pe soldati sa supravietuiasca campaniilor periculoase, Harry se asteapta ca noii veniti sa-i tina pasul la bautura si sa se infrunte cu batausii locali din taverna."}},faq={{q="Cine ofera aceasta misiune?",a="Lyria Du Lac, antrenoarea warrior din spatele fierariei din Goldshire, ofera acest antrenament dupa ce un luptator isi dovedeste primele aptitudini de lupta.",al={"cel care da misiunea","cine incepe antrenamentul unui warrior","misiunea Lyriei Du Lac"}},{q="Unde poate fi gasit Harry Burlguard?",a="Harry Burlguard se gaseste in Pig and Whistle Tavern din Stormwind City, in districtul Old Town.",al={"unde se afla Harry Burlguard","locatia lui Harry Burlguard","hanul Pig and Whistle"}},{q="Ce te invata Harry Burlguard?",a="Harry te invata miscari si pozitii practice care ii ajuta pe warriors sa reziste mai mult pe campul de lupta, incepand cu probe de rezistenta.",al={"ce inveti","recompensa misiunii de warrior la nivelul 10","lectia lui harry burlguard"}},{q="De ce are loc antrenamentul intr-o taverna si nu in cazarma?",a="Old Town este inima traditionala si aspra a Stormwind, unde se aduna soldatii retrasi si veteranii caliti. Harry ii invata la un pahar de bere si prin disciplina luptei cu pumnii goi, nu prin metodele militare formale din cazarma.",al={"de ce pig and whistle","de ce sa te antrenezi intr-o taverna","cazarma din stormwind"}},{q="Ce urmeaza dupa ce vorbesti cu Harry?",a="Dupa ce vorbeste cu Harry, recrutul infrunta o provocare care il implica pe Bartleby the Drunk, un bataus din partea locului, pentru a-si testa rezistenta fizica inainte de incheierea antrenamentului.",al={"care este urmatoarea misiune","dupa antrenamentul unui Warrior","pasul urmator"}},{q="Pot primi aceasta misiune cei care nu sunt Warrior?",a="Numai warrior pot primi aceasta instruire. Ea face parte din calea de pregatire dedicata warrior.",al={"doar pentru warrior","pot face asta paladinii","misiune de clasa warrior"}}},fx={["7596c61a"]={q="De ce te trimite Lyria Du Lac la Harry Burlguard?",a="Lyria Du Lac stie ca ti-ai dovedit priceperea ca razboinic, dar intelege ca entuziasmul de unul singur nu te duce prea departe pe campul de lupta. Pentru a-ti spori sansele de supravietuire in fata unor amenintari mai cumplite, te indruma catre Harry Burlguard. Veteran cu multa experienta, Harry stapaneste tehnici martiale bine incercate si intelepciunea practica de pe campul de lupta de care recrutii mai noi au nevoie disperata daca vor sa ramana in viata.",al={"de ce isi doreste Lyria acest lucru","motivul pentru care Lyria Du Lac vrea asta","de ce sa trimita la Harry Burlguard"}}},fp="20,234,23.356.0,22.374.0,21.139.0,35.103.0,32.121.0,57.209.0,35.166.1,36.91.0"}
P.entries["quest:1639"] = {n="Bartleby the Drunk",s="In Pig and Whistle Tavern, Bartleby the Drunk este pus la incercare de Harry Burlguard. Un aspirant razboinic Alliance trebuie sa-i ia halba pretioasa lui Bartleby inainte ca Harry sa-l invete tehnici de lupta mai avansate.",h="In Pig and Whistle Tavern, Bartleby the Drunk este pus la incercare de Harry Burlguard.",kw={"bartleby","betiv","harry burlguard","halba","orasul vechi","pig and whistle","stormwind","antrenament","warrior"},ang={["class:Warrior"]="Ca warrior, treci o proba practica data de instructorii din Stormwind inainte sa te invete tactici defensive si stapanirea pozitiilor de lupta.",["faction:Alliance"]="Ca calator al Alliance, vezi latura aspra si lipsita de stralucire a cartierului Old Town din Stormwind, departe de curtea regala din Keep."},sec={{t="O incercare la han",b="Harry Burlguard cere o dovada a curajului unui novice inainte de a-l invata tehnici de lupta mai avansate la Pig and Whistle Tavern. De cealalta parte a incaperii, Bartleby isi bea bauturile la capatul indepartat al tejghelei. Harry vrea sa-i iei cana barbatului, stiind ca Bartleby ar prefera sa se lupte decat sa renunte la berea lui. Provocarea pune la incercare hotararea unui razboinic."},{t="Eticheta din Old Town",b="Soldati, muncitori si localnici arizi umplu localul Pig and Whistle, unde bunele maniere conteaza prea putin. Bartleby isi bate joc de nou-veniti, spunand ca sunt prea simandicosi pentru o incaierare in taverna, in loc sa le raspunda politicos. Schimbul de replici duce la o bataie pe podeaua de scanduri, unde pregatirea unui Warrior din Stormwind incepe cu un test de lupta elementara de carciuma."}},faq={{q="Cine este Bartleby?",a="Bartleby este un client indaratnic, care bea mult, la barul din Pig and Whistle Tavern, in Old Town din Stormwind.",al={"cine este bartleby","npc-ul bartleby","Bartleby the Drunk"}},{q="De ce ma trimite Harry Burlguard la Bartleby?",a="Harry Burlguard vrea sa vada ce miscari folosesti inainte de a te invata tehnici avansate de warrior. Sa iei halba lui Bartleby garanteaza o lupta si pune la incercare capacitatea ta de a incasa un pumn si de a-ti tine pozitia.",al={"de ce sa ma lupt cu bartleby","incercarea lui harry burlguard","de ce sa iau cana"}},{q="Unde are loc aceasta intalnire?",a="Intalnirea are loc in Pig and Whistle Tavern din Old Town, in partea de est a Stormwind City.",al={"unde este Bartleby","locatia Pig and Whistle"}},{q="Ce se intampla cand vorbesti cu Bartleby?",a="Bartleby te jigneste, numindu-te fandosit si mofturos, apoi te avertizeaza sa nu-ti rupi vreo unghie in Pig and Whistle. Vorbele lui starnesc repede o bataie.",al={"ce spune Bartleby","dialogul lui Bartleby"}},{q="Ce urmeaza dupa ce vorbesti cu Bartleby?",a="Dupa ce vorbesti cu Bartleby, izbucneste o bataie de crasma. Trebuie sa-l invingi ca sa-i iei cana si sa i-o duci inapoi lui Harry Burlguard.",al={"urmatoarea misiune dupa Bartleby","ce urmeaza dupa Bartleby the Drunk"}},{q="Este aceasta misiune disponibila pentru orice clasa?",a="Nu. Aceasta instruire de clasa este pentru warrior din Alliance care au ajuns la nivelul zece.",al={"poate oricine sa-l infrunte pe bartleby","doar Warrior"}}},fx={["1d302574"]={q="De ce te trimite Harry Burlguard in loc sa i se impotriveasca el insusi lui Bartleby?",a="Harry Burlguard nu are nimic personal de impartit cu betivul locului - este un antrenor de razboinici care-ti pune curajul la incercare. Inainte sa-si piarda vremea invatandu-te tehnici martiale avansate, vrea sa vada daca ai stofa necesara pentru o incaierare zdravana. Sa te trimita sa smulgi o halba din mana unui betiv incapatanat de la han e pur si simplu proba lui practica de admitere.",al={"de ce eu","de ce ma trimiti la bartleby","de ce nu se lupta harry cu bartleby"}}},fp="18,193,18.347.0,18.330.0,16.113.0,45.195.0,37.111.0,40.133.0,37.122.0,37.76.0"}
P.entries["quest:164"] = {n="Deliveries to Sven",s="Deliveries to Sven este o sarcina a Alliance incredintata de Elaine Carevin in Darkshire, prin care se cere ducerea proviziilor esentiale la o tabara izolata de la granita de nord-vest a Duskwood. Acolo, Sven Yorgen si putinii sai adepti ramasi duc o lupta disperata si solitara impotriva ororilor padurii napadite de blestem. Aceasta misiune leaga locuitorii orasului, care se lupta cu intunericul, de o ceata izolata de la marginea salbaticiei.",h="Deliveries to Sven este o sarcina a Alliance incredintata de Elaine Carevin in Darkshire, prin care se cere...",kw={"Carevin","Darkshire","Duskwood","Elaine Carevin","lumina","Supplies for Sven","Sven Yorgen"},ang={["class:Paladin"]="Elaine vorbeste despre Sven ca despre un om care face cu adevarat voia Luminii, astfel ca aceasta cursa cu provizii devine un act de solidaritate fata de un frate aflat sub asediu.",["faction:Alliance"]="Strajeri din avanposturi precum Sven ilustreaza raza de actiune slabita a Alliance in Duskwood, unde supravietuirea depinde de curieri voluntari, nu de liniile regulate de aprovizionare ale garnizoanei.",["race:Human"]="Familia Carevin si adeptii lui Sven demonstreaza tenacitatea neclintita a oamenilor de la tara din Stormwind, refuzand sa abandoneze Duskwood in ciuda beznei sale necrutatoare."},sec={{t="O legatura vitala cu salbaticia",b="In timp ce Darkshire abia isi apara zidurile de lupi, paianjeni si morti nelinistiti, unii refuza sa se ascunda in spatele palisadelor. Sven Yorgen si un pumn de insotitori si-au stabilit o tabara izolata de-a lungul marginii nord-vestice a Duskwood. Sunt atat de coplesiti de pericolul neincetat, incat nu-si pot lipsi tabara nici macar de un singur om care sa faca drumul primejdios inapoi in oras pentru provizii. Elaine Carevin intervine pentru a coordona ajutorul, bazandu-se pe calatori curajosi care sa se asigure ca acesti luptatori de la granita nu mor de foame."},{t="Legatura cu Carevin",b="Familia Carevin il pretuieste mult pe Sven, vazand in lupta sa neinfricata adevarata devotiune fata de Light. Faptul ca Elaine este dispusa sa organizeze si sa trimita provizii scoate la iveala retelele discrete de supravietuire care impiedica Duskwood sa se prabuseasca cu totul in intuneric. Cand Sven primeste lada, recunoaste sprijinul statornic al familiei Carevin, desi gandurile ii sunt inca mistuite de lupta crancena care il asteapta."}},faq={{q="Cine este Sven Yorgen?",a="Sven Yorgen este un om al tinuturilor de frontiera, cu o tabara inarmata la marginea de nord-vest a Duskwood. Considerat de oameni precum Elaine Carevin un luptator drept, care slujeste Light, Sven si mica lui banda se lupta cu nenumaratele orori ce bantuie padurile din imprejurimi.",al={"cine este Sven","povestea lui Sven","informatii despre Sven Yorgen"}},{q="De ce are Sven nevoie sa-i fie aduse provizii?",a="Ceata lui Sven este extrem de mica si trebuie sa stea necontenit in garda impotriva amenintarilor din jur. Nu-si poate lipsi nici macar un singur om pentru calatoria primejdioasa pana la Darkshire si inapoi, fiind astfel cu totul dependenta de localnici binevoitori si curieri aflati in trecere pentru hrana.",al={"de ce nu poate Sven sa obtina provizii","proviziile lui Sven","de ce livrare"}},{q="Cine furnizeaza proviziile?",a="Elaine Carevin furnizeaza proviziile din Darkshire. Familia ei pastreaza o relatie apropiata cu Sven si ii pretuieste mult devotamentul, organizand cu regularitate ajutoare pentru a-i sustine tabara.",al={"cine trimite proviziile","elaine carevin","familia carevin"}},{q="Unde se afla tabara lui Sven?",a="Tabara lui Sven este ascunsa langa muntii din nord-vestul regiunii Duskwood, mult dincolo de drum si la nord de terenurile agricole blestemate, chiar la marginea salbaticiei.",al={"unde se afla Sven","locatia lui Sven","tabara lui Sven"}},{q="Este aceasta livrare obligatorie inainte de a-l ajuta din nou pe Sven?",a="Nu. Desi Elaine Carevin le da aceasta sarcina pentru a-i indruma pe calatori catre Sven, cei care ii descopera tabara pe cont propriu il pot ajuta direct, fara sa duca lada lui Elaine.",al={"este necesara misiunea Deliveries to Sven","am nevoie de Deliveries to Sven","misiune prealabila necesara"}},{q="Ce face Sven dupa ce primeste livrarea?",a="Sven isi exprima recunostinta sincera pentru sprijinul familiei Carevin, dar gandul ii zboara imediat la amenintarile cumplite care ii pun in pericol tabara si istoria familiei, in cautarea unor luptatori capabili sa-l ajute sa se razbune.",al={"ce urmeaza","dupa Deliveries to Sven","urmatoarea misiune a lui sven"}}},fx={cd88e308={q="De ce vrea Elaine Carevin sa-i livrezi provizii lui Sven?",a="Elaine Carevin il stimeaza mult pe Sven Yorgen, considerand ca lupta lui in salbaticie este o adevarata lucrare a Light. Familia ei ii sprijina adesea cauza cu provizii esentiale, dar banda lui Sven este mult prea mica pentru a trimite pe cineva sa ajunga in Darkshire si sa le ridice in siguranta.",al={"de ce trimite Elaine provizii","motivul lui Elaine Carevin","de ce o ajuta Elaine pe Sven"}},d0ad7f5e={q="De ce iti cere Elaine Carevin tie ajutorul in locul celor din Night Watch?",a="Night Watch abia mai face fata sarcinii de a pazi Darkshire si de a patrula drumurile principale impotriva strigoilor si fiarelor din Duskwood. Nu-i prisosesc paznici pe care sa-i trimita sa aprovizioneze o tabara izolata din salbaticia nord-vestica.",al={"de ce are Elaine nevoie de mine","de ce sa nu trimita Night Watch","de ce sa livrez eu insumi proviziile"}}},fp="18,417,28.505.0,22.404.0,19.277.0,43.268.0,26.196.0,29.173.0,55.189.0,47.207.0"}
P.entries["quest:1640"] = {n="Beat Bartleby",s="In Stormwind, Bartleby pazeste cana pe care trebuie sa o obtina un tanar warrior. Instructorii ii trimit pe recruti sa-l infrunte intr-o lupta cu pumnii goi si sa castige vasul necesar pregatirii lor.",h="In Stormwind, Bartleby pazeste cana pe care trebuie sa o obtina un tanar warrior.",kw={"bartleby","incaierare","betiv","cana","stormwind","antrenament","proba","warrior"},ang={["class:Warrior"]="Ca Warrior al Alliance, infrunti aceasta incaierare timpurie din taverna si inveti ca vointa neclintita si un pumn greu pot rezolva neintelegerile cand diplomatia da gres.",["faction:Alliance"]="Pe strazile capitalei Stormwind, zaresti latura rau-famata a orasului alaturi de zidurile sale impunatoare de piatra."},sec={{t="Provocarea unui bataus",b="Instructorii de warrior din Stormwind se asteapta ca recrutilor sa infrunte lupta fara scuze sau ceremonii pompoase. Ca parte a pregatirii formale, tinerii warrior trebuie sa recupereze o anumita cana de la Bartleby, un betiv notoriu care trandaveste prin oras. Acesta ia in ras rugamintile politicoase si jura ca nimeni nu-i va lua vesela pretioasa fara sa i-o smulga din degetele-i reci si moarte. Pentru un warrior in devenire, vorbele lasa curand locul unei incaierari."},{t="O lectie bahica",b="Bartleby se lauda ca va lupta pana la moarte, dar o bataie zdravana ii risipeste repede bravada. Odata invins, fala ii lasa locul unei admiratii cu vanatai. Recunoaste ca adversarul este mai puternic decat pare si se preda pasnic, lasandu-l pe invingator sa ia halba si sa incheie incercarea din sala de antrenament."}},faq={{q="Cine este Bartleby?",a="Bartleby este un betiv bataios care frecventeaza Stormwind City. Tine cu dintii la un vas de baut drag si ii pune la incercare pe razboinicii incepatori trimisi sa-si dovedeasca taria fizica.",al={"bartleby","cine este bartleby","bartleby npc"}},{q="De ce trebuie sa ma lupt cu Bartleby?",a="Instructorii Warrior din Alliance trimit recruti sa recupereze o halba aflata in posesia lui Bartleby. El refuza sa o cedeze fara o incaierare, asa ca recrutul trebuie sa-l invinga in lupta corp la corp pentru a o lua.",al={"de ce sa lupt cu bartleby","beat bartleby motivul","de ce sa-l bat"}},{q="Chiar il omor pe Bartleby in aceasta misiune?",a="Nu. Bartleby se lauda ca trebuie sa-i smulgi cana din degetele lui reci si moarte, dar cedeaza dupa ce este invins si recunoaste ca esti mai puternic decat se astepta.",al={"moare bartleby","ucide-l pe bartleby","bartleby este mort"}},{q="Unde are loc aceasta misiune?",a="Confruntarea are loc in Stormwind, unde Bartleby bea si pierde vremea.",al={"locatia lui Beat Bartleby","unde se afla Bartleby","locul lui Bartleby"}},{q="Ce se intampla dupa ce il inving?",a="Dupa ce il invingi, Bartleby se da batut si iti vorbeste prietenos. Ii poti duce cana inapoi instructorilor de Warrior pentru a-ti incheia initierea.",al={"dupa beat bartleby","ce urmeaza dupa bartleby"}},{q="Ce nivel de pregatire reprezinta aceasta incercare?",a="Aceasta incaierare este o etapa importanta timpurie pentru razboinicii incepatori, aflati in jurul celui de-al zecelea sezon de experienta, si un test practic al rezistentei de baza in lupta corp la corp.",al={"nivelul misiunii lui Bartleby","cand ma lupt cu Bartleby"}}},fx={["14f26138"]={q="De ce se lupta Bartleby cu tine?",a="Bartleby nu-si doreste deloc aceasta incaierare; tu ai starnit-o cerandu-i halba. Incapatanat, beat si atasat de bautura lui, refuza sa ti-o dea de bunavoie si declara ca va trebui sa i-o smulgi din degetele lui reci si moarte. Pentru Bartleby, lupta cu tine tine doar de mandria unui betiv si de hotararea de a-si pastra berea.",al={"de ce ataca Bartleby","motivul lui Bartleby","de ce se lupta Bartleby"}}},fp="13,171,21.424.0,16.316.0,16.167.0,32.181.0,42.149.0,33.78.0,32.142.0,49.139.0"}
P.entries["quest:1641"] = {n="The Tome of Divinity",s="In Stormwind, The Tome of Divinity ii indruma pe tinerii paladini printr-un ritual solemn. Sub indrumarea lui Duthorian Rall, in Cathedral of Light, vei invata despre virtute, devotiune si indatoririle care vin odata cu Holy Light.",h="In Stormwind, The Tome of Divinity ii indruma pe tinerii paladini printr-un ritual solemn.",kw={"book of divinity","brother wilhelm","cathedral of light","duthorian rall","lumina sacra","paladin","stormwind","tome of divinity","virtute"},ang={["class:Paladin"]="Ca paladin, acest ritual marcheaza trecerea ta de la ucenic in ale armelor la slujitor al Holy Light. El dezvaluie sacrificiul si mila aflate in inima ordinului.",["faction:Alliance"]="Ca membru Alliance, instruirea ta intareste inima Stormwind si ii pregateste pe paladins sa apere Alliance de intunericul care se ridica.",["race:Human"]="Ca human din Stormwind, ii onorezi pe cavalerii cazuti din Lordaeron si duci mai departe traditia mandra a Silver Hand in regatul sudic."},sec={{t="Chemarea unui Paladin",b="Duthorian Rall ii indruma pe cei care raspund chemarii de paladin la Cathedral of Light. Instruirea de inceput ii invata disciplina martiala si ritualurile ordinului, dar inaintarea cere un angajament spiritual mai profund. Incercarile iti cer sa privesti dincolo de lupta si sa cantaresti indatoririle morale ale unui paladin. Stormwind se confrunta cu primejdii atat in interiorul, cat si dincolo de hotarele sale, iar oamenii au nevoie de aparatori care inteleg ce presupune aceasta datorie."},{t="Calea virtutii",b="Primirea Book of Divinity te leaga de slujire si jertfire de sine. Duthorian iti cere sa studiezi textul sfant si sa afli ce pretinde Light de la aparatorii sai. Lectiile sale ii pregatesc pe paladini sa se impotriveasca ororilor napastuitoare ale Scourge si sa-i protejeze pe oamenii de rand. Puterea dreapta trebuie sa slujeasca virtutii si compasiunii."}},faq={{q="Care este scopul Tome of Divinity?",a="The Tome of Divinity pune la incercare intelegerea principiilor sacre de catre un paladin aflat in formare. Inainte ca unui initiat sa-i fie incredintate puteri divine mai mari, acesta trebuie sa-si intemeieze taria pe devotiune si virtute, nu doar pe forta martiala.",al={"de ce tome of divinity","ce este tome of divinity","misiunea cu cartea paladinului"}},{q="Cine este Duthorian Rall?",a="Duthorian Rall este un instructor superior de paladini la Cathedral of Light din Stormwind. El ii indruma pe noii paladini, le da Book of Divinity si le stabileste incercarile in tot regatul.",al={"Duthorian Rall","antrenor de Paladin din Stormwind","cine este Duthorian"}},{q="Unde se desfasoara aceasta incercare?",a="Proba incepe in Cathedral Square din Stormwind City, in interiorul Cathedral of Light. Dupa indatoririle preliminare din localitati periferice precum Goldshire, initiatii se prezinta la Duthorian Rall.",al={"unde se afla Duthorian","misiunea Cathedral of Light","unde incepe Tome of Divinity"}},{q="De ce este mentionat Scourge in invataturile din Stormwind?",a="Scourge a devastat Lordaeron, in nord, dar mortii-vii ai sai raman o amenintare pentru toti muritorii vii. Paladinii din Stormwind invata sa recunoasca si sa infrunte coruptia profana a Scourge oriunde apare in Azeroth.",al={"amenintarea Scourge din Stormwind","de ce este Scourge aici","paladini contra Scourge"}},{q="Ce urmeaza dupa ce citesti Book of Divinity?",a="Citirea Book of Divinity este doar primul pas. Duthorian Rall verifica daca i-ai insusit invataturile, trimitandu-te sa-i ajuti pe cei aflati in mare nevoie, unde faptele trebuie sa-ti dovedeasca mila si rezistenta.",al={"pasul urmator din tome of divinity","dupa ce citesti cartea","ce vrea duthorian in continuare"}},{q="Cine ii indruma de obicei pe candidati catre Duthorian Rall?",a="Instructorii si clericii din asezarile indepartate din Elwynn ii pot indruma pe candidati catre Duthorian Rall. Brother Wilhelm din Goldshire este un astfel de indrumator, trimitandu-i pe initiati in capitala cand sunt pregatiti pentru probele oficiale.",al={"cine m-a trimis la Duthorian","misiunea anterioara Tome of Divinity","Brother Wilhelm"}}},fx={f1eda7dc={q="De ce vrea Duthorian Rall sa treci prin aceasta proba?",a="Duthorian Rall are datoria de a-i calauzi in Stormwind pe paladinii incepatori spre virtutea adevarata si devotamentul fata de Holy Light. Cu Azeroth amenintat de Scourge si nenumarate alte primejdii, ordinul are nevoie de aparatori statornici, cu o credinta neclintita si pricepere pe masura. Inmanandu-ti Book of Divinity, el vrea sa-ti puna la incercare intelegerea juramintelor sacre ale unui paladin si sa se asigure ca ai temelia spirituala necesara inainte sa-ti ofere binecuvantari sacre mai mari.",al={"de ce vrea Duthorian Rall ca acest lucru sa fie facut","motivul lui Duthorian Rall","de ce sa studiezi Book of Divinity"}},e0af06a7={q="De ce te alege Duthorian Rall pentru aceasta sarcina?",a="Aceasta proba este un rit de trecere launtric si spiritual, pe care numai tu il poti parcurge. Garzile obisnuite sau cavalerii consacrati nu pot studia in locul tau principiile Light. Duthorian Rall iti supravegheaza dezvoltarea personala ca aspirant la clasa Paladin; pentru a castiga cinstea si abilitatile ordinului, trebuie sa-ti dovedesti singur devotamentul si pregatirea de a-ti asuma responsabilitatile sacre care te asteapta.",al={"de ce eu, Duthorian Rall","de ce te alege Duthorian Rall","de ce nu trimite gardieni"}}},fp="20,220,19.405.0,18.313.0,44.220.0,22.179.0,33.184.0,54.218.0,46.214.0,50.222.0"}
P.entries["quest:1642"] = {n="The Tome of Divinity",s="Tome of Divinity este un pas esential in pregatirea paladinilor devotati lui Holy Light. Incredintate spre calauzire campionilor in devenire din Stormwind, invataturile sacre subliniaza ca adevarata divinitate sta in virtutea smerita, compasiune si rabdare, nu in forta armelor sau in goana dupa statutul de zeu. Sub privirea atenta a lui Duthorian Rall, initiatii trebuie sa intruchipeze aceste invataturi slujindu-i pe cei nevoiasi si lipsiti de aparare din tot regatul.",h="Tome of Divinity este un pas esential in pregatirea paladinilor devotati lui Holy Light.",kw={"Cathedral of Light","compasiune","divinitate","Duthorian Rall","Lumina Sfanta","Paladin","rabdare","Stormwind","Tome of Divinity"},ang={["class:Paladin"]="Tome of Divinity defineste nucleul moral al chemarii unui paladin, stabilind ca mila si rabdarea sunt la fel de vitale ca pregatirea pentru lupta.",["faction:Alliance"]="Paladinii din Stormwind formeaza coloana vertebrala spirituala si martiala a Alliance, intarind apararea regatului prin integritate morala si slujire umila a cetatenilor de rand.",["race:Human"]="Pentru oamenii din Stormwind, studiul tomului sfant este un rit sacru de trecere, care intareste datoria civica si devotamentul fata de Holy Light."},sec={{t="Natura divinitatii",b="Pentru un initiat care paseste pe calea paladinului, divinitatea este adesea inteleasa gresit. Dupa cum explica textele sacre din Tome of Divinity, a te stradui sa fii divin nu inseamna sa ravnesti la statutul de zeu sau sa pretinzi ca poti porunci altora. Dimpotriva, Light-ul le cere campionilor sa-i oglindeasca harul prin intentii curate si fapte bune. Desi paladinii sunt, fara indoiala, antrenati sa zdrobeasca raul si sa ia armele in vremuri primejdioase, forta martiala nu inseamna nimic fara un scop moral. Scriptura le aminteste cavalerilor ca adevarata maretie se vede in felul in care ii trateaza pe oamenii de rand din Azeroth, iar puterea trebuie sa ramana legata de dreptate si umilinta."},{t="Incercarile compasiunii si rabdarii",b="Studiul scripturilor sfinte este doar inceputul unei slujiri adevarate. Odata ce un initiat aprofundeaza Tome of Divinity, Duthorian Rall din Stormwind verifica daca lectiile si-au gasit locul in inima si mintea candidatului. Chemarea Light-ului cere mult mai mult decat sa ucizi fiare; ea presupune rabdare indelungata, curaj neclintit si intelegere autentica. In oras si pe meleagurile din jur exista intotdeauna cetateni care sufera si sarcini lipsite de glorie sau faima. Ajutandu-i pe cei nevoiasi si alinandu-i pe cei disperati, un paladin dovedeste ca are mintea limpede si spiritul altruist necesare pentru a folosi cu raspundere binecuvantarile Light-ului."}},faq={{q="Ce este Tome of Divinity?",a="Tome of Divinity este un text sacru de instruire studiat de paladini in Stormwind. Acesta invata ca divinitatea nu inseamna atingerea statutului de zeu sau cautarea gloriei personale, ci reflectarea Holy Light prin bunatate morala, compasiune si rabdare in fiecare actiune.",al={"ce este Tome of Divinity","misiunea Tome of Divinity","Paladin Tome of Divinity"}},{q="Cine este Duthorian Rall?",a="Duthorian Rall este un conducator paladin respectat, aflat in Stormwind. El supravegheaza incercarile spirituale si martiale ale tinerilor paladini, indrumandu-i in studiul Tome of Divinity si punandu-le hotararea la incercare prin sarcini practice in folosul regatului si al oamenilor sai.",al={"cine este duthorian rall","locatia lui duthorian rall","duthorian rall din stormwind"}},{q="Ce virtuti subliniaza Tome of Divinity?",a="Tome of Divinity invata ca mila, rabdarea si curajul sunt la fel de esentiale pentru un razboinic sfant ca iscusinta in lupta. Desi paladinii trebuie sa starpeasca raul, adevarata lor noblete sta in a-i ajuta dezinteresat pe cei vulnerabili si in a oglindi bunatatea Light.",al={"virtutile Paladinului, Tome of Divinity","ce invata tomul","virtutile Luminii"}},{q="De ce ii pune Duthorian Rall la incercare pe cei care vor sa devina paladini?",a="Duthorian Rall ii pune la incercare pe initiati pentru a se asigura ca au asimilat cu adevarat invataturile din Tome of Divinity. Un paladin trebuie sa dovedeasca faptul ca are mintea limpede si rabdarea de a-i ajuta pe cei napastuiti, aratand ca devotamentul sau se intemeiaza pe slujire, nu pe mandrie.",al={"de ce ii supune Duthorian la incercari pe paladini","incercarile lui Duthorian Rall","scopul incercarilor paladinilor"}},{q="Ii invata Tome of Divinity pe paladini sa caute statutul de zeitate?",a="Nu, textul respinge explicit nazuinta catre divinitate. El ii invata pe paladini ca stradania de a deveni divin inseamna stradania de a face bine in toate actiunile, folosind puterea daruita de Light pentru a-i proteja si sprijini pe ceilalti, nu pentru a te ridica deasupra muritorilor de rand.",al={"urmaresc Paladinii divinitatea","tinderea spre divinitate pentru un Paladin","sensul divinitatii pentru un Paladin"}},{q="Unde are loc aceasta misiune?",a="Aceasta misiune are loc in regatul Human Stormwind. Initiatii studiaza invataturile sacre si se prezinta direct la Duthorian Rall, in oras, pregatindu-se sa treaca prin incercari ale caritatii, rabdarii si vitejiei, pe strazile si in tinuturile din jurul regatului.",al={"unde se afla misiunea tome of divinity","locatia tome of divinity in stormwind","unde predai tome of divinity"}},{q="De ce este rabdarea atat de importanta pentru un Paladin al Light-ului?",a="Patience dovedeste ca un razboinic sfant este disciplinat, umil si cu mintea limpede. Adevaratii slujitori ai Luminii trebuie adesea sa indeplineasca sarcini umile, dificile sau lipsite de stralucire pentru cei napastuiti, ceea ce cere tarie sufleteasca si empatie sincera, nu doar forta agresiva in lupta.",al={"de ce este importanta rabdarea pentru un paladin","importanta rabdarii pentru Lumina","testul rabdarii paladinului"}}},fp="20,441,22.673.0,33.669.0,29.270.0,22.269.0,49.276.0,47.277.0,57.268.0,33.266.0,56.297.0"}
P.entries["quest:1643"] = {n="The Tome of Divinity",s="Tome of Divinity este o incercare sfanta fundamentala, in care initiatii Luminii trebuie sa caute si sa ajute un cetatean cu inima pura si intentii nobile din Stormwind. Indrumand campionii catre Stephanie Turner, in Trade District, sarcina subliniaza ca adevarata slujire incepe prin acte de caritate modeste, facute in sprijinul celor vulnerabili.",h="Tome of Divinity este o incercare sfanta fundamentala, in care initiatii Luminii trebuie sa caute si sa ajute...",kw={"lumina sacra","ironforge","orfelinat","paladin","stephanie turner","stormwind","the tome of divinity","tome of divinity","trade district"},ang={["class:Paladin"]="Aceasta proba este o lectie esentiala de inceput pentru Paladinii care invata sa slujeasca Holy Light: adevarata devotiune incepe cu acte de caritate umile, nu cu gloria luptelor.",["faction:Alliance"]="Misiunea scoate in evidenta problemele interne din Stormwind si legaturile stranse cu Ironforge, in timp ce cetatenii se straduiesc sa sprijine orfanii vulnerabili in pofida dificultatilor economice."},sec={{t="O lectie despre umilinta si slujire",b="Tome of Divinity este un ritual esential de trecere spirituala pentru initiatii care studiaza caile lui Holy Light. Inainte de a primi invataturi mai profunde despre indatoririle sacre, viitorii slujitori trebuie sa strabata strazile din Stormwind si sa gaseasca o persoana cu intentii nobile si ganduri curate, care depinde de bunatatea strainilor. Aceasta proba intemeiaza juramintele sacre nu pe o lupta glorioasa, ci pe slujirea umila si atenta a celor vulnerabili."},{t="Ajutor in Trade District",b="In animatul Trade District din Stormwind, indatorirea aceasta ii calauzeste pe initiati la Stephanie Turner. Impreuna cu sotul ei, Stephanie isi dedica zilele confectionarii de haine pentru copiii din orfelinatul orasului. Insa numarul tot mai mare de negustori locali a dus la o concurenta acerba pentru panza si piele bruta, iar cuplului ii este greu sa obtina donatii. In timp ce sotul ei calatoreste la marile sali ale piticilor din Ironforge pentru a cere sprijin, Stephanie ramane in Stormwind si isi continua munca tacuta si altruista."}},faq={{q="Care este scopul incercarii din The Tome of Divinity?",a="Tome of Divinity este o proba fundamentala pentru Paladin in devenire, devotati lui Holy Light. In loc sa ceara pricepere in lupta sau fapte eroice marete, ii trimite pe initiati in inima orasului Stormwind sa gaseasca si sa ajute o persoana cu suflet curat, care are cu adevarat nevoie de ajutor.",al={"ce este Tome of Divinity","scopul Tome of Divinity","de ce Tome of Divinity"}},{q="Cine este Stephanie Turner?",a="Stephanie Turner este o locuitoare plina de compasiune din Trade District, Stormwind. Coase fara odihna haine pentru copiii de la orfelinatul local si se bazeaza pe donatii de stofa si piele pentru a-i tine pe micutii aflati in grija ei la cald si in siguranta.",al={"cine este Stephanie Turner","Stephanie Turner din Stormwind","unde se afla Stephanie Turner"}},{q="De ce a plecat sotul lui Stephanie Turner la Ironforge?",a="Sotul ei lucreaza alaturi de ea pentru a sprijini orfelinatul. In timp ce Stephanie aduna provizii si coase haine in Stormwind, sotul ei a calatorit spre nord, la Ironforge, pentru a cere donatii si ajutor de la populatia pitica si gnomica.",al={"sotul lui Stephanie Turner","cine este sotul lui Stephanie","sotul din Ironforge"}},{q="Cu ce dificultati se confrunta Stephanie Turner?",a="Numarul tot mai mare de negustori din Stormwind a intensificat concurenta pentru materii prime esentiale, precum panza si pielea. Cu tot mai putini oameni dispusi sa renunte de buna voie la aceste resurse, Stephanie gaseste din ce in ce mai greu materialele necesare pentru a le face haine orfanilor.",al={"de ce se chinuie stephanie","lipsa de panza din stormwind","problema hainelor de la orfelinat"}},{q="De ce ii indruma aceasta incercare pe initiati tocmai catre Stephanie Turner?",a="Proba cere ca un novice al Light sa caute pe cineva cu intentii nobile, motive pure si o nevoie sincera de o mana calauzitoare. Stephanie Turner intruchipeaza devotamentul dezinteresat fata de ceilalti, ceea ce o face persoana ideala pe care un aspirant la slujirea Light o poate ajuta.",al={"de ce sa o ajut pe stephanie turner","de ce te trimite misiunea la stephanie"}},{q="Ce lectie ofera aceasta incercare slujitorilor Light?",a="Incercarea invata ca urmarea caii Light-ului cere compasiune, altruism si slujirea celor vulnerabili. Inainte de a folosi puterea sfanta in lupta, un campion al Light-ului trebuie mai intai sa inteleaga datoria de a-i trata cu bunatate pe cetatenii de rand aflati la nevoie.",al={"ce invata Lumina aici","lectia din Tome of Divinity"}}},fp="20,311,32.438.0,25.536.0,50.272.0,24.256.0,53.245.0,45.280.0,70.265.0,60.259.0"}
P.entries["quest:1644"] = {n="The Tome of Divinity",s="Tome of Divinity este o misiune de paladin din Stormwind, in care initiatii ii duc panza de in lui Stephanie Turner, care are grija de copiii ramasi orfani din cauza Scourge. Ajutand-o sa-i imbrace pe copii cat timp sotul ei aduna provizii in Ironforge, misiunea ilustreaza virtutea esentiala a paladinilor: caritatea dezinteresata.",h="Tome of Divinity este o misiune de paladin din Stormwind, in care initiatii ii duc panza de in lui Stephanie...",kw={"caritate","John Turner","tesatura de in","orfani","Paladin","Scourge","Stephanie Turner","Stormwind","Tome of Divinity"},ang={["class:Paladin"]="Ca parte a probelor legate de Tome of Divinity, grija fata de cei vulnerabili si binefacerea dezinteresata in Stormwind pun la incercare devotamentul unui paladin fata de compasiune si Light.",["faction:Alliance"]="Soarta orfanilor de razboi din Stormwind scoate in evidenta pierderile umane provocate de recentele atacuri ale Scourge in tinuturile nordice ale Alliance.",["profession:Tailoring"]="Stephanie Turner foloseste bucati simple de panza de in pentru a coase camasi si pantaloni esentiali pentru copiii orfani aflati in grija ei."},sec={{t="Orfanii razboiului",b="Pe strazile aglomerate din Stormwind, Stephanie Turner are grija de o gospodarie plina de copii ramasi fara familie in urma devastarilor provocate de Scourge in tinuturile nordice in ultimul deceniu. In timp ce sotul ei, John, calatoreste peste hotare pentru a strange provizii, Stephanie poarta povara zilnica de a-i tine pe copii hraniti, incalziti si adapostiti. Chiar si lucruri de baza, precum hainele curate, necesita efort si timp considerabil, de care rareori dispune."},{t="O incercare a compasiunii",b="Paladinii aspiranti care vor sa stapaneasca invataturile din Tome of Divinity sunt chemati sa-si dovedeasca generozitatea dezinteresata, nu iscusinta martiala. Ducandu-i lui Stephanie suluri de panza de in, un initiat ii ia o povara de pe umeri, permitandu-i sa coasa camasi si pantaloni pentru copii, concentrandu-se totodata asupra adapostului si hranei lor. Prin astfel de gesturi umile de ajutor, aparatorii lui Light isi dovedesc devotamentul fata de ocrotirea celor slabi."},{t="Tensiuni in capitala",b="Desi Stephanie razbate prin greutatile de zi cu zi, ea remarca faptul ca anul in curs a devenit vizibil mai aspru. Sotul ei este nevoit sa faca drumuri lungi si grele pana la Ironforge pentru provizii, iar povara resimtita de oamenii de rand oglindeste nelinistea mai larga din intregul regat. Chiar si la adapostul zidurilor inalte de piatra ale capitalei, umbrele persistente ale tragediilor recente din nord se resimt puternic."}},faq={{q="Cine este Stephanie Turner?",a="Stephanie Turner este o femeie plina de compasiune, care locuieste in Stormwind si si-a dedicat viata ingrijirii copiilor ramasi orfani din cauza Scourge. Se straduieste neobosit sa le asigure hrana, haine si adapost, bazandu-se in mare masura pe generozitatea comunitatii si pe eforturile sotului ei, John.",al={"cine este stephanie turner","stephanie turner din stormwind","ingrijitoarea orfelinatului"}},{q="De ce are Stephanie Turner nevoie de panza de in?",a="Stephanie are nevoie de panza de in ca sa coasa camasi si pantaloni pentru copiii orfani. Fiind ocupata cu gasirea hranei si intretinerea adapostului lor, faptul ca primeste panza bruta o scuteste de timpul si efortul necesare pentru a aduna singura materialele.",al={"de ce panza de in","la ce se foloseste inul","panza pentru stephanie"}},{q="Cine este John si unde a plecat?",a="John este sotul lui Stephanie Turner. Pleaca din Stormwind ca sa adune provizii si materiale esentiale, ajungand pana in orasul pitic Ironforge, desi nu-i place sa stea departe de familie.",al={"cine este John","unde este John","sotul lui Stephanie Turner"}},{q="De ce sunt atat de multi copii orfani in Stormwind?",a="Cei mai multi dintre copiii aflati in grija lui Stephanie si-au pierdut familiile in atacurile devastatoare ale Scourge asupra regatelor nordice din ultimul deceniu. Multi dintre acesti copii ramasi fara parinti au fost adusi spre sud, in Stormwind, de refugiatii stramutati si de supravietuitori.",al={"de ce sunt orfani in Stormwind","orfani ai Scourge in Stormwind","ce s-a intamplat cu parintii copiilor"}},{q="Ce legatura are ajutarea lui Stephanie cu Tome of Divinity?",a="Tome of Divinity pune la incercare virtutile fundamentale ale unui Paladin aspirant, mai presus de toate mila si compasiunea. Ajutarea unui ingrijitor coplesit cu provizii de baza dovedeste ca un slujitor al Light-ului ii apara pe cei umili la fel de prompt cum infrunta monstrii.",al={"semnificatia cartii Tome of Divinity","de ce este aceasta o misiune de Paladin","misiune de binefacere pentru Paladin"}},{q="La ce se refera Stephanie cand spune ca 'se simte ceva in aer'?",a="Stephanie remarca faptul ca anul acesta a fost mult mai greu decat cei dinainte, de parca ceva din aer ar prevesti o schimbare uriasa, desi recunoaste ca nu poate spune despre ce este vorba.",al={"an greu pentru stormwind","ceva in aer","necazurile din stormwind"}}},fp="20,327,18.448.0,21.462.0,22.412.0,24.262.0,43.231.0,34.216.0,53.243.0,58.259.0,54.160.0"}
P.entries["quest:1646"] = {n="The Tome of Divinity",s="Tome of Divinity este o misiune fundamentala pentru paladini, axata pe virtutile spirituale care ii calauzesc pe razboinicii sacri. Oferita de mentori precum Tiza Battleforge in Ironforge, aceasta ii invata pe initiati ca devotamentul adevarat fata de Light cere rabdare, compasiune si slujire umila a celor nevoiasi, pe langa puterea martiala.",h="Tome of Divinity este o misiune fundamentala pentru paladini, axata pe virtutile spirituale care ii calauzesc...",kw={"compasiune","lumina sfanta","ironforge","paladin","rabdare","the tome of divinity","tiza battleforge","tome of divinity"},ang={["class:Paladin"]="Tome of Divinity le dezvaluie tinerilor Paladini principiile fundamentale ale chemarii lor, subliniind ca mila si slujirea sunt la fel de importante ca iscusinta in lupta.",["race:Dwarf"]="Paladinii pitici din Ironforge primesc aceasta invatatura de la mentori precum Tiza Battleforge, pentru ca puterea lor sa fie calauzita de rabdare si virtute."},sec={{t="Masura divinitatii",b="Tome of Divinity reprezinta o etapa esentiala in pregatirea unui paladin. Transmis prin mentori precum Tiza Battleforge din Ironforge, textul le insufla initiatilor scopul spiritual care se afla in spatele maiestriei lor martiale. In loc sa glorifice stapanirea sau divinitatea, cartea ii invata ca adevarata divinitate consta in cautarea binelui moral si in a sluji drept unealta de nadejde a Light."},{t="Incercarile slujirii si compasiunii",b="Desi razboinicii Light-ului sunt chemati adesea sa loveasca raul in tot Azeroth-ul, tomul subliniaza ca puterea martiala singura nu defineste un paladin. Compasiunea, rabdarea si umilinta il deosebesc de luptatorii de rand. Dupa ce studiaza textul, initiatii sunt indrumati sa treaca prin incercari in Ironforge si tinuturile din apropiere, savarsind fapte de milostenie si slujire pentru a-si dovedi judecata sanatoasa si devotiunea neclintita."}},faq={{q="Ce este Tome of Divinity?",a="Tome of Divinity este un text fundamental de instruire oferit paladinilor novice. Acesta ii invata ca a fi divin nu inseamna sa cauti sa devii zeu, ci sa te straduiesti sa faci bine, sa-i ajuti pe cei napastuiti si sa dai dovada de compasiune, rabdare si curaj.",al={"ce este Tome of Divinity","Tome of Divinity pentru Paladin","ce invata tome-ul"}},{q="Cine este Tiza Battleforge?",a="Tiza Battleforge este un indrumator paladin din Ironforge, care ii indruma pe novici in primele lor incercari, asigurandu-se ca inteleg echilibrul dintre lupta dreapta si slujirea dezinteresata.",al={"cine este Tiza Battleforge","locatia lui Tiza Battleforge","unde este Tiza"}},{q="De ce trebuie sa studieze paladins rabdarea si compasiunea?",a="Puterea unui paladin vine din reflectarea Light, ceea ce presupune un caracter integru si disciplina morala. Forta in lupta nu este de ajuns fara rabdarea si compasiunea necesare pentru a-i apara si a-i inalta pe ceilalti.",al={"de ce sa citesti tomul","virtutile paladinilor","de ce sunt importante rabdarea si compasiunea"}},{q="Ce probe urmeaza dupa citirea cartii?",a="Dupa ce citesc textul, paladinii trebuie sa-si dovedeasca virtutile prin probe practice. Mentorii le incredinteaza sarcini prin oras si tinuturile din jur, pentru a-i ajuta pe cei nevoiasi si a-si dovedi devotamentul fata de Light.",al={"ce se intampla dupa ce citesti tomul","incercarile din tome of divinity","urmatoarea incercare dupa lectura"}},{q="Unde se desfasoara aceasta incercare?",a="Misiunea le cere paladinilor sa se intoarca la Tiza Battleforge, in capitala piticilor, Ironforge, dupa ce au studiat invataturile din tom.",al={"unde predau aceasta misiune","misiunea de paladin din Ironforge"}},{q="Ce inseamna sa aspiri la divinitate?",a="Potrivit textului, a te stradui sa fii divin nu inseamna sa aspiri la statutul de zeu. Inseamna, in schimb, sa alegi in mod activ sa faci bine in toate actiunile tale si sa folosesti Light pentru a sprijini si proteja locuitorii din Azeroth.",al={"ce inseamna nazuinta spre divinitate","divinitatea paladinului"}}},fp="20,318,23.392.0,32.429.0,29.229.0,24.190.0,48.216.0,35.213.0,33.142.0,41.207.0"}
P.entries["quest:1647"] = {n="The Tome of Divinity",s="Tome of Divinity este o proba sacra timpurie, parcursa de initiatii Luminii din Ironforge. Trimisa de un mentor din templul orasului, aspiranta trebuie sa caute in cercul exterior pe cineva cu intentii curate si o nevoie reala. Gasindu-l pe muncitorul devotat John Turner, initiatii invata ca slujirea dezinteresata si compasiunea sunt esentiale pentru a urma calea Luminii.",h="Tome of Divinity este o proba sacra timpurie, parcursa de initiatii Luminii din Ironforge.",kw={"ironforge","john turner","lumina","orfelinat","paladin","templu","the tome of divinity","tome of divinity"},ang={["class:Paladin"]="Aceasta misiune este o proba esentiala pe calea Luminii, invatandu-i pe Paladini ca adevarata devotiune incepe prin a-i ajuta dezinteresat pe oamenii de rand aflati la nevoie.",["faction:Alliance"]="Misiunea scoate in evidenta virtutile care tin Alliance unita—compasiunea, milostenia si grija fata de cei vulnerabili din orase precum Ironforge.",["race:Dwarf"]="Desfasurata in capitala piticilor, Ironforge, aceasta incercare ii pune la proba pe discipolii locali ai Light, chiar in salile orasului lor natal."},sec={{t="O lectie de compasiune",b="Tome of Divinity este o proba de initiere pentru cei care slujesc Light in Ironforge. In loc sa le testeze abilitatile martiale sau sa le ceara sa se masoare cu dusmanii, indrumatorul initiatului ii cere sa cutreiere orasul aglomerat al piticilor in cautarea cuiva care are cu adevarat nevoie de ajutor. Sarcina cere discernamant: initiatul trebuie sa gaseasca o persoana cu inima curata, intentii nobile si o nevoie sincera de bunatatea celorlalti, dovedind ca slujirea smerita este temelia chemarii sale sacre."},{t="Povara lui John Turner",b="Cautarea ii conduce pe discipoli la inelul exterior al Ironforge, unde un simplu muncitor pe nume John Turner isi practica meseria. Luat prin surprindere de vizitatorii care il aud vorbind despre orfelinatul din Stormwind, Turner dezvaluie sacrificiul tacut din spatele vietii sale de zi cu zi. Despartit de iubita sa sotie de munca neincetata, indura orele lungi doar pentru ca orfanii sa aiba haine pe ei si mancare pe masa. Ajutandu-l pe Turner, initiatii descopera adevarata greutate a bunavointei, apoi se intorc la templu pentru a-si continua calea in Light."}},faq={{q="Ce este misiunea The Tome of Divinity?",a="Tome of Divinity este o incercare sacra la care se supun aspirantii la slujirea Light-ului in Ironforge. Initiatul trebuie sa gaseasca si sa ajute in oras o persoana cu inima pura si intentii nobile, inainte de a-si continua invataturile spirituale.",al={"ce este Tome of Divinity","scopul lui Tome of Divinity","ce este aceasta misiune"}},{q="Cine este John Turner?",a="John Turner este un barbat harnic, intalnit in cercul exterior al Ironforge. Munceste neobosit, departe de sotia sa iubita, pentru a strange resurse si a hrani si imbraca orfanii aflati in nevoie.",al={"cine este John Turner","John Turner in Ironforge","unde se afla John Turner"}},{q="De ce te trimite mentorul sa cauti pe cineva aflat la nevoie?",a="Incercarea pune la incercare intelegerea compasiunii si a slujirii de catre un initiat. In loc sa lupte cu monstri, un slujitor al Light trebuie mai intai sa invete sa recunoasca intentiile nobile, sa ofere bunatate si sa-i indrume pe cei care trudesc in tacere pentru binele altora.",al={"de ce sa gasesc pe cineva care are nevoie","scopul ajutorului dat lui John Turner","de ce sa fac acest test"}},{q="Unde se afla John Turner in Ironforge?",a="John Turner poate fi gasit mergand de-a lungul inelului exterior al orasului Ironforge, unde isi indeplineste treburile zilnice solicitante pentru orfelinat.",al={"unde il gasesc pe john turner","locatia lui john turner","cum il gasesc pe john turner"}},{q="Ce se intampla dupa ce vorbesti cu John Turner?",a="Dupa ce-l gasesti pe John Turner si-i asculti necazul, te intorci la mentorul din templu pentru a medita la adevaratul sens al urmarii caii Light-ului si a te pregati pentru urmatoarea etapa a chemarii tale.",al={"ce se intampla dupa ce-l gasesti pe John Turner","intoarce-te la Temple of the Light","urmatorul pas din Tome of Divinity"}},{q="De ce striga John Turner despre un orfelinat?",a="La prima intalnire, John Turner incepe sa strige despre orfelinatul din Stormwind, apoi isi vine in fire si isi cere scuze. Munca lui este dedicata sprijinirii copiilor orfani care depind de pomana pentru hrana si imbracaminte.",al={"despre ce orfelinat striga john turner","orfelinat din stormwind ironforge","de ce a strigat john turner"}}},fp="20,369,22.515.0,25.541.0,35.249.0,19.183.0,53.242.0,42.131.0,45.202.0,48.224.0"}
P.entries["quest:1648"] = {n="The Tome of Divinity",s="Tome of Divinity le cere slujitorilor Light-ului sa savarseasca un gest de compasiune smerita in Ironforge. Ajutorul dat lui John Turner, care administreaza un orfelinat in Stormwind pentru copiii stramutati de Scourge, pune la incercare devotamentul unui initiat fata de altruism si milostenie, mai presus de gloria armelor.",h="Tome of Divinity le cere slujitorilor Light-ului sa savarseasca un gest de compasiune smerita in Ironforge.",kw={"Holy Light","Ironforge","John Turner","panza de in","Paladin","orfanii Scourge","orfelinatul din Stormwind","The Tome of Divinity"},ang={["class:Paladin"]="Paladinii trec aceasta incercare nu prin otel sau iscusinta in lupta, ci oferind ajutor dezinteresat celor nevinovati si intruchipand virtutea compasiunii, esentiala pentru Holy Light.",["faction:Alliance"]="Aceasta insarcinare dezvaluie ranile adanci lasate de Scourge asupra societatii umane si ilustreaza dependenta reciproca dintre Stormwind si Ironforge."},sec={{t="Milostenie in Great Forge",b="Tome of Divinity ii pune in fata unui initiat care paseste pe calea Light o incercare ce nu tine de arme, ci de marinimie. In salile forfotitoare din Ironforge, un sol al milei pe nume John Turner cere ajutor. Turner si sotia lui se ocupa de un orfelinat in kingdom of Stormwind, avand grija de copiii ramasi fara parinti in urma campaniilor devastatoare ale Scourge din ultimul deceniu. Calatoria lui catre capitala piticilor reflecta greutatile impartasite de oamenii de rand ai Alliance."},{t="Cicatricile Scourge-ului",b="Aprovizionarea peste granite nu este deloc usoara. Un aflux de meseriasi in toata lumea Azeroth a pus la grea incercare lanturile locale de aprovizionare, facand rare si materialele simple. Calatoria lui Turner la Ironforge, unde urma sa faca apel la grupurile civice si la cetateni, s-a impotmolit dupa saptamani de progrese minime, lasandu-l fara panza de in de care sotia lui are nevoie pentru a croi haine pentru copii. Oferind panza fara a cere nimic in schimb, un slujitor al Luminii dovedeste devotamentul altruist care sta la temelia chemarii sale sacre."}},faq={{q="Cine este John Turner?",a="John Turner este un om care se ocupa de un orfelinat din Stormwind impreuna cu sotia sa. Aproximativ o data pe luna, calatoreste la Ironforge pentru a cere provizii si ajutoare de la cetatenii pitici si ghildele negustorilor, in sprijinul copiilor ramasi orfani din cauza razboiului.",al={"cine este John Turner","povestea lui John Turner","familia Turner din Ironforge"}},{q="De ce are John Turner nevoie de panza de in?",a="Turner are nevoie de panza de in, pentru ca sotia lui, ramasa in Stormwind, sa poata coase haine groase pentru copiii orfani. Din cauza afluxului de negustori si a schimbarilor comertului in Azeroth, panza obisnuita a devenit rara si greu de gasit.",al={"de ce in","de ce are John Turner nevoie de material","in pentru orfelinat"}},{q="De ce sunt atatia orfani in Stormwind?",a="Copiii aflati in grija familiei Turner si-au pierdut parintii in timpul atacurilor devastatoare lansate de strigoii Scourge de-a lungul ultimului deceniu. Third War a destramat multe familii din regatele oamenilor, lasand numerosi tineri fara adapost.",al={"orfanii din orfelinatul Stormwind","de ce sunt orfani","orfanii scourge"}},{q="De ce a calatorit John Turner la Ironforge?",a="Turner calatoreste peste munti pana la Ironforge pentru a le cere cetatenilor dwarfi si diverselor bresle comerciale donatii si provizii care sunt greu de obtinut in Stormwind.",al={"de ce este John Turner in Ironforge","de ce Ironforge pentru orfelinatul din Stormwind"}},{q="Ce legatura are ajutorarea unui orfelinat cu Holy Light?",a="Holy Light cere altruism, mila si slujire fata de cei cuprinsi de disperare. Ajutorul dat unui ingrijitor epuizat, care se ocupa de orfanii de razboi, este un test de umilinta si caritate pentru paladinii aspiranti, nu o demonstratie de forta martiala.",al={"ce legatura are asta cu Lumina","legatura cu paladinii","de ce indeplinesc paladinii aceasta misiune"}},{q="De ce a fost atat de anevoioasa calatoria lui John Turner la Ironforge?",a="Expeditia lui Turner a inaintat chinuitor de incet si a fost in mare parte nerodnica, fiindca proviziile locale sunt putine si nicio echipa nu prea s-a oferit sa ajute. Astfel, el nu se poate intoarce acasa pana nu este asigurata o livrare.",al={"John Turner e blocat","de ce dureaza mult calatoria"}}},fp="20,282,26.481.0,24.530.0,19.240.0,38.230.0,43.236.0,40.183.0,55.239.0,58.218.0"}
P.entries["quest:1649"] = {n="The Tome of Valor",s="Duthorian Rall ii asteapta pe paladinii care cauta incercari de credinta si curaj in Stormwind. Tome of Valor le calauzeste primii pasi spre a-si dovedi devotamentul fata de Church.",h="Duthorian Rall ii asteapta pe paladinii care cauta incercari de credinta si curaj in Stormwind.",kw={"cathedral of light","church of the holy light","duthorian rall","credinta","paladin","stormwind","tome of valor","vitejie"},ang={["class:Paladin"]="Ca Paladin, aceasta incercare marcheaza o etapa definitorie in dezvoltarea ta. Iti uneste iscusinta martiala cu credinta disciplinata si slujirea dezinteresata.",["faction:Alliance"]="Ca membru al Alliance, impartasesti forta pe care aceste incercari din Stormwind o pastreaza, atat in aparare, cat si in spirit, in vremuri tulburi."},sec={{t="Calirea spiritului",b="Tome of Valor ne invata ca vitejia trebuie calita prin greutati. Textul sacru compara virtutile cu minereurile pretioase: valoroase cand sunt descoperite, dar care trebuie rafinate ca sa dainuie. Prin incercari grele si devotament adevarat, un paladin impleteste credinta, compasiunea si curajul intr-o forta capabila sa reziste raului care ameninta Azeroth."},{t="Adresarea unei cereri Bisericii",b="Dupa ce citesti Tome of Valor, esti indrumat catre Duthorian Rall, un conducator respectat printre paladinii din Cathedral of Light din Stormwind. El asculta cererile celor care cauta probele curajului. Incercarile nu sunt un simplu ritual: apararea celor nevinovati si sustinerea Bisericii iti pot cere viata, iar numai cei neclintiti sunt recunoscuti de ordin."}},faq={{q="Care este scopul acestei misiuni?",a="Tome of Valor il indruma pe un initiat de la doctrina sacra spre incercari primejdioase. Dupa ce il citeste, aspirantii la clasa Paladin ii cer lui Duthorian Rall din Cathedral of Light sa le puna la incercare credinta si curajul.",al={"ce este misiunea Tome of Valor","de ce am nevoie de aceasta misiune","scopul Tome of Valor"}},{q="Cine este Duthorian Rall?",a="Duthorian Rall este un paladin de rang inalt si instructor la Cathedral of Light din Stormwind. Supravegheaza pregatirea aparatorilor promitatori si incercarile care dovedesc ca un initiat este demn de Church.",al={"cine este Duthorian Rall","povestea lui Duthorian Rall","antrenorul Paladin din catedrala"}},{q="De ce ii pune Biserica la incercari atat de grele pe paladinii sai?",a="Church of the Holy Light pune paladinii la incercare, pentru ca acestia sa poata ramane neclintiti in fata disperarii si violentei. O hotarare slaba sau o credinta fragila ar putea costa vieti in lupta, asa ca instructorii pun la incercare si calesc fiecare novice inaintea misiunilor sfinte decisive.",al={"de ce sunt periculoase incercarile paladinilor","de ce se pune la incercare vitejia"}},{q="Unde se desfasoara aceasta incercare?",a="Iti prezinti petitia lui Duthorian Rall la Cathedral of Light, in inima Cathedral Square din Stormwind City.",al={"unde predai Tome of Valor","locatia lui Duthorian Rall"}}},fx={["5e1febd2"]={q="De ce te trimite Tome of Valor la Duthorian Rall?",a="Textul din Tome of Valor este un indrumar spiritual si moral, care subliniaza ca virtuti precum credinta si curajul trebuie puse la incercare si calite pana devin o hotarare de neclintit. Te trimite la Duthorian Rall, in Stormwind, fiindca incercarile nu pot fi doar citite: un paladin in devenire trebuie sa se infatiseze inaintea conducerii Cathedral of Light si sa dovedeasca faptul ca devotamentul sau poate rezista unui sacrificiu mortal.",al={"de ce trebuie sa vorbesc cu Duthorian Rall","de ce Duthorian Rall si Tome of Valor","de ce sa ma trimita la Rall"}}},fp="17,168,20.325.0,22.354.0,34.197.0,22.196.0,50.230.0,33.120.0"}
P.entries["quest:165"] = {n="The Hermit",s="Ingrijorata de absenta indelungata a unui batran pustnic, Elaine Carevin din Darkshire le cere calatorilor sa vada ce mai face. Batranul singuratic, Abercrombie, locuieste intr-o sandrama darapanata, chiar la marginea Raven Hill Cemetery.",h="Ingrijorata de absenta indelungata a unui batran pustnic, Elaine Carevin din Darkshire le cere calatorilor sa...",kw={"abercrombie","darkshire","duskwood","elaine carevin","cimitirul raven hill","coliba","pustnicul"},ang={["faction:Alliance"]="Night Watch se lupta sa apere drumurile dintre Darkshire si Raven Hill, lasandu-i pe sihastri indepartati precum Abercrombie complet izolati de siguranta orasului.",["race:Human"]="Familia Carevin intruchipeaza legaturile de vecinatate trainice din Duskwood, avand grija de batranii excentrici ai comunitatii chiar si in timp ce regiunea lor se cufunda in umbra."},sec={{t="O vizita de curtoazie la vecini",b="Intr-o asezare greu incercata precum Darkshire, e usor sa nu mai stii nimic de pustnicii excentrici pana cand disparitia lor devine ingrijoratoare. Elaine Carevin isi aminteste de un batran care venea regulat in oras pentru provizii, inainte sa dispara brusc. Avand in vedere primejdiile neincetate care bantuie drumurile din Duskwood, ea ii indeamna pe aventurierii aflati in trecere sa-i cerceteze coliba, de unde se vede intinderea bantuita din Raven Hill Cemetery, pentru a se asigura ca nu a avut parte de un sfarsit cumplit."},{t="Pustnicul din Raven Hill",b="Ajungand la coliba izolata, afli ca locatarul ei, un batran pe nume Abercrombie, este inca in viata. El chicoteste incet cand aude de Carevins si sustine ca lunga sa absenta nu se datoreaza decat varstei inaintate si monstrilor primejdiosi care pandesc prin padure. Usurat ca a gasit la usa un calator destoinic, Abercrombie nu pierde vremea si intreaba daca acesta n-ar putea sa-i faca cateva comisioane folositoare."}},faq={{q="Cine incepe aceasta treaba?",a="Elaine Carevin, locuitoare din Darkshire, in Duskwood, porneste misiunea ingrijorata pentru un pustnic batran care obisnuia sa cumpere provizii din oras.",al={"cine ofera misiunea The Hermit","unde incepi The Hermit","misiunea lui Elaine Carevin"}},{q="Unde se afla pustnicul?",a="Abercrombie locuieste intr-o coliba de lemn darapanata, aflata la marginea nordica a Raven Hill Cemetery, in vestul Duskwood.",al={"unde este Abercrombie","locatia pustnicului din Duskwood","coliba de langa Raven Hill"}},{q="De ce isi facea Elaine Carevin griji pentru el?",a="Abercrombie mergea odinioara regulat in Darkshire sa cumpere provizii, dar apoi a incetat sa mai apara. Cu fiare salbatice si strigoi ratacind pe drumuri, ea se temea ca el pierise.",al={"de ce sa-l verificam pe abercrombie","de ce este elaine ingrijorata","ce i s-a intamplat batranului"}},{q="Este Abercrombie cu adevarat in pericol cand il gasesti?",a="Nu. Cand ajungi la coliba lui, Abercrombie este teafar si nevatamat, amuzat in tacere de ingrijorarea orasului. Explica faptul ca drumurile periculoase si varsta inaintata facusera calatoria prea anevoioasa.",al={"Abercrombie este bine","moare pustnicul","a fost atacat pustnicul"}},{q="De ce ar alege cineva sa locuiasca chiar langa Raven Hill Cemetery?",a="Abercrombie spune ca prefera singuratatea, desi multi calatori considera nelinistitor sa traiesti in umbra unuia dintre cele mai corupte de necromantie cimitire din Eastern Kingdoms.",al={"de ce sa locuiesti langa Raven Hill","coliba lui Abercrombie din cimitir","de ce sta pustnicul langa morminte"}},{q="Ce ii cere Abercrombie dupa ce ajungi la el?",a="Abercrombie abia asteapta sa profite de prezenta unui aventurier in putere la usa sa, cerandu-i imediat ajutorul pentru diverse comisioane si treburi prin padure.",al={"ce vrea Abercrombie","misiunea urmatoare a pustnicului","ce urmeaza dupa The Hermit"}}},fx={e8a34d53={q="De ce ii cere Elaine Carevin unui aventurier sa verifice ce face Abercrombie?",a="Night Watch-ul local din Darkshire este deja periculos de suprasolicitat, aparand perimetrul impotriva bestiilor nesatule, a worgenilor salbatici si a mortilor nelinistiti. O calatorie in adancul padurilor vestice, pana la Raven Hill, doar pentru a verifica ce mai face un pustnic excentric este un lux pe care paznicii orasului nu si-l pot permite, asa ca singura optiune reala sunt calatorii capabili.",al={"de ce sa ma trimita","de ce are Elaine nevoie de un aventurier","de ce nu verifica garzile situatia pustnicului"}}},fp="10,225,21.461.0,25.419.0,23.140.0,28.125.0,41.179.0,52.190.0,66.189.0,49.174.0"}
P.entries["quest:1650"] = {n="The Tome of Valor",s="Duthorian Rall trimite un Paladin sa o protejeze pe Daphne Stilwell pe tarmul indepartat din Westfall. Cu sotul ei plecat, banditii Defias ii ameninta gospodaria.",h="Duthorian Rall trimite un Paladin sa o protejeze pe Daphne Stilwell pe tarmul indepartat din Westfall.",kw={"daphne stilwell","defias brotherhood","duthorian rall","jordan stilwell","longshore","stormwind","tome of valor","westfall"},ang={["class:Paladin"]="Ca paladin, parasesti siguranta catedralei din Stormwind pentru a-i proteja pe cei lipsiti de aparare si a-ti dovedi vitejia.",["faction:Alliance"]="Gospodaria Stilwell arata cat de departe a cazut Westfall de sub protectia Stormwind, lasand oamenii de la tara sa infrunte singuri Defias."},sec={{t="Un Call to Arms",b="La Cathedral of Light din Stormwind, Duthorian Rall ii pune la incercare pe aspirantii la rangul de paladin, cerandu-le sa apere oamenii regatului. Dupa ce accepti mantia vitejiei, pui aceste idealuri in practica acolo unde legea si autoritatea au dat gres."},{t="Pericol pe Longshore",b="Daphne Stilwell si sotul ei, Jordan, au un avanpost la Longshore, in locul izolat din Westfall. Jordan este plecat in Ironforge, unde se consulta cu fierari Dwarf, iar activitatea Defias Brotherhood e intensa. Duthorian te trimite spre vest ca s-o aperi pe Daphne inainte ca hotii sa-i copleseasca gospodaria."}},faq={{q="De ce este Daphne Stilwell singura in Westfall?",a="Sotul ei, Jordan Stilwell, a calatorit la Ironforge pentru a se consulta cu alti fierari. Cat timp el lipseste, Daphne infrunta singura atacurile tot mai dese ale Defias asupra proprietatii lor de pe coasta.",al={"unde este sotul lui daphne","de ce a plecat jordan stilwell","daphne stilwell singura"}},{q="Cine ii incredinteaza aceasta sarcina paladinului?",a="Duthorian Rall ti-o incredinteaza. El antreneaza paladini la Cathedral of Light din Stormwind si iti da insarcinarea dupa ce dovedesti ca esti pregatit pentru incercarile curajului.",al={"cine ofera tome of valor 1650","cel care da misiunea tome of valor","misiunea lui duthorian rall"}},{q="Unde poate fi gasita Daphne Stilwell?",a="Daphne locuieste intr-o casuta in capatul sudic al Longshore, de-a lungul coastei din sud-vestul Westfall.",al={"unde se afla daphne stilwell","locatia lui daphne stilwell","gaseste-o pe daphne stilwell"}},{q="Este Daphne complet neajutorata cand ajungi?",a="Nu. Pana ajungi la prispa ei, Daphne a ucis deja cu propria arma o jumatate de duzina de banditi Defias, aparandu-si gospodaria.",al={"poate lupta Daphne","este Daphne lipsita de aparare","Daphne Stilwell se lupta"}},{q="Ce amenintare pandeste casa familiei Stilwell?",a="Defias Brotherhood ameninta casa familiei Stilwell. Brotherhood a ocupat mare parte din Westfall si continua sa hartuiasca gospodaria izolata de pe coasta, cautand sa puna stapanire pe pamant si sa prade ce a mai ramas.",al={"cine o ataca pe Daphne","Defias din Westfall","dusmanii de la ferma Stilwell"}},{q="Cum se incadreaza aceasta sarcina in seria Tome of Valor?",a="Vitejia unui Paladin se masoara prin sacrificiu si prin apararea celor lipsiti de aparare. Ocrotirea lui Daphne de banditii jefuitori pune dreptatea in practica.",al={"de ce trebuie sa o ajut pe Daphne","scopul incercarii Tome of Valor","semnificatia acestei misiuni"}}},fx={ef242344={q="De ce te trimite Duthorian Rall la Daphne Stilwell?",a="Duthorian Rall vrea sa-ti puna la incercare hotararea si devotamentul fata de virtutile Light. In timp ce sotul ei, Jordan, calatoreste la Ironforge pentru a face schimb de cunostinte despre fierarie, Daphne Stilwell a ramas singura in Westfall, tocmai cand Defias Brotherhood cotropeste coasta. Sa te trimita sa aperi un civil lipsit de aparare este atat o datorie dreapta, cat si o adevarata proba de vitejie.",al={"de ce vrea Duthorian Rall acest lucru","motivul lui duthorian rall","de ce trimite paladin la daphne"}},["49096f91"]={q="De ce are Duthorian Rall nevoie de tine in locul garzii orasului Stormwind?",a="Westfall se afla departe de siguranta oferita de zidurile Stormwind, neglijat de Coroana si napadit de banditi. Garzile orasului sunt ocupate pana peste cap cu apararea Elwynn si gestionarea tulburarilor urbane. Pentru Church of the Holy Light, ocrotirea gospodarilor lipsiti de aparare este chemarea solemna a paladinilor, ceea ce face din aceasta misiune primejdioasa incercarea ideala pentru a dovedi ca esti vrednic de Tome of Valor.",al={"de ce eu, Duthorian Rall","de ce sa nu trimita garzile la Daphne","de ce sa trimita un initiat"}}},fp="17,148,14.221.0,22.280.0,41.169.0,37.145.0,35.104.0,46.141.0,42.200.0,52.149.0"}
P.entries["quest:1651"] = {n="The Tome of Valor",s="La ferma lui Daphne Stilwell din Westfall, un paladin infrunta o proba de vitejie. Defias Brotherhood ameninta gospodaria, iar Daphne are nevoie de un aparator alaturi de ea.",h="La ferma lui Daphne Stilwell din Westfall, un paladin infrunta o proba de vitejie.",kw={"Daphne Stilwell","Defias Brotherhood","jefuitori Defias","incercarea de paladin","Tome of Valor","Westfall"},ang={["class:Paladin"]="In calitate de paladin, esti pus la incercare ca protector neclintit. Sa tii linia alaturi de Daphne inseamna sa dai dovada de vitejie: aparand nevinovatii de primejdii.",["faction:Alliance"]="Garnizoana din Stormwind este raspandita si nu poate pazi gospodariile rurale. Apararea cetatenilor loiali din Westfall le revine eroilor care actioneaza pe cont propriu."},sec={{t="O infruntare in praf",b="Gospodaria lui Daphne Stilwell din Westfall se afla pe un teritoriu disputat de Defias Brotherhood. In timp ce cauti virtutile consemnate in Tome of Valor, esti trimis sa-i aperi ferma. Defias au incercat in repetate randuri sa cucereasca proprietatea si sa o ucida pe Daphne. Dupa ciocnirile anterioare, se asteapta un nou atac. Trebuie sa ramai langa casa ei, nu sa te retragi intr-un loc mai sigur."},{t="Incercarea curajului",b="Tu si Daphne infruntati val dupa val de jefuitori Defias. Ea are doar arma de foc personala, in timp ce tu ai binecuvantarile lui Holy Light. Lupta pune la incercare capacitatea ta de a proteja pe cineva vulnerabil, aflat sub o presiune uriasa. Adevarata vitejie nu inseamna urmarirea gloriei personale, ci vointa de a te interpune intre civili nevinovati si violenta necrutatoare."}},faq={{q="Cine este Daphne Stilwell?",a="Daphne Stilwell este o fermiera Human care traieste in campiile inierbate din Westfall. Desi Defias Brotherhood ii incalca deseori proprietatea, ea refuza sa plece si le tine piept raidurilor.",al={"daphne stilwell","cine este daphne","stilwell din westfall"}},{q="De ce ataca Defias tocmai aceasta ferma?",a="Defias Brotherhood a pus stapanire pe mare parte din tinuturile rurale ale Westfall, alungand fermierii sau silindu-i sa se supuna. Sotul lui Daphne, Jordan, este plecat in Ironforge, lasand-o singura si fara aparare, iar Defias vor pamantul ei.",al={"de ce ataca Defias","raidul Defias asupra lui Daphne","de ce sa-l atace pe Stilwell"}},{q="Ce este Tome of Valor?",a="Tome of Valor este un text sacru pe care Church of the Holy Light il foloseste pentru a-i indruma pe tinerii paladini. Cavalerii in pregatire trec prin incercari fizice si spirituale in tot regatul, ca sa traiasca potrivit virtutilor sale.",al={"ce este Tome of Valor","misiunea Tome of Valor","tome-ul valorii pentru Paladin"}},{q="Ce se intampla daca Daphne cade in lupta?",a="Daca Daphne Stilwell cade in lupta, incercarea esueaza. Vitejia cere sa-i protejezi viata, precum si pe a ta, de atacul banditilor.",al={"poate daphne sa moara","daphne stilwell moare"}},{q="Unde are loc acest atac?",a="Atacul are loc in fata fermei lui Daphne Stilwell, o mica gospodarie din Dagger Hills, cu vedere spre Longshore, in sudul Westfall.",al={"locatia Daphne Stilwell","unde este ferma"}},{q="Ce urmeaza dupa apararea fermei?",a="Dupa ce iti dovedesti curajul si alungi jefuitorii Defias, Daphne iti recunoaste devotamentul si te indruma spre urmatoarea etapa a incercarilor tale de paladin.",al={"misiunea urmatoare Tome of Valor","dupa ce o aperi pe Daphne"}}},fx={dca50aad={q="De ce are Daphne Stilwell nevoie de ajutorul tau pentru a apara ferma?",a="Westfall este in mare parte abandonat de armata din Stormwind, lasandu-i pe colonisti sa se descurce singuri in fata valului tot mai mare de proscrisi. Desi Daphne este hotarata sa-si apere casa si are o arma de foc in interior, nu poate rezista singura unui atac organizat. Un val anterior a pus-o deja la incercare, iar ea stie ca raidul care se apropie va aduce mult mai multi proscrisi decat ar putea spera vreodata sa infrunte un colonist singuratic.",al={"de ce s-o ajuti pe Daphne Stilwell","de ce nu se poate apara Daphne","de ce sa o ajuti pe Daphne Stilwell"}},["3da31dda"]={q="De ce vrea Daphne Stilwell sa opuna rezistenta?",a="Ferma aceasta este mijlocul de trai al lui Daphne Stilwell si dovada incapatanarii sale de a nu se lasa alungata de haiduci. In loc sa fuga ori sa-si cedeze pamantul banditilor care au cotropit Westfall, ea alege sa-si apere locul. Ocrotirea gospodariei este o chestiune de supravietuire si mandrie; daca cedeaza aici, pierde tot ce a cladit.",al={"motivul lui daphne stilwell","de ce sa lupti cu defias, daphne","de ce vrea daphne sa ramana"}},["7af5f29f"]={q="Cine sunt atacatorii Defias care ii ataca ferma lui Daphne Stilwell?",a="Atacatorii sunt jefuitori Defias, membri ai unei fratii criminale raspandite, care terorizeaza Westfall. Ei opereaza in toata regiunea, ocupand ferme parasite, stoarcandu-i pe locuitori si alungand cu forta pe oricine li se impotriveste. Refuzul lui Daphne de a-si parasi casa face din gospodaria ei o tinta de prim rang pentru un raid coordonat, menit sa zdrobeasca orice urma de rezistenta civila.",al={"cine sunt atacatorii","ce sunt jefuitorii Defias","Defias ataca ferma Stilwell"}}},fp="17,163,19.375.0,18.346.0,23.194.0,48.225.0,26.191.0,47.132.0,34.140.0,36.158.0"}
P.entries["quest:1652"] = {n="The Tome of Valor",s="La Cathedral of Light din Stormwind soseste vestea ca Daphne Stilwell este in siguranta. Dupa ce si-a aparat gospodaria din Westfall de banditi, un paladin aspirant se prezinta la Duthorian Rall, incheind incercarile de vitejie ale Church of the Holy Light. Menirea Bisericii este sa-i apere pe nevinovati fara sa se gandeasca la propria persoana.",h="La Cathedral of Light din Stormwind soseste vestea ca Daphne Stilwell este in siguranta.",kw={"cathedral of light","daphne stilwell","duthorian rall","ironforge","jordan stilwell","stormwind","tome of valor","westfall"},ang={["class:Paladin"]="Ca Paladin, raportandu-te lui Duthorian Rall iti inchei lectia despre curaj si arati altruismul asteptat de la un aparator sfant al Alliance.",["faction:Alliance"]="In calitate de membru al Alliance, poti vedea cum problemele familiei Stilwell leaga tinuturile agricole human din Westfall de atelierele dwarven din Ironforge. Povestea lor arata cum Alliance depinde de ajutorul dintre tinuturi indepartate."},sec={{t="Un scut sacru",b="Gospodaria lui Daphne Stilwell din Westfall este in siguranta dupa ce un novice al Church of the Holy Light a aparat-o de banditi. Inapoi la Cathedral of Light din Stormwind, aspirantul la rangul de Paladin ii da de veste lui Duthorian Rall ca ea este teafara. Apararea gospodarieii dovedeste curajul si convingerea asteptate de la cineva care se interpune intre primejdie si cei lipsiti de aparare."},{t="Legaturi intre regate",b="Sotul lui Daphne, Jordan Stilwell, se afla in Ironforge, unde isi pune maiestria vestita in slujba Alliance. Cu Daphne in siguranta si gospodaria pazita, Duthorian Rall se pregateste sa-i trimita vesti lui Jordan, in nord. Linistit ca familia sa este protejata, mesterul se poate concentra asupra lucrului sau. Caminurile lor indepartate sunt unite de ajutorul pe care Alliance il ofera pe intregul sau teritoriu."}},faq={{q="Cine este Duthorian Rall?",a="Duthorian Rall este un instructor senior de paladini la Cathedral of Light din Stormwind. El ii indruma pe tinerii paladini prin incercari spirituale si martiale, invatandu-i vitejia, dreptatea si umilinta.",al={"Duthorian Rall","cine este Duthorian","antrenor de Paladin din Stormwind"}},{q="De ce era Daphne Stilwell in pericol?",a="Daphne Stilwell era in pericol fiindca banditii asediasera ferma ei izolata din Westfall. Sotul ei, Jordan, era plecat la lucru in Ironforge.",al={"daphne stilwell","ferma stilwell","cine a atacat-o pe daphne"}},{q="Cine este Jordan Stilwell?",a="Jordan Stilwell este sotul lui Daphne, un fierar si mestesugar priceput. Se afla in Ironforge, ajutand Alliance prin munca sa, in timp ce Church ii protejeaza sotia acasa.",al={"jordan stilwell","sotul lui Daphne","jordan din Ironforge"}},{q="Ce este Tome of Valor?",a="Tome of Valor este o carte sfanta cu lectii legate de incercari practice oferite de Cathedral of Light. Prin ele, paladinii isi dovedesc curajul infruntand intunericul si aparandu-i pe cei vulnerabili cu pretul propriei sigurante.",al={"sensul lui tome of valor","ce este tome of valor"}},{q="Ce urmeaza dupa incheierea acestei incercari?",a="Dupa ce Duthorian Rall iti recunoaste eforturile de a o apara pe Daphne Stilwell, te indruma spre Test of Righteousness, urmatorul pas in evolutia ta spirituala si martiala.",al={"urmatoarea misiune dupa tome of valor","ce urmeaza"}},{q="De ce ii pasa Bisericii de gospodaria familiei Stilwell?",a="Bisericii ii pasa de gospodaria familiei Stilwell, deoarece Daphne si Jordan au ajutat-o prin credinta si maiestrie. Sa o protejeze pe Daphne cat timp Jordan este plecat inseamna sa respecte promisiunea Bisericii de a avea grija de ai sai.",al={"de ce ajuta biserica daphne","biserica si familia stilwell"}}},fx={["9332b34b"]={q="De ce vrea Daphne Stilwell sa te intorci sa-i raportezi lui Duthorian Rall?",a="Daphne vrea ca Duthorian Rall sa afle ca este in siguranta si ca gospodaria a supravietuit atacului, dar cea mai mare grija a ei este sotul sau, Jordan. Jordan este plecat la lucru in Ironforge, iar Daphne stie ca se va ingrijora fara incetare pana cand va primi vesti de acasa. Daca se intoarce la Church of the Light din Stormwind, Duthorian ii poate trimite vorba in Ironforge, ca sa-l linisteasca pe Jordan si sa-i spuna ca sotia si casa lui sunt in siguranta.",al={"de ce sa mergi la Duthorian","motivul lui Daphne Stilwell","de ce sa vorbesti cu Duthorian Rall"}}},fp="17,316,15.335.0,21.361.0,22.185.0,34.134.0,23.171.0,26.211.0,39.171.0,54.217.0"}
P.entries["quest:1653"] = {n="The Test of Righteousness",s="In Ironforge, vestile bune despre sotia lui ajung la Jordan Stilwell. Duthorian Rall te trimite din Westfall sa-i spui fierarului credincios ca Daphne a supravietuit atacului Defias.",h="In Ironforge, vestile bune despre sotia lui ajung la Jordan Stilwell.",kw={"daphne stilwell","defias brotherhood","dun morogh","duthorian rall","ironforge","jordan stilwell","stormwind","test of righteousness"},ang={["class:Paladin"]="Ca Paladin, treci de la protejarea celor slabi la crearea unor unelte sacre pentru a curata raul de pe intreg teritoriul Alliance.",["faction:Alliance"]="Ca membru al Alliance, vezi cum oamenii de rand din Westfall se lupta cu Defias, in timp ce sfetnicii regali din Stormwind amana actiunea.",["profession:Blacksmithing"]="Ca fierar, poti vedea cum munca lui Jordan la nicovala ii exprima devotamentul la fel de limpede ca manuirea unei lame consacrate in lupta."},sec={{t="Un mesager cu vesti bune",b="Duthorian Rall te trimite din Cathedral Square cu o veste pentru Jordan Stilwell. Ai pazit-o pe Daphne Stilwell in timpul unei ambuscade Defias la gospodaria ei din Westfall, iar ea a supravietuit. Sotul ei a plecat spre Ironforge, crezand ca familia era in pericol. Rall te roaga sa-i duci vestea personal, ca Jordan sa afle ca sotia lui este in siguranta."},{t="Fierarul din Dun Morogh",b="Jordan Stilwell era menit candva sa se alature ordinului de Paladin, dar a ales sa urmeze mestesugul tatalui sau si sa devina un maestru faurar de arme. Lucreaza la nicovala din fata portilor Ironforge, pastrandu-si credinta in timp ce faureste arme. Cand ii spui ca Daphne a supravietuit atacului Defias, recunostinta il indeamna sa te ajute sa fauresti o arma binecuvantata a dreptatii."}},faq={{q="Cine este Jordan Stilwell?",a="Jordan Stilwell este un fierar de arme devotat, care lucreaza in afara portilor din Ironforge. A studiat candva caile Light alaturi de paladini, apoi a ales sa continue mestesugul tatalui sau.",al={"Jordan Stilwell","cine este Jordan","fierarul din Ironforge"}},{q="De ce era sotia lui Jordan in pericol?",a="Daphne Stilwell locuieste la o ferma din Westfall, unde nelegiuitii din Defias Brotherhood ii ameninta pe oameni. Jordan s-a temut de un atac cand a plecat spre Ironforge. Banditii au luat ferma cu asalt, dar initiatii paladini i-au alungat.",al={"pericolul pentru Daphne Stilwell","ce i s-a intamplat sotiei lui Jordan","de ce au atacat Defias"}},{q="Unde poate fi gasit Jordan Stilwell?",a="Jordan Stilwell lucreaza in afara portilor principale ale Ironforge, in Dun Morogh. Prefera aerul de munte in locul Great Forge din oras.",al={"unde se afla Jordan Stilwell","locatia lui Stilwell","locatia lui Jordan in Ironforge"}},{q="De ce il trimite Duthorian Rall pe jucator la Ironforge?",a="Duthorian Rall te trimite sa-i spui lui Jordan ca Daphne a supravietuit atacului Defias. Calatoria te duce si la un mester fierar care te poate indruma sa faci o arma sacra de paladin.",al={"de ce sa mergi la Ironforge","treaba lui Duthorian Rall","motivul mesajului"}},{q="Ce urmeaza dupa ce vorbesti cu Jordan?",a="Dupa ce aude vestea, Jordan se ofera sa te ajute sa forjezi un ciocan de razboi sfant. Iti cere sa aduni materiale rare si relicve sfintite din tinuturi indepartate.",al={"urmatorul pas dupa Test of Righteousness","ce vrea Jordan","dupa ce vorbesc cu Jordan"}},{q="Ce parere are Jordan despre amenintarea Defias?",a="Jordan este furios pe consiliul din Stormwind si pe nepasarea acestuia. Defias Brotherhood a chinuit Westfall de multa vreme, iar el spera ca atacurile asupra fermelor oamenilor cinstiti ii vor sili pe regentii tanarului rege sa infrunte criza.",al={"parerea lui Jordan despre Defias","sfetnicii regelui Stilwell","Defias in Westfall"}}},fx={c7e3478b={q="De ce te trimite Duthorian Rall la Jordan Stilwell?",a="Jordan Stilwell a plecat spre Ironforge fara sa stie daca locuinta si sotia lui au supravietuit atacului devastator al Defias din Westfall. Dupa ce ti-a pus vitejia la incercare si ti-ai aparat familia, Duthorian Rall vrea sa-i aduca liniste sufleteasca fierarului. Trimitandu-te pe tine, bucuria vestii ii va parveni direct de la paladinul care i-a raspuns chemarii.",al={"de ce ma trimite la Jordan","motivul lui Duthorian Rall","de ce sa-l vizitez pe Jordan Stilwell"}},["26f62cea"]={q="De ce te alege Duthorian Rall pentru aceasta treaba in locul unui mesager obisnuit?",a="Tu i-ai infruntat de fapt pe Defias pentru a o salva pe sotia lui Jordan. In loc sa aiba incredere intr-un curier impersonal, Duthorian crede ca Jordan merita sa primeasca vestea cea buna direct de la salvatorul familiei sale, continuandu-ti indrumarea pe calea Light alaturi de un aliat profund apropiat de ordinul paladinilor.",al={"de ce ma trimite pe mine in loc sa trimita un mesager","de ce duc eu mesajul","de ce eu Test of Righteousness"}}},fp="25,170,24.326.0,23.334.0,23.186.0,32.219.0,35.131.0,53.178.0,38.152.1,45.214.0"}
P.entries["quest:1656"] = {n="A Task Unfinished",s="A Task Unfinished este o simpla misiune de livrare, care scoate in evidenta greutatile indurate de tinerii tauren in timpul ritualurilor de maturizare de pe Red Cloud Mesa. Impovarat de cerintele incercarilor si de o sarcina de familie, un tanar istovit roaga un calator aflat in trecere sa duca un pachet de blanuri la Innkeeper Kauth, in Bloodhoof Village.",h="A Task Unfinished este o simpla misiune de livrare, care scoate in evidenta greutatile indurate de tinerii...",kw={"o sarcina neterminata","Bloodhoof Village","pachet de blanuri","hangiul Kauth","Mulgore","Red Cloud Mesa","Rite of Strength","tauren"},ang={["faction:Horde"]="Bloodhoof Village este un popas esential pentru calatorii din Mulgore, oferind adapost primitor si vetre calde membrilor Horde care strabat campiile.",["race:Tauren"]="Tinerii Tauren trec prin incercari istovitoare pe Red Cloud Mesa pentru a-si dovedi maturitatea si forta, iar indatoririle tribale si familiale le pun adesea rezistenta la incercare la fel de mult ca probele ritualice."},sec={{t="Incercari pe platou",b="Sus, pe Red Cloud Mesa, tinerii tauren trec prin incercari riguroase de initiere, pentru a-si dovedi pregatirea pentru lumea larga. Imbinarea ritualurilor traditionale cu treburile obisnuite ale tribului poate impinge un tanar pana la epuizare fizica. Cu un Rite of Strength neterminat si o treaba urgenta de la tatal sau, un tanar tauren cere ajutorul unui calator aflat in trecere, pentru a duce un balot de blanuri jos de pe mesa."},{t="Vatra si adapost",b="Destinatia blanurilor este Bloodhoof Village, un adapost primitor aflat in campiile deschise de dedesubt. Hangita Kauth primeste cu nerabdare livrarea, intentionand sa transforme blanurile in paturi calduroase pentru calatorii istoviti. Misiunea scoate in evidenta atat ospitalitatea taurenilor de pe campii, cat si importanta odihnei, aratand ca sprijinul comunitatii sta la temelia fiecarei incercari solitare de a-ti dovedi puterea."}},faq={{q="Ce este misiunea A Task Unfinished?",a="A Task Unfinished este o sarcina incredintata de un tanar tauren istovit, aflat pe Red Cloud Mesa. Coplesit de incercarile neintrerupte ale Rite of Strength, tanarul ii cere unui calator sa-i duca in locul lui un balot de blanuri hangiului din Bloodhoof Village.",al={"ce este A Task Unfinished","informatii despre misiunea A Task Unfinished","cine ofera misiunea A Task Unfinished"}},{q="Cine este Innkeeper Kauth?",a="Innkeeper Kauth administreaza hanul local din Bloodhoof Village, in Mulgore. Le ofera un loc primitor pentru odihna, paturi calde si ospitalitate calatorilor obositi care strabat campiile venind de pe platourile inalte.",al={"cine este hangiul Kauth","unde se afla Kauth","hangiul din Bloodhoof Village"}},{q="De ce sunt duse blanurile la han?",a="Legatura de blanuri este o livrare ceruta de tatal tanarului tauren pentru hangiul Kauth. Kauth foloseste aceste blanuri rezistente drept paturi calduroase pentru oaspetii care cauta adapost si odihna la hanul sau din Bloodhoof Village.",al={"de ce sa livrezi blanuri","la ce folosesc blanurile","pachet de blanuri pentru Mulgore"}},{q="De ce nu au putut tinerii Tauren sa livreze singuri blanurile?",a="Tanarul tauren indeplineste acum Rite of Strength pe Red Cloud Mesa. Efortul fizic cerut de incercare il lasa mult prea epuizat ca sa poata cobori pana la Bloodhoof Village fara sa-si compromita ritualul sacru sau sa se prabuseasca de oboseala.",al={"de ce nu poate cel care da misiunea sa livreze blanurile","de ce are tanarul nevoie de ajutor"}},{q="Ce este Rite of Strength?",a="Rite of Strength este una dintre incercarile fundamentale de maturizare pentru tinerii tauren de pe mesa. Le pune la incercare rezistenta fizica, perseverenta si capacitatea de a deveni viitori aparatori ai tribului.",al={"ce este Rite of Strength","incercarea Rite of Strength pentru Tauren"}},{q="Unde este situat Bloodhoof Village?",a="Bloodhoof Village este o asezare importanta situata pe campiile domoale din Mulgore, sub inaltimile adapostite ale Red Cloud Mesa. Aici se gasesc facilitati tribale centrale, printre care un han deschis tuturor, materiale pentru mestesuguri si puncte comerciale.",al={"unde se afla Bloodhoof Village","locatia Bloodhoof Village"}}},fp="17,319,18.404.0,18.390.0,36.262.0,23.212.0,44.207.0,58.254.0,29.195.0,36.233.0"}
P.entries["quest:166"] = {n="The Defias Brotherhood",s="Aceasta misiune incununeaza campania indelungata a lui Gryan Stoutmantle de a elibera Westfall de sub stapanirea proscrisilor. Dupa ce patrund in Deadmines, campionii din Alliance trebuie sa strapunga ascunzatoarea criminalilor si sa-l doboare pe insusi creierul din spatele complotului, Edwin VanCleef.",h="Aceasta misiune incununeaza campania indelungata a lui Gryan Stoutmantle de a elibera Westfall de sub...",kw={"Deadmines","cap","juggernaut","militie","Moonbrook","zidari","Stoutmantle","VanCleef","Westfall"},ang={["class:Rogue"]="VanCleef este un rogue legendar si un maestru mestesugar; infruntarea lui in sanctuarul sau interior pune la incercare pregatirea martiala a oricarui agent specializat in furisare.",["faction:Alliance"]="Aceasta misiune marcheaza o victorie timpurie esentiala pentru Alliance, asigurand hambarul Westfallului atunci cand tronul Stormwindului nu-si poate trimite propriile trupe.",["race:Human"]="Pentru oamenii regatului, uciderea lui VanCleef este o tragedie dulce-amara: il doboara chiar pe mesterul ale carui maini le-au recladit capitala din cenusa."},sec={{t="O sentinta pronuntata",b="De luni intregi, Gryan Stoutmantle si incercata People's Militia duc o lupta disperata pentru a-si mentine pozitiile impotriva Defias Brotherhood in Westfall. Acum ca adevarata locatie a fortaretei hotilor a fost descoperita sub Moonbrook, Stoutmantle emite decretul sau final si sumbru: Edwin VanCleef trebuie asasinat pentru a zdrobi o data pentru totdeauna rebeliunea."},{t="In labirint",b="Pentru a duce la bun sfarsit executia, luptatorii trebuie sa patrunda adanc in puturile intortocheate din Deadmines. Dincolo de pietrarii renegati, inginerii goblini si portile grele de fier pentru explozibili se afla docul uscat central, unde VanCleef supravegheaza constructia finala a grandioasei sale nave de razboi. Taierea capului sau decapiteaza structura de comanda care tine laolalta intreaga retea de proscrisi."},{t="Umbrele unei conspiratii mai ample",b="Desi Stoutmantle crede ca moartea lui VanCleef vesteste inceputul sfarsitului pentru Brotherhood, cadavrul fostului maestru de breasla ascunde secrete tulburatoare. Asupra lui se afla o scrisoare netrimisa, care sugereaza ca revolta din Westfall nu a fost o rascoala izolata, ci parte dintr-o tesatura mai vasta si mai intunecata, care ajunge pana in sanul nobilimii din Stormwind City."}},faq={{q="Care este scopul acestei misiuni?",a="Gryan Stoutmantle iti da sarcina sa patrunzi in temnita Deadmines din Moonbrook, sa-l elimini pe Edwin VanCleef si sa te intorci la Sentinel Hill cu capul lui taiat.",al={"obiectivul misiunii","ce trebuie sa fac","despre ce este misiunea asta"}},{q="Cine este Edwin VanCleef?",a="Edwin VanCleef a fost candva Marele Zidar al Stonemasons Guild, pe care a condus-o in timpul reconstruirii Stormwind City, dupa ce orcs au ras orasul in First War. In urma unei dispute aprinse cu House of Nobles privind plata, a infiintat Defias Brotherhood pentru a se razbuna pe regat.",al={"cine este vancleef","identitatea lui vancleef","povestea lui edwin vancleef"}},{q="De ce ordona Gryan Stoutmantle un asasinat?",a="People's Militia nu dispune de intaririle armatei regulate din Stormwind, necesare pentru a purta un razboi de durata. Stoutmantle intelege ca eliminarea conducerii este singura sansa realista a celor din Westfall de a rupe stransoarea sindicatului asupra terenurilor agricole.",al={"de ce sa-l omori pe VanCleef","motivul lui Stoutmantle","de ce pedeapsa cu moartea"}},{q="Unde poate fi gasit Edwin VanCleef?",a="Este ascuns adanc in Deadmines, sub Moonbrook. Gryan Stoutmantle iti cere sa intri in ascunzatoare si sa-l gasesti.",al={"locatia lui VanCleef","unde se afla Edwin VanCleef","locatia sefului Deadmines"}},{q="Distrugerea lui VanCleef pune capat definitiv gruparii Defias?",a="Stoutmantle spera ca moartea lui VanCleef va destrama stapanirea Fratiei asupra Westfall. Deznodamantul si orice descoperiri ulterioare vor astepta pana la asalt.",al={"au fost invinsi Defias","au disparut Defias","sfarsitul Fratiei"}},{q="Ce obiect important se gaseste asupra lui VanCleef dupa ce este invins?",a="Stoutmantle cere capul lui VanCleef drept dovada. Alte descoperiri din ascunzatoare sunt dezvaluite pe parcursul misiunii.",al={"prada lui VanCleef","scrisoare netrimisa","ce lasa VanCleef"}}},fx={e9d4d384={q="La ce foloseste Head of VanCleef?",a="Gryan Stoutmantle cere dovezi incontestabile ca Edwin VanCleef este intr-adevar mort. Defias Brotherhood a terorizat Westfall din umbra vreme de ani intregi, raspandind zvonuri si evitand sa fie prins. Aducerea capului taiat al lui VanCleef pune capat indoielilor People's Militia si le arata fermierilor aflati sub asediu ca cel mai mare chinuitor al lor a fost, in sfarsit, doborat.",al={"de ce sa iau capul lui VanCleef","scopul Head of VanCleef","de ce am nevoie de capul lui VanCleef"}},["48642626"]={q="De ce te trimite Gryan Stoutmantle in locul People's Militia?",a="People's Militia abia mai face fata apararii Sentinel Hill si a gospodariilor rasfirate din Westfall impotriva raidurilor zilnice ale banditilor si incursiunilor gnollilor. Stormwind a refuzat sa trimita intariri, lasandu-l pe Stoutmantle fara forta de atac grea si disciplinata de care are nevoie pentru a patrunde in adancurile fortificate ale Deadmines. Trebuie sa se bazeze pe aventurieri incercati si capabili, precum tine, ca sa loveasca direct in inima conspiratiei.",al={"de ce nu ataca militia Deadmines","de ce ma trimit impotriva lui VanCleef","de ce nu-l ucide Stoutmantle pe VanCleef"}}},fp="22,257,17.364.0,18.354.1,31.343.1,31.164.0,22.284.0,50.257.0,34.123.0,52.140.1,55.115.1"}
P.entries["quest:1665"] = {n="Bartleby's Mug",s="In Stormwind, Bartleby's Mug marcheaza proba de curaj a unui tanar warrior. Dupa ce il invingi pe Bartleby in Pig and Whistle Tavern, ii iei cana de baut instructorului tau, Harry Burlguard.",h="In Stormwind, Bartleby's Mug marcheaza proba de curaj a unui tanar warrior.",kw={"bartleby","garda de blana","cana","orasul vechi","porcul si fluierul","stormwind","warrior"},ang={["class:Warrior"]="Ca Warrior in Stormwind, dovedesti ca poti infrunta de la egal la egal dusmani indisciplinati luand halba lui Bartleby.",["faction:Alliance"]="Ca membru al Alliance, stii ca petrecaretii turbulenti din Old Town sunt o bataie de cap obisnuita pentru instructorii de lupta din Stormwind."},sec={{t="Trofeul unei incaierari de taverna",b="Harry Burlguard ii pune la incercare pe tinerii Warrior cu o incaierare in Old Town. Iti cere sa-l rapui pe Bartleby, un betiv incapatanat de la barul din Pig and Whistle Tavern. Dupa ce-l domolesti, Bartleby renunta cu parere de rau la halba sa pretioasa, dar mai trage o ultima dusca, sa goleasca drojdia."},{t="Un pas spre maiestrie",b="Ducand cana inapoi la Harry Burlguard iti inchei proba de novice. Burlguard vede ca poti convinge prin forta pura si iti recunoaste pregatirea pentru maiestria defensiva. Te indruma mai departe, spre instruire pe campul de lupta alaturi de Marshal Haggard, un veteran incercat din Elwynn Forest."}},faq={{q="De ce vrea Harry Burlguard cana lui Bartleby?",a="Harry Burlguard vrea halba lui Bartleby ca dovada ca te-ai luptat cu el si l-ai invins. Bartleby tine cu indarjire la bautura lui, asa ca sa renunte la halba personala arata ca a fost infrant categoric si supus.",al={"de ce cana lui bartleby","scopul canii burlguard","dovada ca l-ai batut pe bartleby"}},{q="Cine este Bartleby?",a="Bartleby este un client turbulent la barul din Pig and Whistle, in Old Town, Stormwind. Beat si plin de toane, le ofera instructorilor locali de Warrior o proba neoficiala pentru luptatorii aspiranti.",al={"povestea lui Bartleby","cine este Bartleby the Drunk","Bartleby old town"}},{q="Unde se desfasoara aceasta lupta?",a="Bataia are loc in interiorul Pig and Whistle Tavern din Old Town, Stormwind.",al={"unde este Bartleby","locatia lui Bartleby","lupta de la Pig and Whistle"}},{q="Ce urmeaza dupa ce-i returnezi cana lui Burlguard?",a="Dupa ce Burlguard inspecteaza halba si iti confirma victoria, te invata pozitii defensive avansate. Apoi te trimite in afara portilor orasului, sa-l cauti pe Marshal Haggard in Elwynn Forest.",al={"ce urmeaza dupa cana lui Bartleby","misiunea de dupa Bartleby Mug","misiunea lui Haggard"}},{q="Este Bartleby ranit permanent in incaierare?",a="Nu. Incaierarea nu este letala. Bartleby cedeaza, isi termina bautura, isi da cana si ramane in taverna cu vanatai si mandria ranita.",al={"bartleby e mort","bartleby a murit","bartleby a supravietuit"}},{q="Poate orice clasa din Alliance sa indeplineasca aceasta misiune?",a="Doar Warrior din Alliance parcurg aceasta proba ca parte a antrenamentului de clasa de la nivelul zece, in posturi de lupta si manevre defensive.",al={"cana lui Bartleby este doar pentru Warrior","cine poate face misiunea lui Bartleby","clase pentru misiunea cu cana"}}},fx={["2bbd1f99"]={q="De ce renunta Bartleby la halba lui?",a="Bartleby iti da pretioasa sa cana doar pentru ca l-ai invins cinstit intr-o incaierare de taverna. Nu voia sa se desparta de ea de bunavoie, dar, dupa ce a fost batut mar, cedeaza cu onoare - nu inainte de a termina in graba ce mai ramasese in cana.",al={"de ce da Bartleby halba sa","motivul lui Bartleby","de ce renunta la halba"}}},fp="14,183,24.276.0,21.290.0,45.196.0,16.191.0,33.80.0,48.192.0,48.143.0,37.128.0"}
P.entries["quest:1666"] = {n="Marshal Haggard",s="La Eastvale, Marshal Haggard pastreaza armele adunate de-a lungul unei vieti de slujire. Harry Burlguard ii trimite la el pe razboinicii incepatori din Stormwind City, ca sa-l intalneasca pe marshalul pensionat si sa caute arme mai bune.",h="La Eastvale, Marshal Haggard pastreaza armele adunate de-a lungul unei vieti de slujire.",kw={"eastvale","eastvale logging camp","elwynn forest","harry burlguard","marshal haggard","stormwind","warrior"},ang={["class:Warrior"]="Ca Warrior al Alliance, parasesti pregatirea formala din Stormwind si pornesti in salbaticie in cautare de arme.",["faction:Alliance"]="Ca luptator al Alliance, urmaresti modul in care Stormwind se bazeaza pe veteranii retrasi si proviziile lor personale pentru a pregati urmatoarea generatie de aparatori."},sec={{t="Arsenalul unui veteran",b="Warrior novice din Stormwind au nevoie de mai mult decat indemanare ca sa infrunte pericolele de dincolo de oras. Harry Burlguard ii trimite pe luptatorii promitatori spre est, prin Elwynn Forest, ca sa-l gaseasca pe Marshal Haggard, un ofiter pensionat care a slujit regatul ani la rand. Haggard a adunat o armura personala de-a lungul unei vieti petrecute pe campul de lupta, iar casa lui de langa Eastvale Logging Camp adaposteste arme pentru Warrior tineri care cauta echipament mai bun."},{t="Retragerea la Eastvale",b="Marshal Haggard locuieste intr-un conac retras, langa Eastvale Logging Camp. Ani de slujire i-au slabit vederea tot mai precara, iar uneori ii ia pe calatorii care se apropie drept gnoll-i Riverpaw care pandesc. Desi varsta il tine in acest colt linistit din estul Elwynn, garzile si instructorii Stormwind il respecta in continuare pe batranul marshal."}},faq={{q="Cine incepe aceasta misiune?",a="Harry Burlguard, instructor de warrior in Stormwind City, ii trimite pe tinerii cu potential la Marshal Haggard.",al={"unde gasesc misiunea lui marshal haggard","cine ofera misiunea lui marshal haggard"}},{q="Unde se afla Marshal Haggard?",a="Marshal Haggard locuieste intr-un conac chiar la est de Eastvale Logging Camp, in extremitatea estica a Elwynn Forest, aproape de granita cu Redridge Mountains.",al={"locatia lui Marshal Haggard","unde se afla Haggard","conacul din tabara de taiat lemne Eastvale"}},{q="De ce te trimite Harry Burlguard la Haggard?",a="Harry Burlguard te trimite la Marshal Haggard, deoarece tinerii Warrior au nevoie de arme mai bune decat sabiile de antrenament. Haggard a adunat arme si armuri in lunga sa cariera si poate ca le va imparti celor care isi dovedesc valoarea.",al={"de ce marshal haggard","de ce sa mergi la eastvale warrior","scopul misiunii lui marshal haggard"}},{q="De ce ii confunda Haggard pe vizitatori cu gnolii?",a="Vederea lui Marshal Haggard s-a inrautatit odata cu varsta. Gnolls hartuie operatiunile de exploatare a lemnului si periferiile din estul Elwynn Forest, facandu-l pe batranul veteran sa se fereasca de musafirii neasteptati.",al={"vederea lui Haggard","este Haggard orb","dialogul gnolului Haggard"}},{q="Ce urmeaza dupa indeplinirea acestei misiuni?",a="Dupa ce il saluti pe Marshal Haggard, acesta iti pune la incercare curajul trimitandu-te sa te ocupi de Dead-tooth Jack, inainte de a se hotari sa-ti imparta armele din depozitele sale.",al={"urmatoarea misiune de la marshal haggard","continuarea dupa marshal haggard"}},{q="Este aceasta misiune disponibila si altor clase in afara de Warrior?",a="Nu. Aceasta cale este destinata Warrior, ca parte a antrenamentului lor in jurul nivelului zece si a pregatirii pentru primejdiile de dincolo de Elwynn Forest.",al={"pot paladinii sa faca misiunea lui marshal haggard","misiunea lui haggard este doar pentru Warrior"}}},fp="15,194,18.386.0,22.325.0,22.104.0,33.137.0,45.223.0,45.169.0,39.150.1,55.129.0"}
P.entries["quest:1667"] = {n="Dead-tooth Jack",s="O insigna furata pune autoritatea lui Marshal Haggard in mainile Defias. Ofiterul pensionat locuieste in estul Elwynn Forest, unde Dead-tooth Jack l-a pacalit sa-i predea insemnul oficial. Jack a purtat pe intuneric o tunica heraldica Stormwind si s-a dat drept Marshal Dughan. Haggard trebuie sa-si recupereze insigna inainte ca Defias Brotherhood sa o foloseasca pentru a se da drept oficiali Stormwind.",h="O insigna furata pune autoritatea lui Marshal Haggard in mainile Defias.",kw={"insigna","Dead-tooth Jack","Defias","Elwynn Forest","gardianul Burlguard","uzurpare de identitate","Marshal Dughan","Marshal Haggard","caseta de valori"},ang={["class:Rogue"]="Ca Rogue, poti vedea cum isprava lui Dead-tooth Jack depinde de deghizare, inselatorie si tupeu la fel de mult ca de jafurile grosolane de drumul mare.",["class:Warrior"]="Marshal Haggard a fost candva un veteran al luptelor din prima linie. Ca Warrior, ii poti castiga recunostinta si poti alege dintre armele de rezerva pastrate din anii sai de serviciu.",["race:Human"]="Pentru tine, un Human din Stormwind, acest furt arata cat de vulnerabile sunt granitele rurale ale regatului in fata infiltratilor Defias. Acestia vor purta culorile coroanei pentru a-i insela pe veteranii retrasi din serviciu."},sec={{t="O inselatorie in intuneric",b="Marshal Haggard locuieste intr-o casuta izolata, pe crestele estice din Elwynn. Intr-o noapte, s-a apropiat de el o silueta purtand o tunica heraldica Stormwind, care sustinea ca are treburi oficiale si i-a cerut vechea insigna de marshal. Crezand ca o inmaneaza unui ofiter coleg, Haggard s-a conformat. Necunoscutul a ras in fata lui si a disparut in padure. Hotul era un Rogue Defias pe nume Dead-tooth Jack."},{t="Ameninarea autoritatii false",b="Marshal Haggard s-a retras din activitate, dar vechiul sau insemn are inca putere legala in Stormwind. Banditii Defias se raspandesc prin Elwynn, Westfall si Redridge, iar insemnul i-ar putea ajuta sa treaca de punctele de control ale garzilor, sa redirectioneze patrulele sau sa preia controlul proviziilor. Jack s-a retras intr-o tabara spre sud si a lasat insemnul incuiat intr-o lada ferecata. Haggard are nevoie sa fie recuperat inainte ca Defias sa provoace pagube serioase."}},faq={{q="Cine este Dead-tooth Jack?",a="Dead-tooth Jack este un agent Defias din estul Elwynn Forest. Sub acoperirea intunericului, s-a dat drept Marshal Dughan si l-a pacalit pe Marshal Haggard, iesit la pensie, sa-i predea insigna oficiala Stormwind.",al={"Dead Tooth Jack","cine este Dead Tooth","povestea lui Dead Tooth Jack"}},{q="De ce are Marshal Haggard nevoie sa-si recupereze insigna?",a="Marshal Haggard are nevoie de insigna sa inapoi, deoarece este un simbol autentic al autoritatii Stormwind. Se teme ca Defias o va folosi pentru a se da drept oficiali, a ocoli patrulele militare si a provoca haos in intregul tinut.",al={"de ce sa recuperezi insigna","insigna lui haggard","de ce conteaza insigna"}},{q="Cum a reusit Jack sa-l pacaleasca pe Marshal Haggard?",a="Jack s-a apropiat noaptea de casuta lui Haggard, purtand o tabarda din Stormwind. In lumina slaba, Haggard l-a confundat cu Marshal Dughan din Goldshire si i-a inmanat insemnul, crezand ca il dadea unui ofiter de-al sau.",al={"cum l-a pacalit pe haggard","haggard a fost pacalit","de ce a dat haggard insigna"}},{q="Unde tine Jack insigna furata?",a="Jack tine insigna incuiata intr-o lada solida, in tabara sa de banditi, la sud de casa lui Marshal Haggard. Poarta asupra sa cheia la lada.",al={"locatia insignei","unde este insigna","tabara dead tooth"}},{q="Cine te-a trimis initial la Marshal Haggard?",a="Harry Burlguard, un razboinic veteran care frecventeaza Pig and Whistle Tavern din Stormwind, ii trimite pe aventurieri la Marshal Haggard. Stie ca fostul marshal ar putea sa renunte la armele de rezerva in schimbul ajutorului.",al={"cine te trimite aici","Burlguard","cine da misiunea"}},{q="Ce se intampla dupa ce este returnata insigna?",a="Marshal Haggard este foarte usurat ca Defias nu-i poate folosi identitatea sau rangul impotriva regatului. Drept multumire, te saluta si iti ofera la alegere arme militare bine intretinute, din anii sai de serviciu.",al={"predarea misiunii","reactia lui Haggard","insigna returnata"}}},fx={["5b8b35d8"]={q="La ce foloseste Marshal Haggard's Badge?",a="Insigna lui Marshal Haggard este un simbol de rang inalt, retras din uz, al Stormwind Army. In maini cinstite, este o mostenire de familie pretuita, ramasa din anii de slujire ai lui Haggard. In mainile Defias Brotherhood, insa, insemnul oficial de maresal le permite hotilor si banditilor sa se dea drept ofiteri din Stormwind, sa treaca de punctele de control si sa puna la cale inselatorii primejdioase in tot regatul.",al={"scopul insignei lui haggard","ce face insigna","de ce este periculoasa insigna"}},["55355d07"]={q="De ce are nevoie Marshal Haggard sa-i recuperezi insigna?",a="Haggard s-a retras de mult si locuieste intr-o casuta izolata, rusinat ca un hot l-a pacalit pe intuneric. Sa le ceara ajutorul garzii orasului sau lui Marshal Dughan ar insemna sa recunoasca faptul ca si-a inmanat insigna oficiala unui hot Defias, iar garzile din Stormwind sunt deja suprasolicitate cu apararea asezarii. Ai venit in cautarea armelor sale de rezerva, oferindu-i ocazia perfecta de a se razbuna cu ajutorul unei persoane capabile si discrete.",al={"de ce are nevoie Haggard de mine","de ce nu se ocupa Haggard singur","de ce sa nu folosim gardienii"}}},fp="15,367,17.381.0,29.408.0,23.199.0,45.211.0,44.219.0,38.142.0,51.207.0,40.219.1"}
P.entries["quest:167"] = {n="Oh Brother. . .",s="\"Oh Brother. . .\" este o misiune Alliance oferita de Wilder Thistlenettle in Stormwind City. Tulburat de o prabusire survenita in timpul unei expeditii in adancurile de sub Moonbrook, Wilder le cere aventurierilor sa caute prin minele labirintice fratele sau disparut, Foreman Thistlenettle, sau sa-i recupereze insigna Explorers' League.",h="\"Oh Brother.",kw={"insigna","deadmines","explorers' league","moonbrook","stormwind","thistlenettle","undead","westfall","wilder"},ang={["faction:Alliance"]="Minele Deadmines sunt o napasta la portile Stormwindului, iar aceasta misiune arata cat de mult au afectat Defias si ororile subterane cetatenii nevinovati.",["race:Dwarf"]="Moartea tragica a unui maistru din Explorers' League pe meleagurile oamenilor ii afecteaza pe toti piticii care pretuiesc camaraderia, cioplirea pietrei si munca neobosita a breslei."},sec={{t="O expeditie prinsa in capcana",b="Wilder Thistlenettle si fratele sau au intrat in tunelurile subterane, ca niste pesteri, de sub Moonbrook, ca membri ai unei companii miniere. Insa totul a devenit dezastruos cand hoti ostili au napadit zona, iar o prabusire violenta a blocat tunelurile inferioare. Wilder a reusit sa scape la Stormwind, dar fratele sau si restul echipei au ramas prinsi in spatele daramaturilor."},{t="Soarta cruda a lui Foreman Thistlenettle",b="Adevarul care ii asteapta pe cei ce incearca sa salveze pe cineva patrunzand adanc in tunelurile din Deadmines este tragic. Foreman Thistlenettle nu a supravietuit surparii; energiile intunecate care frematau in minele abandonate l-au readus la viata pe nefericitul pitic, transformandu-l intr-un strigoi lipsit de suflet. Ratacind prin pesterile subterane alaturi de alte cadavre nelinistite, maistrul pastreaza doar pretioasa sa insigna Explorers' League, ca amintire a celui care a fost."}},faq={{q="Unde incep misiunea \"Oh Brother. . .\"?",a="Misiunea este oferita de Wilder Thistlenettle, care poate fi gasit in Dwarven District of Stormwind City.",al={"cel care da misiunea Oh Brother","cine ofera Oh Brother","unde poti obtine Oh Brother"}},{q="Unde se afla Foreman Thistlenettle?",a="Foreman Thistlenettle rataceste prin galeriile exterioare ale minei Deadmines, aflata sub orasul Moonbrook din Westfall. Se gaseste undeva in tunelurile exterioare care duc spre portalul instantei.",al={"locatia lui foreman thistlenettle","unde se afla thistlenettle","unde este fratele"}},{q="Ce i s-a intamplat lui Foreman Thistlenettle?",a="O surpare i-a prins pe Foreman Thistlenettle si grupul sau de mineri in pesteri, iar de atunci nu s-a mai auzit nimic despre ei. Sa-l gaseasca pe el sau macar insigna lui este singura cale prin care Wilder va afla soarta fratelui sau.",al={"mai traieste thistlenettle","ce s-a intamplat cu fratele","povestea lui thistlenettle"}},{q="Ce obiect trebuie sa recuperez?",a="Trebuie sa recuperezi insigna Explorers' League a maistrului Foreman Thistlenettle, pe care o purta mereu; gaseste-l pe maistru in adancul tunelurilor din Deadmines, iar insigna va fi la el.",al={"obiect de misiune Oh Brother","ce obiect cade pentru Oh Brother"}},{q="Ce facea expeditia in Moonbrook?",a="Fratii Thistlenettle faceau parte dintr-o companie miniera care lucra in vasta mina de sub Moonbrook, inainte de a fi atacati de banditi Defias si despartiti de surparea brusca a unui tunel.",al={"de ce erau dwarves in Westfall","Explorers' League Deadmines","de ce erau in Moonbrook"}},{q="Se incheie aceasta misiune in instanta temnitei Deadmines?",a="Nu, nu trebuie sa intri in instanta temnitei. Foreman Thistlenettle este o creatura de elita care cutreiera tunelurile minei disputate ce duc pana la portalul instantei.",al={"este Oh Brother in instanta Deadmines","am nevoie de un grup pentru temnita"}}},fx={["7bf03114"]={q="De ce vrea Wilder Thistlenettle ca acest lucru sa fie facut?",a="Wilder abia a scapat cu viata cand tunelurile s-au prabusit adanc sub Moonbrook. Fratele lui si restul expeditiei miniere nu au mai iesit la iveala, inghititi de intuneric si de hotii care infesteaza pasajele. Ramanand in chinuitoarea nesiguranta din Stormwind, Wilder cauta liniste sufleteasca. Trebuie sa afle daca fratele lui mai traieste sau daca a avut parte de un sfarsit sumbru in adancuri.",al={"de ce vrea wilder sa-i fie gasit fratele","motivul lui wilder thistlenettle","de ce trebuie gasit foreman thistlenettle"}},ebc7a172={q="Ce este Thistlenettle's Badge?",a="Foreman Thistlenettle purta o insigna a Explorers' League, care-i atesta statutul in breasla sapatorilor si aventurierilor din Ironforge. Daca nu gasesti niciun pitic in viata in adancuri, recuperarea acestui obiect personal dovedeste ce s-a intamplat cu el si ii ofera fratelui indurerat un raspuns definitiv.",al={"ce este insigna lui Thistlenettle","insigna Thistlenettle a Ligii Exploratorilor","de ce sa obtin insigna"}},["5e05fe78"]={q="De ce te roaga Wilder Thistlenettle pe tine, in loc sa mearga el insusi?",a="Wilder a scapat cu greu cu viata dupa ce s-a abatut dezastrul. Labirintul intins de sub Moonbrook e plin de talhari si capcane periculoase, cu mult peste ce poate infrunta singur un miner evadat. Vazand in tine un aventurier capabil, isi pune speranta in tine sa reusesti acolo unde el n-a putut decat sa fuga.",al={"de ce nu merge Wilder singur","de ce sa ma trimita in Deadmines","de ce are Wilder nevoie de ajutor"}}},fp="15,316,20.372.0,38.411.1,45.105.0,39.200.0,39.215.1,32.173.1,43.182.0,62.168.0"}
P.entries["quest:1678"] = {n="Vejrek"}
P.entries["quest:1679"] = {n="Muren Stormpike"}
P.entries["quest:168"] = {n="Collecting Memories",s="Collecting Memories este o sarcina solemna incredintata de minerul pitic Wilder Thistlenettle, din Stormwind City. El le cere aventurierilor care se incumeta sa intre in minele prabusite de sub Moonbrook sa recupereze Miners' Union Cards ale colegilor cazuti. Inapoierea acestor insemne le ofera familiilor indoliate din capitala un prilej de a-si inchide ranile dupa o surpare catastrofala.",h="Collecting Memories este o sarcina solemna incredintata de minerul pitic Wilder Thistlenettle, din Stormwind...",kw={"collecting memories","deadmines","legitimatie a minerilor","moonbrook","stormwind","mineri Undead","wilder thistlenettle"},ang={["faction:Alliance"]="Recuperarea insemnelor muncitorilor cazuti din Westfall sprijina in mod direct familiile indoliate din clasa muncitoare, care trec prin vremuri grele intre zidurile Stormwind.",["profession:Mining"]="Orice miner intelege teama persistenta provocata de surparea unei galerii, ceea ce da misiunii de recuperare a carnetelor de membru pierdute o rezonanta profunda si sumbra pentru cei care manevreaza tarnacopul.",["race:Dwarf"]="Piticii pretuiesc legaturile faurite in adancuri si sacralitatea fratilor cazuti, astfel incat rugamintea lui Wilder Thistlenettle capata o semnificatie personala pentru ceilalti pitici."},sec={{t="O prabusire tragica",b="Inainte ca Moonbrook sa cada cu totul in faradelegi si sub umbra Defias Brotherhood, minele din Westfall erau o sursa de trai activa pentru multe familii muncitoare. Wilder Thistlenettle a supravietuit unei surpari devastatoare care a ingropat o aripa a tunelurilor labirintice, dar multi dintre prietenii si colegii sai nu au avut acelasi noroc. Izolati si fara speranta de salvare, minerii au pierit in adancuri, lasand in urma rude indurerate in Stormwind, care nu au primit niciodata o confirmare adevarata sau raspunsuri despre soarta celor dragi."},{t="Ramasite nelinistite",b="Galeriile din afara principalelor uzine subterane de prelucrare a fierului nu mai sunt morminte tacute. Sufletele minerilor care au pierit in surpare ratacesc acum prin pasajele intunecate sub forma unor cadavre de strigoi nelinistite. Pentru a recupera Miners' Union Cards, calatorii trebuie sa strabata aceste galerii bantuite, infruntand ramasitele reanimate ale minerilor alaturi de care lucrase candva Wilder. Inapoierea acestor carduri la Stormwind le va permite in sfarsit rudelor lor sa afle adevarul si ii va oferi lui Wilder sansa de a-si onora tovarasii cazuti."}},faq={{q="Cine este Wilder Thistlenettle?",a="Wilder Thistlenettle este un miner pitic care locuieste in Stormwind City. A supravietuit prabusirii catastrofale a unui tunel de sub Westfall, in care si-au pierdut viata colegii sai apropiati, iar acum cauta sa le aduca liniste si certitudini familiilor ramase in viata.",al={"Wilder Thistlenettle","cel care da misiunea","cine ofera Collecting Memories"}},{q="Ce li s-a intamplat minerilor din Deadmines?",a="Prabusirea catastrofala a unui tunel a prins in capcana si a ucis o intreaga echipa de mineri intr-o aripa a sapaturilor din Moonbrook. Lipsiti de salvare si de o inmormantare cuvenita, spiritele si trupurile lor s-au ridicat ca morti-vii nelinistiti, bantuind pasajele parasite.",al={"de ce sunt mineri strigoi","surparea minei","surparea din Deadmines"}},{q="De ce vrea Wilder cardurile lor de tip Miners' Union Card?",a="Carnetele de sindicat servesc drept acte oficiale de identificare pentru muncitorii care au murit in prabusire. Cum trupurile nu au fost recuperate niciodata, gasirea carnetelor ii permite lui Wilder sa-si anunte oficial familiile din Stormwind si sa le ajute sa gaseasca alinare.",al={"la ce folosesc cartile sindicatului","cartile sindicatului minerilor"}},{q="Unde se gasesc legitimatiile sindicatului?",a="Cartile se gasesc in tunelurile bantuite de la periferie, de sub Moonbrook, pe coridoarele aflate chiar inainte de intrarea in zona securizata a Deadmines propriu-zise.",al={"unde gasesc cartile","locatia mortilor-vii din deadmines","unde sunt minerii morti"}},{q="A provocat Defias Brotherhood prabusirea pesterii?",a="Wilder Thistlenettle isi aminteste doar de un accident minier ingrozitor si de prabusirea unui tunel. Desi Defias Brotherhood stapaneste acum pasajele adanci din Deadmines, tragedia pare sa fi fost o catastrofa industriala care i-a prins in capcana pe minerii sai.",al={"au provocat Defias surparea","cine a prabusit mina"}},{q="Sunt minerii considerati parte din Defias Brotherhood?",a="Nu. Erau simpli muncitori sindicalizati care lucrau in mine cand s-a produs surparea. Ramasitele lor de strigoi, nelinistite, ratacesc la marginile pesterii, departe de fortele Defias organizate ale lui Edwin VanCleef, aflate mai in adanc.",al={"sunt minerii morti Defias","sunt minerii strigoi alaturi de Defias"}}},fx={e1328ead={q="Ce este Miners' Union Card?",a="Aceste legitimatii sindicale serveau drept acte oficiale de identitate pentru muncitorii care sapau in filoanele bogate ale minelor din Moonbrook inainte de catastrofa. Acum, ele sunt singura dovada durabila a celor care au pierit sub pamant cand s-au prabusit tunelurile. Recuperarea lor este singura cale de a confirma care anume muncitori si-au gasit sfarsitul in adancuri, ingaduindu-i lui Wilder Thistlenettle sa le dea vestea familiilor indurerate din Stormwind si sa le ofere un strop de alinare.",al={"legitimatia uniunii minerilor","ce sunt legitimatiile de sindicat","legitimatie de sindicat"}},["22601dce"]={q="De ce are Wilder Thistlenettle nevoie de un aventurier pentru aceasta sarcina?",a="Wilder Thistlenettle a supravietuit prabusirii cumplite, dar de atunci adancurile minelor din Moonbrook au cazut in haos primejdios. Zona din jurul vechii surpari este napadita de forte ostile si morti nelinistiti, cu mult peste puterile unui simplu civil sau fost miner. Cum nu au fost trimisi gardieni oficiali ai orasului in ruinele inselatoare din Westfall, Wilder se bazeaza pe aventurieri capabili, care oricum intentioneaza sa patrunda in mine, pentru a cauta printre daramaturi prietenii disparuti.",al={"de ce eu in collecting memories","de ce are wilder nevoie de ajutor","de ce sa trimita un aventurier"}}},fp="19,339,17.529.0,16.482.0,28.247.0,45.237.0,47.237.0,32.162.0,45.261.0,57.210.0"}
P.entries["quest:1680"] = {n="Tormus Deepforge",s="Tormus Deepforge este un armurier din Ironforge, insarcinat sa le furnizeze arme luptatorilor promitatori trimisi de Muren Stormpike. Inainte sa faureasca orice arma la comanda, Tormus ii cere aventurierului sa treaca printr-o proba primejdioasa pentru a-si dovedi puterea.",h="Tormus Deepforge este un armurier din Ironforge, insarcinat sa le furnizeze arme luptatorilor promitatori...",kw={"fierar Dwarf","forja cea mare","Ironforge","Muren Stormpike","Tormus Deepforge","misiune Warrior","fauritor de arme"},ang={["class:Warrior"]="Muren Stormpike ii indruma pe razboinicii in formare spre Tormus Deepforge din Ironforge, pentru a-si dovedi valoarea si a obtine o arma faurita la comanda, potrivita chemarii lor necrutatoare.",["faction:Alliance"]="Mesterii fierari din Ironforge pun adesea luptatorii promitatori ai Alliance la incercari primejdioase inainte de a le fauri arme si armuri de calitate."},sec={{t="Nicovala fierarului",b="Tormus Deepforge este un maestru armurier pitic stabilit in Ironforge. Cand razboinicii isi demonstreaza priceperea tot mai mare in fata lui Muren Stormpike, sunt trimisi de-a lungul orasului sa-l consulte pe Tormus. Renumit pentru armele sale trainice si puternice, Tormus nu imparte pur si simplu lame si buzdugane de calitate oricui se apropie de nicovala sa - razboinicii trebuie sa-si castige mestesugul prin fapte."},{t="O incercare primejdioasa",b="Inainte sa accepte sa bata metalul incins pentru un aventurier, Tormus ii cere acestuia sa-i promita o favoare. In stilul tipic piticesc, nu indulceste deloc adevarul despre primejdiile care-l asteapta si il avertizeaza ca treaba implica un pericol real de moarte. Pentru Tormus, o sarcina plina de primejdii si cu posibilitatea mortii nu este un motiv de descurajare, ci incercarea ideala a vitejiei unui razboinic."}},faq={{q="Cine este Tormus Deepforge?",a="Tormus Deepforge este un fierar de arme pitic desavarsit, aflat la Great Forge din Ironforge. El poate fauri arme exceptionale pentru razboinicii care dovedesc ca sunt destul de priceputi si curajosi pentru a se incumeta la misiuni primejdioase.",al={"cine este tormus","tormus deepforge din ironforge","cine este tormus deepforge"}},{q="Cine te trimite sa vorbesti cu Tormus Deepforge?",a="Muren Stormpike, veteranul instructor de razboinici din Ironforge, ii trimite pe luptatorii promitatori la Tormus Deepforge atunci cand sunt gata sa faureasca o arma pe masura priceperii lor martiale, aflate in crestere.",al={"cine m-a trimis la Tormus","de ce sa vorbesc cu Tormus","recomandarea lui Muren Stormpike"}},{q="Ce cere Tormus Deepforge in schimbul confectionarii unei arme?",a="Tormus accepta sa faureasca o arma de calitate, dar mai intai are nevoie de o favoare. Insista asupra unei sarcini primejdioase, care s-ar putea sa insemne moartea, sustinand ca tocmai un asemenea test il cauta un Warrior aspirant.",al={"favoarea lui Tormus","ce arma va fauri Tormus","ce vrea Tormus"}},{q="De ce subliniaza Tormus ca misiunea este periculoasa?",a="Sarcina pe care o are in vedere Tormus este deosebit de primejdioasa. In loc sa-i descurajeze pe luptatori, el considera ca sarcinile mortale sunt singurul test potrivit pentru cineva demn sa foloseasca lucrurile faurite de el.",al={"este Tormus Deepforge periculos","care este sarcina lui Tormus","misiunea de razboinic din Ironforge data de Tormus"}},{q="Unde poate fi gasit Tormus Deepforge?",a="Tormus Deepforge lucreaza langa Great Forge, in capitala dwarfilor, Ironforge, inconjurat de fierari, nicovale si furnale ce mugesc.",al={"unde este Tormus","locatia lui Tormus Deepforge"}},{q="Cu ce aventurieri lucreaza Tormus Deepforge?",a="Tormus se ocupa in mod special de razboinicii trimisi de instructorii lor, cautand persoane cu taria si hotararea martiala necesare pentru a indeplini sarcini ce le pun viata in pericol.",al={"ce clasa primeste misiunea lui tormus","misiunea lui tormus este doar pentru warrior"}}},fp="16,248,22.399.0,16.353.0,24.242.0,45.192.0,61.197.0,52.189.0,36.139.0,50.160.0"}
P.entries["quest:1683"] = {n="Vorlus Vilehoof"}
P.entries["quest:1685"] = {n="Gakin's Summons",s="O convocare trimisa Warlock-ilor promitatori din Alliance de Remen Marcot, in numele lui Gakin the Darkbinder. Aceasta ii indruma pe practicantii incepatori spre criptele de sub Slaughtered Lamb, in Mage Quarter din Stormwind, pentru a-si incepe urmatoarea etapa de pregatire in artele oculte intunecate.",h="O convocare trimisa Warlock-ilor promitatori din Alliance de Remen Marcot, in numele lui Gakin the Darkbinder.",kw={"demonologie","Gakin the Darkbinder","Mage Quarter","Remen Marcot","Slaughtered Lamb","Stormwind","voidwalker","warlock"},ang={["class:Warlock"]="Aceasta invocare marcheaza progresul tau dincolo de trucurile de salon si impii marunti, initiindu-te in incercarile necesare pentru a subjuga un hoinar al vidului care sa te apere in lupta.",["faction:Alliance"]="Chiar si in inima Stormwind, Alliance tolereaza o cabala subterana de tesatori ai umbrelor, a caror expertiza in magia vil ofera un avantaj intunecat impotriva dusmanilor."},sec={{t="Un mesaj confidential",b="Demonologia este strict interzisa in cartierele civilizate din Stormwind, dar artele intunecate dainuie chiar sub nasul garzii orasului. Cand un warlock da dovada de pricepere suficienta in stapanirea impilor de inceput, vestea ajunge pe furis la practicantii de rang inalt. Remen Marcot transmite mesajul cu o discretie calculata, indemnandu-i pe initiati sa pastreze tacerea despre locul intalnirii si sa se indrepte spre cotloanele intunecate de sub Mage Quarter."},{t="Criptele din Slaughtered Lamb",b="In spatele fatadei modeste a hanului Slaughtered Lamb se intinde o retea de pivnite umede si catacombe ascunse. Aici, ferit de privirile magilor Kirin Tor si ale inchizitorilor Catedralei, Gakin the Darkbinder supravegheaza instruirea warlockilor din Stormwind. Invocarea este poarta catre stapanirea unui voidwalker, un ritual care necesita reactivi furati, primejdiosi, si cercuri de invocare periculoase."}},faq={{q="De ce convoaca Gakin the Darkbinder warlocks?",a="Gakin ii cheama pe aspirantii Warlock odata ce ating un nivel potrivit de experienta. El considera ca Warlock-ii neinvatati sunt o povara, predispusi sa-si piarda capul, si isi propune sa-i instruiasca in ritualul complex de legare a unui voidwalker in slujba lor.",al={"scopul invocarilor lui gakin","la ce folosesc invocarile lui gakin","inceputul misiunii voidwalker"}},{q="Unde se afla Gakin the Darkbinder?",a="Gakin se ascunde in criptele adanci de subteran de sub Slaughtered Lamb, un han din Mage Quarter of Stormwind.",al={"unde este gakin","locatia lui gakin","subsolul Slaughtered Lamb"}},{q="Cine este Remen Marcot?",a="Remen Marcot este un asociat al covenului de warlock din Stormwind, care sta in pivnita de la Lion's Pride Inn din Goldshire si cauta candidati promitatori pentru a-i indruma pe ascuns spre enclava secreta a lui Gakin.",al={"remen marcot","cine incepe chemarea lui Gakin"}},{q="De ce trebuie pastrata locatia in secret?",a="Magia fel si invocarea demonilor sunt interzise in Kingdom of Stormwind. Daca ar fi descoperite de Silver Hand, Cathedral of Light sau de garzile orasului, ar urma intemnitarea sau executia.",al={"de ce secret","secretul warlock-ilor din stormwind"}},{q="Ce urmeaza dupa ce raspunzi chemarii lui Gakin?",a="Dupa ce ii da raportul lui Gakin, acesta ii cere warlock-ului sa mearga la Brackwell Pumpkin Patch, in Elwynn Forest, si sa recupereze de la Surena Caledon un pandantiv din piatra a sangelui, componenta esentiala a ritualului de legare a voidwalker-ului.",al={"urmatoarea misiune dupa invocarea lui gakin","ce se intampla in continuare"}},{q="Pot primi aceasta convocare cei care nu sunt Warlock?",a="Nu. Chemarea le este destinata strict warlockilor care si-au stapanit companionul imp de baza si au nevoie de instruire ezoterica avansata.",al={"pot face Mage asta","cine poate indeplini invocarile lui gakin"}}},fx={["0d517c2f"]={q="De ce vrea Remen Marcot sa-l vezi pe Gakin?",a="Remen Marcot actioneaza doar la ordinele lui Master Gakin the Darkbinder. Si-a petrecut toata ziua cutreierand orasul in cautarea ta si, intre timp, si-a pierdut rabdarea. Singurul sau interes este sa-si duca sarcina la indeplinire, ca sa nu mai fie nevoit sa te urmareasca si sa se poata ocupa de treburile lui. Te avertizeaza sa te prezinti repede, inainte ca stapanul tau sa-si piarda rabdarea.",al={"de ce te trimite Remen la Gakin","motivul lui Remen Marcot","de ce te cauta Remen"}}},fp="15,265,18.434.0,34.392.0,46.241.0,38.128.0,20.204.0,37.188.0,43.219.1,38.135.0"}
P.entries["quest:1686"] = {n="The Shade of Elura"}
P.entries["quest:1688"] = {n="Surena Caledon",s="Sub Slaughtered Lamb din Stormwind, Gakin isi cauta fostul elev si un colier de piatra-sangerie. Il trimite pe aspirantul warlock dupa Surena Caledon, care l-a tradat pentru a se alatura Defias Brotherhood.",h="Sub Slaughtered Lamb din Stormwind, Gakin isi cauta fostul elev si un colier de piatra-sangerie.",kw={"colier Bloodstone","Brackwell Pumpkin Patch","Defias","Erlan Drudgemoor","Gakin the Darkbinder","Slaughtered Lamb","Surena Caledon","Voidwalker"},ang={["class:Warlock"]="Ca warlock, treci printr-o proba in cautarea lui Surena Caledon. Gakin te invata ca tradarea are un pret mortal si ca sentimentalismul nu-si are locul in artele intunecate.",["race:Human"]="Ca om, vezi cum Defias Brotherhood continua sa-i ademeneasca pe cetatenii nemultumiti ai regatului Stormwind."},sec={{t="Un stapan amar",b="Sub Slaughtered Lamb, in Mage Quarter din Stormwind, Gakin the Darkbinder ii invata pe novici artele interzise ale invocarii magiei vil. A luat-o candva drept eleva pe o tanara pe nume Surena Caledon. Ii admira talentul magic innascut si frumusetea. Surena si-a parasit studiile si si-a pierdut bunavointa lui Gakin, apoi a fugit din Stormwind impreuna cu iubitul ei, Erlan Drudgemoor, ca sa se alature Defias Brotherhood."},{t="Piatra de sange furata",b="Gakin nu-si face griji pentru supravietuirea Surenei, dar vrea colierul bloodstone pe care i l-a dat in timpul uceniciei. Isi trimite cel mai nou ucenic spre sud-est, la Brackwell Pumpkin Patch din Elwynn Forest, o gospodarie napadita de banditi Defias. Ucenicul trebuie sa-i ia bijuteria Surenei prin orice mijloace necesare. Bloodstone-ul va servi drept catalizator magic pentru urmatoarea proba: invocarea si supunerea unui Voidwalker."}},faq={{q="Cine este Surena Caledon?",a="Surena Caledon a fost ucenica lui Gakin the Darkbinder in Stormwind. Avea talent innascut si i-a castigat bunavointa si darurile, inainte de a-si abandona studiile ca sa fuga cu Erlan Drudgemoor, un bandit Defias.",al={"povestea lui Surena","cine este Surena","trecutul lui Surena Caledon"}},{q="De ce vrea Gakin sa-si recupereze medalionul ei?",a="Gakin i-a daruit colierul Surenei in timpul uceniciei, iar acesta contine o piatra a sangelui pretioasa. Ii poarta pica pentru tradare si are nevoie de piatra ca reactiv ritualic, pentru a-si ajuta noul ucenic sa lege un Voidwalker.",al={"de ce sa iei colierul","importanta Bloodstone Choker"}},{q="Unde poate fi gasita Surena Caledon?",a="Surena poate fi gasita alaturi de tovarasii ei Defias la Brackwell Pumpkin Patch, o gospodarie abandonata din sud-estul Elwynn Forest.",al={"locatia lui surena","unde este surena","unde este lanul de dovleci"}},{q="Ce se intampla dupa recuperarea colierului?",a="Dupa ce duci colierul cu piatra sangelui inapoi la Gakin, incercarea se incheie. Urmatorul pas este sa intri in cercul de invocare din criptele de sub Slaughtered Lamb si sa legi un Voidwalker din Twisting Nether.",al={"ce urmeaza","urmatoarea misiune dupa surena"}},{q="Cine este Erlan Drudgemoor?",a="Erlan Drudgemoor este un Rogue din Defias Brotherhood. A sedus-o pe Surena Caledon si a convins-o sa-si abandoneze pregatirea de Warlock si sa fuga din Stormwind pentru a trai printre banditi.",al={"povestea lui Erlan","cine este Erlan Drudgemoor"}},{q="Simte Gakin vreo remuscare pentru soarta Surenei?",a="Gakin nu simte nicio remuscare pentru soarta Surenei. Spune ca viata ei nu inseamna nimic pentru el si ca e pacat sa-i iroseasca talentul magic, dar tradarea ei face necesara eliminarea ei.",al={"ii pasa lui Gakin","reactia lui Gakin fata de Surena"}}},fx={["8bc53c35"]={q="La ce foloseste Surena's Choker?",a="Colierul este o bijuterie vrajita din piatra sangelui, pe care Gakin the Darkbinder i-a daruit-o nechibzuit fostului sau ucenic. Pentru un vrajitor, piatra sangelui adaposteste o putere arcana si de invocare pura. Gakin are nevoie de puterea reziduala a artefactului pentru a pregati cercul ritualic de sub Slaughtered Lamb, care iti va permite sa invoci si sa legi un voidwalker dupa voia ta.",al={"scopul pentru surena's choker","de ce bloodstone choker","ce face colierul"}},["703ff238"]={q="De ce trimite Gakin un ucenic in loc sa se ocupe el insusi de Surena?",a="Warlocks din Stormwind actioneaza in mare taina, sub Slaughtered Lamb, fiind interzisi de legile regatului si vanati daca sunt descoperiti. Gakin nu poate cere garzii orasului sa recupereze o mostenire magica ilicita de la proscrisii Defias si nici nu-si poate parasi sanctuarul ca sa-si rezolve o umilinta personala. Trimitandu-te, iti pune la incercare cruzimea si dovedeste daca ai taria necesara pentru a stapani artele intunecate.",al={"de ce sa ma trimita dupa Surena","de ce nu poate Gakin sa ia colierul","de ce nu se duce Gakin singur"}}},fp="14,196,15.376.0,21.419.1,22.198.0,36.201.0,34.128.0,41.199.1,24.176.0,47.179.0"}
P.entries["quest:1689"] = {n="The Binding",s="In Stormwind, Gakin the Darkbinder supune un novice warlock unei probe finale. Cu Bloodstone Choker recuperat, atragi un voidwalker intr-un cerc ascuns si il fortezi sa se supuna.",h="In Stormwind, Gakin the Darkbinder supune un novice warlock unei probe finale.",kw={"legare","bloodstone choker","gakin the darkbinder","mage quarter","slaughtered lamb","stormwind","cerc de invocare","voidwalker"},ang={["class:Warlock"]="Ca warlock, primesti un voidwalker care sa te apere. Ritualul marcheaza trecerea ta de la invocator novice la comandant al fortelor din alte lumi.",["faction:Alliance"]="Ca membru al Alliance, slujesti o cauza care sustine Holy Light si ordinea arcana. In vremuri primejdioase, liderii pragmatici inchid ochii la practicantii artelor intunecate de sub Mage Quarter.",["race:Gnome"]="Ca Gnome warlock, aduci o minte precisa si iscoditoare la invocarea intunecata. Sub indrumarea lui Gakin, studiezi supunerea fiintelor din vid ca pe un experiment metafizic.",["race:Human"]="Ca human warlock, esti supravegheat indeaproape de clerul din Stormwind. Stapanesti fiinte periculoase din umbra si iti ascunzi puterea de orasul de deasupra."},sec={{t="Subjugarea din cripte",b="Sub Slaughtered Lamb, in Mage Quarter din Stormwind, catacombe uitate se intind dincolo de privirile vigilente ale magistratilor din Silver Hand si Kirin Tor. Gakin the Darkbinder ii invata pe warlocks incepatori ca magia intunecata cere mai mult decat canalizarea puterii; ei trebuie sa stapaneasca si fiinte de dincolo de aceasta lume. Ai recuperat Bloodstone Choker furat de la Gakin, de la Surena Caledon. Acum iti cere sa chemi un voidwalker in cercul de invocare de sub taverna."},{t="Impune-ti vointa asupra Vidului",b="Un voidwalker nu va negocia cu tine. Puterea din Bloodstone Choker deschide o ruptura si atrage creatura umbrei in lumea muritorilor. Trebuie sa-l lovesti cu magie si forta pana cand i se frange vointa, dovedind ca il poti stapani. Odata infrant, esenta voidwalker-ului se leaga de tine, oferindu-ti un protector rezistent si intunecat, capabil sa indure loviturile in bataliile ce vor urma."}},faq={{q="Unde se afla cercul de invocare?",a="Cercul de invocare se afla in adancul catacombelor de la subsol, sub The Slaughtered Lamb din cartierul Mage Quarter din Stormwind. Coboara pe scarile din apropierea lui Gakin the Darkbinder si strabate pasajele subterane pana la cea mai joasa incapere, unde o runa ritualica violet, stralucitoare, marcheaza podeaua de piatra.",al={"locatia cercului de invocare","unde invoc Voidwalker-ul","unde este cercul"}},{q="Cine este Gakin the Darkbinder?",a="Gakin the Darkbinder este un instructor warlock care lucreaza sub The Slaughtered Lamb din Stormwind. El ii invata in secret pe practicantii promitatori, oameni si gnomi, sa invoce si sa controleze fiinte demonice si atinse de Vid, departe de garzile orasului si de autoritatile bisericii.",al={"cine este gakin","povestea lui Gakin the Darkbinder","gakin"}},{q="La ce foloseste Bloodstone Choker?",a="Surena Caledon a furat Bloodstone Choker inainte sa-l recuperezi pentru Gakin. Magia concentrata il ajuta pe un novice warlock sa strapunga valul si sa atraga un voidwalker in cercul de invocare.",al={"la ce foloseste colierul Bloodstone","de ce am nevoie de colier","colier"}},{q="De ce trebuie sa se lupte Warlock-ii cu demonii lor pentru a-i lega?",a="Demonii si creaturile Vidului nu slujesc de bunavoie stapani muritori. Un Warlock trebuie sa supuna una in lupta prin forta si vointa inainte de a o lega sa-i slujeasca.",al={"de ce sa lupti cu nalucitorul vidului","de ce sa supui demonii","supunerea demonilor"}},{q="Ce se intampla dupa incheierea ritualului?",a="Dupa ce invingi creatura si ii inapoiezi colierul lui Gakin, dobandesti cunostintele si tehnica necesare pentru a invoca si controla un voidwalker loial, care sa te apere in calatorii.",al={"ce recompensa primesc","vraja voidwalker","dupa legare"}},{q="De ce se desfasoara acest ritual in secret, sub o taverna?",a="Demonologia si magia vidului sunt tabu, iar Church of the Holy Light si magi din Alliance le privesc cu ostilitate. Warlock din Stormwind practica in subsoluri si catacombe ascunse, departe de autoritati.",al={"de ce e ascuns sub han","este magia fel ilegala","subsolul din slaughtered lamb"}}},fx={bc8c924d={q="De ce vrea Gakin the Darkbinder sa legi un nalucitor al vidului?",a="Gakin vede in tine un potential imens dupa ce ai recuperat Bloodstone Choker, dar considera ca pregatirea ta magica este incompleta. Pentru a fi un adevarat warlock, nu este suficient sa canalizezi energii intunecate; trebuie sa ai vointa de a supune creaturi din Nether. Inainte sa te invete cum sa comanzi in lupta un voidwalker asa cum se cuvine, trebuie sa-ti dovedesti superioritatea fata de unul, prin propria putere.",al={"de ce vrea Gakin acest lucru","motivul lui Gakin","de ce sa legi un voidwalker"}},["8fb1392b"]={q="Ce este voidwalker-ul pe care il invoci?",a="Invoci o fiinta ostila din Twisting Nether in cercul de invocare de sub han. Voidwalkerii sunt fapturi intunecate si rezistente, manate de rautate haotica. Atrasa dincolo de prag de puterea amuletei Bloodstone Choker, aceasta creatura va ataca pe loc si va incerca sa-si distruga invocatorul, daca nu este silita sa se supuna prin lupta fizica si magica.",al={"ce este un voidwalker","cu cine te lupti","voidwalker invocat"}},b41bc1ad={q="De ce te pune Gakin sa invoci tu insuti voidwalker-ul?",a="Un demon nu poate fi legat indirect de un vrajitor. Daca Gakin sau un asistent ar imblanzi bestia, aceasta i-ar raspunde doar lui. Pentru a dobandi puterea si protectia unui strajer al vidului, trebuie sa-l atragi personal in cerc si sa-i infrangi vointa. Numai daca il invingi de unul singur poti fauri legatura mistica necesara pentru a-l invoca si a-l comanda pe viitor.",al={"de ce trebuie sa-l invoc eu","de ce nu o poate face Gakin","de ce eu, voidwalker"}}},fp="11,184,25.450.0,28.374.0,38.275.0,28.258.0,39.183.0,56.150.0,41.170.0,56.215.0"}
P.entries["quest:169"] = {n="Wanted: Gath'Ilzogg",s="Wanted: Gath'Ilzogg este o recompensa oferita de Alliance in Redridge Mountains, cu tinta asupra conducatorului de razboi din spatele invaziei Blackrock asupra Stonewatch. Magistrate Solomon ofera o rasplata generoasa oricui indrazneste sa atace fortareata cucerita si sa aduca inapoi capul retezat al comandantului.",h="Wanted: Gath'Ilzogg este o recompensa oferita de Alliance in Redridge Mountains, cu tinta asupra...",kw={"blackrock","bounty","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","afis de urmarire"},ang={["class:Warrior"]="Cucerirea culmii din Stonewatch Keep inseamna sa infrunti razboinicii veterani caliti si forta bruta a conducerii din prima linie a Dark Horde.",["faction:Alliance"]="Eliminarea lui Gath'Ilzogg inlatura una dintre cele mai imediate amenintari militare la adresa granitelor estice ale regatului, oferindu-le locuitorilor din Lakeshire un ragaz vital.",["race:Human"]="Pentru locuitorii din Stormwind, Stonewatch Keep a fost o fortificatie cucerita cu greu; masacrarea nevinovatilor de catre Gath'Ilzogg in timpul cuceririi sale face din aceasta recompensa o chestiune de razbunare amara."},sec={{t="Comandantul razboinic din Stonewatch",b="Gath'Ilzogg este comandantul brutal care conduce raidurile Blackrock clan prin Redridge Mountains. Sub conducerea lui, orcs au luat cu asalt si au cucerit Stonewatch Keep, transformand un fost bastion human intr-o baza fortificata pentru atacurile asupra asezarilor din jur. De pe cele mai inalte metereze ale fortaretei, el planuieste noi incursiuni in Lakeshire, amenintand sa taie legatura dintre Redridge si restul regatului."},{t="Un oras impins in pragul dezastrului",b="In timp ce armata regala din Stormwind nu reuseste sa trimita intariri in regiunile de granita, Magistrate Solomon a preluat situatia in propriile maini. Localitatea Lakeshire pur si simplu nu dispune de suficienti militari pentru a recuceri prin forta Stonewatch Keep. Prin publicarea unei recompense pentru Gath'Ilzogg, Solomon urmareste sa decapiteze conducerea Blackrock si sa declanseze prima etapa a recuceririi fortaretei in numele coroanei."}},faq={{q="Cine este Gath'Ilzogg?",a="Gath'Ilzogg este un conducator de razboi orc care comanda fortele Blackrock clan ce ocupa Stonewatch. A condus cucerirea fortaretei si raspunde de raidurile mortale, tot mai dese, impotriva colonistilor umani din Lakeshire.",al={"povestea lui Gath'Ilzogg","cine este Gath'Ilzogg","liderul Blackrock din Redridge"}},{q="Unde poate fi gasit Gath'Ilzogg?",a="Este instalat chiar in varful Stonewatch Keep, aflata in crestele estice ale Redridge Mountains. Este pazit indeaproape de campionii si garzile sale Blackrock.",al={"locatia lui Gath'Ilzogg","unde se afla Gath'Ilzogg","locatia sefului Stonewatch"}},{q="De ce ofera Magistrate Solomon o recompensa in loc sa trimita soldati?",a="Garda locala din Lakeshire este suprasolicitata, iar coroana din Stormwind nu a trimis trupele necesare pentru a intari regiunea. Magistrate Solomon trebuie sa se bazeze pe mercenari si aventurieri independenti pentru a face fata amenintarilor majore.",al={"de ce o recompensa","unde sunt soldatii din stormwind","ajutorul garzii din lakeshire"}},{q="Ce se intampla dupa ce este ucis Gath'Ilzogg?",a="Magistrate Solomon considera moartea conducatorului de razboi drept primul pas esential pentru a curata zona de invadatorii Orc si, in cele din urma, pentru a recuceri Stonewatch Keep in numele Kingdom of Stormwind, desi prezenta Blackrock in regiune ramane puternica.",al={"a fost recucerit Stonewatch","dupa gath'ilzogg"}},{q="De ce au invadat orcii Blackrock Stonewatch Keep?",a="Blackrock clan foloseste Stonewatch Keep drept baza fortificata inaintata. Asezata sus, in muntii de deasupra Redridge, aceasta le ofera control strategic asupra trecatorilor si un punct de plecare direct pentru raidurile impotriva asezarilor omenesti.",al={"de ce sunt Blackrock in Redridge","de ce a fost cucerit Stonewatch"}},{q="Cine revendica recompensa dupa ce Gath'Ilzogg moare?",a="Recompensa trebuie dusa direct la Magistrate Solomon, in primaria din Lakeshire, insotita de capul lui Gath'Ilzogg drept dovada definitiva a infrangerii sale.",al={"cui predau misiunea Gath'Ilzogg","predarea misiunii Gath'Ilzogg"}}},fx={["1d021e94"]={q="De ce vrea Lakeshire ca Gath'Ilzogg sa fie ucis?",a="Gath'Ilzogg este generalul care conduce invazia orcs Blackrock in Redridge. Sub comanda lui, orcs i-au macelarit pe aparatorii human, au cucerit Stonewatch Keep si au lansat raiduri violente direct asupra asezarii Lakeshire. Conducatorii orasului stiu ca, atata vreme cat el le coordoneaza fortele, Blackrock clan va continua sa unelteasca atrocitati impotriva cetatenilor nevinovati. Inlaturarea lui este esentiala pentru ruperea asediului si, in cele din urma, pentru recucerirea fortaretei.",al={"de ce sa-l omor pe gath'ilzogg","de ce exista recompensa pe gath'ilzogg","de ce vrea solomon ca gath'ilzogg sa moara"}},["69773e29"]={q="La ce foloseste Head of Gath'Ilzogg?",a="Capul ofera dovada de netagaduit ca razboinicul Blackrock a fost cu adevarat invins. Magistrate Solomon are nevoie de dovezi concrete ale mortii lui Gath'Ilzogg inainte de a putea plati recompensa orasului si de a-i linisti pe locuitorii ingroziti din Lakeshire, asigurandu-i ca faptasul din spatele atacurilor a fost infrant.",al={"capul lui gath'ilzogg rostul","de ce sa colectez capul lui gath'ilzogg","ce fac cu capul lui gath'ilzogg"}}},fp="19,281,25.414.0,26.396.0,19.208.0,31.173.0,72.237.0,41.240.0,50.228.0,47.154.0"}
P.entries["quest:1690"] = {n="Wastewander Justice",s="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company spune ca nomazii Wastewander detin acum aproape toate fantanile din desertul Tanaris. Esti trimis la est de Gadgetzan sa faci dreptate in randul Wastewander Bandits and Thieves.",h="Chief Engineer Bilgewhizzle of the Gadgetzan Water Company spune ca nomazii Wastewander detin acum aproape...",kw={"bandit","bilgewhizzle","gadgetzan","tanaris","hot","wastewander","water company","puturi"},sec={{t="Dreptate pentru Wells",b="In desertul din Tanaris, nomazii Wastewander detin acum aproape toate fantanile cu apa, iar rezervele din Gadgetzan se vor epuiza curand daca nu vor avea acces la ele. Chief Engineer Bilgewhizzle, care are gust pentru dreptatea in stil goblin, vrea sa dobori zece banditi si hoti Wastewander la est de oras, apoi sa-i raportezi numaidecat."},{t="Departe de a fi gata",b="Bilgewhizzle e multumit de rapiditatea muncii. Nomazii au fost suficient de mult imputinati incat compania sa poata incepe sa se gandeasca la recucerirea puturilor de apa, desi treaba cu nomazii spurcati e departe de a fi incheiata si mai are planuri."}},faq={{q="Cine este Chief Engineer Bilgewhizzle?",a="Un Inginer-sef al Companiei de Apa Gadgetzan, in Gadgetzan.",al={"bilgewhizzle","cine ofera Wastewander Justice","inginerul companiei de apa din Gadgetzan"}},{q="De ce urmareste Gadgetzan Water Company clanul Wastewanders?",a="Nomazii Wastewander detin aproape toate fantanile din desert, iar fara acces la ele, rezerva de apa a orasului Gadgetzan se va epuiza.",al={"de ce ucidem wastewander bandits","motivul pentru wastewander justice","de ce atacam nomazii din tanaris"}},{q="Unde se afla Wastewander Bandits si Thieves?",a="La est de Gadgetzan, in desert.",al={"unde gasesc banditii Wastewander","locatia banditilor Wastewander","locatia hotilor din Tanaris"}}},fp="19,230,21.320.0,13.223.1,35.62.0,64.131.0,54.44.0"}
P.entries["quest:1691"] = {n="More Wastewander Justice"}
P.entries["quest:1692"] = {n="Smith Mathiel"}
P.entries["quest:1693"] = {n="Weapons of Elunite"}
P.entries["quest:1698"] = {n="Yorus Barleybrew",s="La Lakeshire Inn, Yorus Barleybrew ii asteapta pe luptatorii din Alliance indrazneti, dispusi sa-i accepte provocarea. Instructorii din capitalele Alliance trimit luptatori cu experienta din Stormwind spre tinuturile de la granita cu Redridge, ca sa-l intalneasca pe dwarf excentric si sa-i treaca proba armelor.",h="La Lakeshire Inn, Yorus Barleybrew ii asteapta pe luptatorii din Alliance indrazneti, dispusi sa-i accepte...",kw={"kelv sternhammer","lakeshire","hanul din lakeshire","redridge","rethban","stormwind","warrior","wu shen","yorus barleybrew"},ang={["class:Warrior"]="Ca warrior din Alliance, treci un rit de initiere, de la exercitii de baza la incercari periculoase la granita din Redridge.",["faction:Alliance"]="Ca recrut Alliance, ai putea fi trimis la Lakeshire, o asezare vulnerabila napadita de Gnoll si Orc Blackrock."},sec={{t="Un apel catre cei puternici",b="In capitalele Alliance, instructorii de Warrior urmaresc luptatorii care si-au depasit primele exercitii. Cand un novice isi dovedeste valoarea in jurul varstei de douazeci de ani, instructori precum Kelv Sternhammer, Wu Shen si Darnath Bladesinger ii transmit vestea lui Yorus Barleybrew. Dwarf-ul nu ofera niciun ordin militar obisnuit. In schimb, a lansat un pariu deschis si o proba de arme pentru oricare warrior din Alliance care are indrazneala sa-i raspunda."},{t="Asteptand in Lakeshire",b="Yorus Barleybrew asteapta la hanul din Lakeshire, pe linia intai a luptei din Redridge impotriva gnollilor care inainteaza si a orcilor Blackrock. Cei care il gasesc intalnesc un Dwarf lauduros, cu o bautura zdravana in mana, gata sa judece pe oricine pretinde ca are cu adevarat spirit de luptator. Pentru cei care vor sa-si dovedeasca valoarea dincolo de strazile pavate si sigure ale capitalei, incercarea sa deschide drumul spre bataliile mai aspre ale tinutului de granita."}},faq={{q="Cine este Yorus Barleybrew?",a="Yorus Barleybrew este un dwarf din faimosul clan de berari Barleybrew, care a lansat o provocare martiala deschisa luptatorilor din Alliance. El asteapta la Lakeshire Inn, unde ii pune la incercare pe luptatorii care cred ca sunt pregatiti pentru frontiera brutala din Redridge Mountains.",al={"Yorus Barleybrew","cine este Barleybrew","pitic la hanul din Lakeshire"}},{q="De ce trimit instructorii razboinicii la Redridge?",a="Cand un warrior dobandeste destula pricepere in Stormwind, maestrii locali ai armelor il trimit spre lupte practice, cu mize mari. Proba lui Yorus Barleybrew ii duce pe elevi dincolo de zidurile orasului, unde isi dovedesc rezistenta in fata pericolelor reale ale tinuturilor salbatice.",al={"de ce Lakeshire","misiunea antrenorului de Warrior din Redridge","de ce sa mergi la Yorus"}},{q="Unde il gasesc pe Yorus Barleybrew?",a="Yorus Barleybrew te asteapta in Lakeshire Inn, in orasul Lakeshire din Redridge Mountains, chiar la est de Elwynn Forest.",al={"locatia lui Yorus Barleybrew","unde este Yorus","gaseste-l pe Barleybrew"}},{q="Ce se intampla dupa ce vorbesti cu Yorus?",a="Discutia cu Yorus da startul incercarii sale martiale: Rethban Gauntlet, o proba primejdioasa impotriva fiarelor feroce si a gnoll-ilor din dealurile din jur.",al={"dupa yorus","barleybrew proba","urmatoarea misiune"}},{q="Cine ofera misiunea de a-l gasi?",a="Instructorii de warrior din capitalele Alliance, printre care Kelv Sternhammer, Wu Shen si Darnath Bladesinger, ii trimit pe razboinici sa-l gaseasca pe Yorus dupa ce si-au dovedit priceperea de baza.",al={"cine ofera misiunea","cine incepe aceasta misiune","antrenorii pentru yorus"}},{q="Este aceasta incercare deschisa si claselor in afara de Warrior?",a="Nu. Yorus Barleybrew le propune aceasta incercare doar razboinicilor, luptatori care se bazeaza pe rezistenta fizica si arme.",al={"pot Paladins sa faca asta","este doar pentru Warriors","restrictii de clasa"}}},fx={f43b4090={q="De ce te trimit instructorii la Yorus Barleybrew?",a="Instructorii tai vad ca ai depasit exercitiile de baza si ai nevoie de incercari care sa-ti puna la incercare curajul pe teren. Yorus Barleybrew a lansat o provocare deschisa, adresata in mod special razboinicilor capabili ai Alliance, promitand o recompensa mareata oricui este destul de puternic sa o infrunte. In loc sa te tina la adapost in salile de antrenament ale capitalei, mentorii te trimit in Redridge sa-ti dovedesti maiestria intr-o incercare adevarata.",al={"de ce sa ma trimiti la Yorus","de ce eu, Yorus Barleybrew","de ce proba Warrior din Redridge"}}},fp="16,259,20.418.0,20.414.0,24.257.0,46.254.0,34.128.0,39.147.0,33.172.0,50.120.0"}
P.entries["quest:1699"] = {n="The Rethban Gauntlet",s="Rethban Gauntlet este o proba de rezistenta neobisnuita, conceputa de berarul pitic Yorus Barleybrew din Lakeshire. Concurentii trebuie sa dea pe gat o dusca zdravana din Barleybrew Scalder, berea iute a familiei sale, apoi sa alerge spre nord, pana la Rethban Caverns, pline de gnolli, si inapoi, inainte sa treaca o ora.",h="Rethban Gauntlet este o proba de rezistenta neobisnuita, conceputa de berarul pitic Yorus Barleybrew din...",kw={"Barleybrew Scalder","gnolli","Lakeshire","Redridge","Rethban Caverns","Rethban Gauntlet","cursa contra cronometru","Yorus Barleybrew"},ang={["faction:Alliance"]="In timp ce Lakeshire se lupta cu amenintarea incursiunilor gnoll, infruntarea acestui drum primejdios ajuta la imputinarea patrulelor inamice care pandesc langa pesterile nordice.",["race:Dwarf"]="Piticiilor le va placea nespus ideea zgomotoasa de distractie a lui Yorus: sa amestece bautura tare a familiei cu sprinturi periculoase pe munte."},sec={{t="O provocare pitica",b="In orasul Lakeshire, unde discutiile sumbre despre raidurile gnollilor si disparitia garzilor orasului domina de obicei atmosfera hanului, piticul Yorus Barleybrew aduce o forma de divertisment cu totul specifica piticilor. Provocarea botezata de el insusi, Rethban Gauntlet, pune la incercare deopotriva curajul, viteza si ficatul unui aventurier. Participantii trebuie sa dea pe gat o inghititura din bautura specifica familiei sale, Barleybrew Scalder, chiar inainte de a porni pe jos spre poalele nordice."},{t="Goana prin dealurile salbatice",b="Incercarea este mult mai primejdioasa decat o simpla cursa de alergare in stare de ebrietate. Intre Lakeshire si destinatie se intinde tinutul Redridge, plin de gnoli agresivi din Redridge. Pentru a incheia cu succes cursa cu obstacole, participantul trebuie sa lupte cu haitele sau sa se strecoare pe langa ele, sa ajunga la prima bifurcatie din tunelurile intunecate ale Rethban Caverns si sa se grabeasca inapoi la Yorus intr-o ora - totul in timp ce se lupta cu efectele coplesitoare si ametitoare ale bauturii piticesti tari."}},faq={{q="Cine emite Rethban Gauntlet?",a="Yorus Barleybrew, un berar pitic gazduit in Lakeshire, ii provoaca pe calatori la o cursa pentru a-si dovedi rezistenta si a-i testa berea.",al={"cine ofera Rethban Gauntlet","misiunea lui Yorus Barleybrew","cine incepe incercarea"}},{q="Ce face ca aceasta provocare sa fie deosebit de dificila?",a="Pe langa faptul ca trebuie sa evite haitele de gnoll-i care strabat poalele muntilor din Redridge in limita stricta de o ora, alergatorii trebuie mai intai sa inghita Barleybrew Scalder, o bautura foarte tare care ii imbata zdravan si le ingreuneaza pastrarea echilibrului.",al={"de ce este grea Rethban Gauntlet","efectul lui Barleybrew Scalder"}},{q="Unde se afla Rethban Caverns?",a="Pesterile se afla la poalele nordice ale Redridge Mountains, la nord-vest de Lakeshire. Drumul duce spre nord, trecand pe langa gospodariile locale si continuand catre stancile locuite de haite de gnolli.",al={"locatia Rethban Caverns","unde se afla Rethban","cum sa ajungi la Rethban Caverns"}},{q="Cat de adanc in pesteri trebuie sa ajunga un alergator?",a="Cei care accepta provocarea nu trebuie sa strabata intreaga caverna; trebuie doar sa ajunga la prima bifurcatie din interior, apoi sa se intoarca si sa goneasca inapoi spre Lakeshire.",al={"obiectivul din Rethban Caverns","cat de departe in interiorul rethban"}},{q="Cine locuieste pe dealurile si in pesterile de-a lungul drumului?",a="Zona din jurul drumului si din interiorul pesterilor este napadita de gnolli Redridge ostili, asa ca furisarea sau lupta rapida sunt esentiale pentru a supravietui calatoriei.",al={"ce dusmani sunt in Rethban","ce se afla in Rethban Caverns"}},{q="Unde duce mai departe aceasta provocare?",a="Daca supravietuiesti probei, ii dovedesti rezistenta ta lui Yorus Barleybrew si poti trece la alte misiuni din regiune, precum gasirea mesterului de scuturi Furen Longbeard in Stormwind.",al={"continuarea dupa rethban gauntlet","ce misiune urmeaza dupa rethban gauntlet"}}},fx={["26a182c4"]={q="De ce vrea Yorus Barleybrew ca acest lucru sa fie facut?",a="Yorus Barleybrew nu incearca sa rezolve o criza sau sa salveze Lakeshire prin aceasta incercare. In schimb, pune la cale Rethban Gauntlet ca o proba zgomotoasa de curaj, rezistenta si toleranta la alcool. Trimitandu-i pe aventurieri indrazneti adanc in tinutul gnolilor, in timp ce sunt bine ametiti de Barleybrew Scalder, bautura iute a familiei sale, Yorus cauta doar sa se distreze si sa vada pe cineva destul de curajos incat sa infrunte atat gnolii salbatici din Redridge, cat si efectul naucitor al bauturii sale.",al={"de ce sa treci prin incercare","motivul lui Yorus Barleybrew","de ce te provoaca Yorus"}}},fp="20,281,14.462.0,22.443.0,32.132.0,49.252.0,38.174.0,40.151.0,51.157.0,36.178.0"}
P.entries["quest:1700"] = {n="Grimand Elmore",s="Dupa crearea armurii specializate, fierarul pitic Furen Longbeard trimite un exemplar al descoperirilor sale peste district, la Grimand Elmore. Scurta insarcinare poarta insemnari tehnice intre doi fauritori de arme incapatanati, care lucreaza in Stormwind City.",h="Dupa crearea armurii specializate, fierarul pitic Furen Longbeard trimite un exemplar al descoperirilor sale...",kw={"fierarie","districtul piticilor","Fire Hardened Mail","Furen Longbeard","insemnarile lui Furen","Grimand Elmore","Stormwind"},ang={["class:Warrior"]="Aceasta livrare face legatura dintre echiparea ta cu armura si cautarea armelor de lupta faurite prin aceleasi experimente elementale.",["profession:Blacksmithing"]="Schimbul dintre Furen si Grimand ilustreaza rivalitatea profesionala intensa si impartasirea secretelor meseriei, specifice maestrilor prelucratori de metale.",["race:Dwarf"]="Schimbul de replici impulsiv si plin de mandrie dintre Grimand si Furen reflecta traditiile profund competitive, dar si cooperante, ale culturii fierarilor din Khaz Modan."},sec={{t="Un mesaj de-a lungul districtului",b="Dupa ce a faurit armura Fire Hardened Mail, Furen Longbeard consemneaza tehnicile complicate de tratare termica si principiile elementale pe care le-a descoperit in timpul procesului. In loc sa pastreze cunoasterea doar pentru sine, isi asterne notitele pe pergament si ii incredinteaza unui aventurier sarcina de a le duce direct la Grimand Elmore, un mester cu experienta care lucreaza intr-un atelier de arme din apropiere."},{t="Mandrie profesionala si curiozitate",b="Reactia imediata a lui Grimand Elmore la primirea manuscrisului este o mandrie ranita. Convins ca l-a invatat pe Furen tot ce stie dwarf-ul mai tanar, Grimand se infurie la gandul ca fostul sau elev ar putea sa-i dea lectii. In ciuda indignarii vadite, mestesugarul nu se poate abtine sa rasfoiasca textul si descopera repede printre notite o idee interesanta, pe care abia asteapta s-o puna la incercare."}},faq={{q="Cine este Grimand Elmore?",a="Grimand Elmore este un faurar de arme respectat, care are un atelier in Stormwind City's Dwarven District. Este cunoscut pentru mandria sa profesionala nemarginita si pentru ca, in trecut, i-a invatat mestesugul pe alti fierari locali, printre care si Furen Longbeard.",al={"grimand elmore","cine este grimand","elmore stormwind"}},{q="De ce ii trimite Furen mesaje lui Grimand?",a="In timp ce confectiona Fire Hardened Mail, Furen a descoperit tehnici noi si si-a consemnat metodele. A vrut sa-i impartaseasca descoperirile lui Grimand, desi stia ca temperamentul vulcanic si orgoliul incapatanat al acestuia l-ar face sa reactioneze defensiv cand ar fi invatat ceva nou.",al={"de ce sa trimiti notitele","notitele lui furen","furen catre grimand"}},{q="Unde poate fi gasit Grimand Elmore?",a="Poate fi gasit lucrand in magazinul de arme din Dwarven District of Stormwind City, la doar cateva minute de mers pe jos de forja lui Furen Longbeard.",al={"unde se afla Grimand","locatia lui Grimand","magazinul lui Grimand Elmore"}},{q="Cum reactioneaza Grimand la notite?",a="La inceput, Grimand este furios si declara ca l-a invatat pe Furen tot ce stie piticul. Totusi, curiozitatea unui maestru fierar pune repede stapanire pe el cand zareste in text o tehnica interesanta pe care vrea s-o incerce.",al={"reactia lui grimand","este grimand furios"}},{q="Ce se intampla dupa ce Grimand citeste notitele?",a="Intrigat de munca lui Furen la calirea metalului cu foc, Grimand hotaraste sa-si urmeze propriul proiect mestesugaresc ambitios, ceea ce il conduce spre alte sarcini de strangere a unor componente rare cu caldura elementala.",al={"ce urmeaza, grimand","dupa misiunea lui grimand elmore"}},{q="De ce te avertizeaza Furen sa te feresti cand ii dai notitele?",a="Furen cunoaste din proprie experienta temperamentul aprins si mandria exagerata a lui Grimand. Isi inchipuie ca Grimand ar putea face o criza de furie - sau ar putea arunca un obiect - numai la gandul ca un ucenic l-ar putea invata pe maestru o tehnica noua.",al={"de ce sa te feresti","avertismentul lui Furen despre rata"}}},fx={["7d98159c"]={q="De ce te trimite Furen in loc sa mearga el insusi la Grimand?",a="Furen cunoaste prea bine firea artagoasa a lui Grimand Elmore. Grimand sustine ca l-a invatat pe Furen tot ce stie, iar daca fostul sau elev ar intra in atelier ca sa-i tina o lectie despre tehnici noi de fierarie, s-ar isca o cearta aprinsa. Punandu-te sa-i duci notitele in locul lui, Furen evita o confruntare directa si il lasa pe indaratnicul sau mentor sa-si inghita mandria in intimitate.",al={"de ce ma trimit la Grimand Elmore","de ce nu duce el insusi notitele, Furen","de ce are nevoie Furen de mine"}}},fp="14,256,29.392.0,32.407.0,22.240.0,37.270.0,34.149.0,36.233.0,43.187.1,56.215.0"}
P.entries["quest:1701"] = {n="Fire Hardened Mail",s="In Stormwind, Furen Longbeard are un nou model de armura pentru un razboinic Alliance. Armurierul Dwarf se ofera sa faureasca Fire Hardened Mail daca razboinicul ii aduce materiale rare de pe ambele continente.",h="In Stormwind, Furen Longbeard are un nou model de armura pentru un razboinic Alliance.",kw={"corn ars","fire hardened mail","furen longbeard","corn galvanizat","flogiston","razorfen kraul","roogug","colt de paianjen parjolit","stonetalon","wetlands"},ang={["class:Warrior"]="Ca Warrior, iti dovedesti vitejia infruntand salbaticia din Kalimdor si temnitele adanci, pentru a castiga o piesa de armura exceptionala.",["faction:Alliance"]="Ca soldat Alliance, te aventurezi adanc in Barrens si Stonetalon Mountains, unde Horde isi disputa teritoriul.",["race:Dwarf"]="Ca Dwarf, stii ca o armura trainica necesita materiale neclintite, luate direct de la cei mai feroce pradatori ai naturii."},sec={{t="Ambitia unui armurier maestru",b="Furen Longbeard a faurit un scut mic exceptional pentru aspirantul la clasa Warrior si propune acum o lucrare si mai mare: o armura din zale capabila sa reziste unor lovituri violente. Mestesugul lui cere mai mult decat fier sau otel. Are nevoie de materiale rare, atinse de caldura elementala si inzestrate cu rezistenta naturala. Furen nu-si poate parasi atelierul din Stormwind, asa ca Warrior-ul care doreste armura trebuie sa adune aceste ingrediente periculoase."},{t="O expeditie intercontinentala",b="Furen il trimite pe warrior in tinuturi salbatice indepartate si in adancuri periculoase pentru piesele de care are nevoie. Reteta cere colti de la paianjeni veninosi din crapaturile umede ale Wetlands, precum si coarne arse si galvanizate de la chimaere feroce din Stonetalon Mountains. Pentru a lega si cali aceste parti de bestie in zale, Furen are nevoie si de flogiston volatil de la Roogug, un geomant din adancul labirintului spinos din Razorfen Kraul, in Barrens."}},faq={{q="Cine este Furen Longbeard?",a="Furen Longbeard este un armurier si fabricant de scuturi pitic cu experienta, din Stormwind City's Dwarven District. El confectioneaza echipamente de aparare personalizate pentru razboinicii promitatori dispusi sa-l ajute.",al={"Furen","cine ofera Fire Hardened Mail","cine este fierarul"}},{q="De ce are Furen nevoie de ingrediente atat de neobisnuite?",a="Furen are nevoie de ingrediente neobisnuite pentru a cali metalul dincolo de metodele obisnuite ale dwarven. Mestesugul sau secret foloseste materiale organice tratate cu venin natural, vanturi de munte si suflari de arma, alaturi de flogiston volatil.",al={"de ce colti de paianjen","de ce coarne","ce este flogistonul"}},{q="De unde provin coarnele de himera?",a="Coarnele parlite si galvanizate provin de la himerele din Stonetalon Mountains din Kalimdor. Atat fiarele tinere, cat si formidabila Chimaera Matriarch care le conduce poarta aceste coarne.",al={"unde gasesti coarne de chimaera","locatia cornului ars","corn galvanizat"}},{q="Unde se poate gasi flogistonul?",a="Roogug, un geomant quilboar, poarta un flacon de flogiston in barlogul sau din Razorfen Kraul, aproape de extremitatea sudica a tinutului Barrens, in Kalimdor.",al={"fiola de flogiston","cine lasa flogiston","roogug"}},{q="Ce paianjeni poarta colti de paianjen arsi?",a="Leech Stalker si Cave Stalker poarta coltii de paianjen parliti. Aceste arahnide uriase pandesc in mlastinile si pesterile din Wetlands, in Eastern Kingdoms.",al={"colti de paianjen arsi","unde sunt paianjenii","paianjeni din wetlands"}},{q="Ce se intampla dupa ce sunt adunate toate materialele?",a="Odata ce Furen primeste coltii, coarnele si flogistonul, incepe sa faureasca o platosa la comanda pentru Warrior. O lucreaza in forja sa, ca parte din Furen's Armor.",al={"ce urmeaza","continuarea dupa Fire Hardened Mail","recompensa"}}},fx={cecd81db={q="De ce vrea Furen Longbeard ca acest lucru sa fie facut?",a="Furen este foarte mandru de iscusinta sa in fierarie. Dupa ce ti-a faurit deja scutul, vrea sa-si dovedeasca maiestria faurind o armura de zale de o rezistenta exceptionala. Cunoaste tehnicile secrete necesare prelucrarii acestor reactivi exotici, caliti in foc, si se ofera sa-ti faureasca armura doar pentru a vedea cum prinde viata o piesa atat de extraordinara - cu conditia sa infrunti primejdiile adunarii componentelor.",al={"motivul lui Furen Longbeard","de ce sa fac Fire Hardened Mail","de ce vrea Furen materiale"}}},fp="18,193,27.377.0,30.431.0,23.168.0,48.225.0,38.178.0,30.139.0,42.154.0,50.160.0"}
P.entries["quest:1702"] = {n="The Shieldsmith",s="In Stormwind, Yorus Barleybrew ii trimite inapoi pe razboinicii care au trecut printr-o incercare cumplita in Redridge Mountains. Le da un butoi de Barleybrew Scalder sa-l duca lui Furen Longbeard, care va fauri un scut rezistent.",h="In Stormwind, Yorus Barleybrew ii trimite inapoi pe razboinicii care au trecut printr-o incercare cumplita in...",kw={"Barleybrew Scalder","butoi","cartierul piticilor","Furen Longbeard","Rethban","fierar de scuturi","Stormwind","Warrior","Yorus Barleybrew"},ang={["class:Warrior"]="Ca Warrior, duci indarjirea din Redridge la Stormwind si iti dovedesti dreptul de a purta un scut faurit de un armurier dwarven legendar.",["profession:Blacksmithing"]="Ca fierar, il intalnesti pe Furen Longbeard, a carui munca specializata la armurile defensive este apreciata in toata Alliance.",["race:Dwarf"]="Ca Dwarf, stii ca schimbul unui butoi de bere Barleybrew de calitate pe fier forjat in Dwarven District din Stormwind este o afacere obisnuita."},sec={{t="O promisiune respectata",b="Dupa ce-ti dovedesti vitejia impotriva gnoll-ilor si in primejdiile din Rethban Gauntlet, Yorus Barleybrew isi respecta intelegerea. Recompensa promisa nu poate fi faurita in Lakeshire, asa ca ii indruma pe luptatorii promitatori inapoi la Stormwind City. Acolo, un armurier dwarven este gata sa-si achite o datorie personala."},{t="Cele mai bune ale lui Barleybrew",b="In locul unei scrisori de credit, Yorus iti da un butoi greu de Barleybrew Scalder. Du-l la Furen Longbeard, in Dwarven District din Stormwind, unde aerul e plin de funingine si de zanganitul ciocanelor. Fierarul incercat recunoaste numele din spatele livrarii si isi pune mestesugul in slujba unui warrior care cauta un scut trainic."}},faq={{q="Cine este Furen Longbeard?",a="Furen Longbeard este un maestru armurier si fauritor de scuturi de neam Dwarf, stationat in Stormwind City's Dwarven District. Razboinicii Alliance ii cunosc priceperea, iar el faureste echipamente defensive specializate pentru veteranii razboiului care ii castiga respectul.",al={"Furen Longbeard","cine este Furen","cine este fauritorul de scuturi"}},{q="De ce te trimite Yorus la Stormwind?",a="Yorus Barleybrew te trimite la Stormwind, deoarece a promis un scut martial, dar nu are cunostintele specializate de fierarie necesare pentru a-l fauri singur. Prietenul sau, Furen Longbeard, ii este dator cu o favoare importanta.",al={"de ce sa mergi la Stormwind","de ce Stormwind","locatia recompensei lui Yorus"}},{q="Ce este Barleybrew Scalder?",a="Barleybrew Scalder este o bautura pitica extrem de puternica, produsa de familia Barleybrew. Yorus ii trimite lui Furen Longbeard un butoi proaspat, ca sa-i potoleasca setea fierarului si sa inlesneasca intelegerea dintre ei.",al={"Cask of Scalder","Barleybrew Scalder","ce este scalderul"}},{q="Unde poate fi gasit Furen Longbeard?",a="Furen Longbeard isi ingrijeste forja in inima Stormwind City's Dwarven District, printre funingine, nicovale si atelierele mesterilor pitici.",al={"locatia lui Furen","unde se afla Furen Longbeard","gaseste-l pe Furen"}},{q="Ce se intampla dupa ce ii dai butoiul lui Furen?",a="Butoiul confirma ca Yorus te-a trimis. Furen isi recunoaste datoria si se ofera pe loc sa faureasca armura defensiva potrivita pentru lupte grele, deschizand drumul catre echipamentul calit in foc.",al={"ce urmeaza","misiunea de continuare a lui Furen"}},{q="De ce este importanta aceasta insarcinare pentru razboinicii din Alliance?",a="Aceasta livrare ii face cunostinta unui warrior din Alliance cu unul dintre cei mai capabili armurieri ai regatului. Deschide calea catre echipament militar facut pe masura si catre mai multa instruire in razboiul defensiv.",al={"importanta misiunii Warrior","de ce le pasa razboinicilor"}}},fx={["23250e3d"]={q="De ce te trimite Yorus Barleybrew cu aceasta livrare in loc sa foloseasca un curier?",a="Yorus se tine de cuvant dupa ce ai trecut prin Rethban Gauntlet. In loc sa te trimita intr-o livrare obisnuita, te pune sa-ti ridici personal recompensa promisa. Scutul promis se afla la prietenul sau, Furen Longbeard, in Stormwind, iar butoiul de Scalder, bautura sa vestita, pe care te pune sa-l duci, ii permite sa-si respecte promisiunea si sa-si ceara direct o favoare veche in numele tau.",al={"de ce ma trimite shieldsmith","de ce ma trimite yorus","de ce eu, yorus barleybrew"}}},fp="15,205,14.296.0,19.301.0,23.225.0,37.197.0,27.206.0,35.141.0,41.187.0,51.179.0"}
P.entries["quest:1703"] = {n="Mathiel"}
P.entries["quest:1705"] = {n="Burning Blood",s="In Stormwind, Grimand Elmore recurge la metodele de faurire ale lui Furen Longbeard. Are nevoie de sange arzator si de o roca incandescenta din Duskwood pentru a testa singur tehnica de confectionare a armurii.",h="In Stormwind, Grimand Elmore recurge la metodele de faurire ale lui Furen Longbeard.",kw={"sange arzand","stanca arzanda","Duskwood","Furen Longbeard","Grimand Elmore","Gutspill","worgen Nightbane","Roland's Doom"},ang={["class:Warrior"]="Ca Warrior, poti infrunta bestiile blestemate din Duskwood pentru experimentul lui Grimand si poti castiga o armura calita in mod unic, creata pentru linia frontului.",["faction:Alliance"]="Ca membru al Alliance, poti recupera reactivi din Roland's Doom, ajutand la limitarea amenintarii worgen din Duskwood si la aprovizionarea arsenalelor din Stormwind cu metode defensive noi.",["profession:Blacksmithing"]="Ca fierar, il poti vedea pe Grimand testand metodele fostului sau elev, Furen, folosind metale rare si agenti de calire."},sec={{t="Un experiment facut fara tragere de inima",b="Grimand Elmore este unul dintre armurierii de seama ai Alliance si rareori accepta ca vreun alt fierar i-ar putea intrece maiestria. Auzind despre descoperirile neobisnuite ale lui Furen Longbeard in arta fierariei, i se starneste curiozitatea profesionala. Grimand accepta sa-i testeze metodele lui Furen faurind o piesa de armura. Are nevoie de componente stranii si volatile din tinuturile intunecate ale sudului pentru a raci si cali metalul exact dupa cerintele sale; apa obisnuita si carbunii comuni nu sunt de ajuns."},{t="Ororile din Roland's Doom",b="Grimand te trimite in Duskwood, la mina abandonata numita Roland's Doom. Worgen Nightbane salbatici au napadit tunelurile, iar venele lor blestemate pulseaza de ichor arzator. Are nevoie de fiole cu sangele lor arzator si de un nucleu rar, incandescent, numit burning rock, purtat de capetenia haitei, Gutspill. Adu aceste materiale dogoritoare inapoi, ca Grimand sa poata testa metodele lui Furen la forja."}},faq={{q="Cine este Grimand Elmore?",a="Grimand Elmore este un maestru armurier respectat din Dwarven District, in Stormwind. El lucreaza cu alti mestesugari pentru a-i echipa pe aparatorii orasului si ii invata pe aspirantii warrior cat cantaresc si cat de rezistente sunt armurile de lupta potrivite.",al={"grimand","grimand elmore","armurier din stormwind"}},{q="De ce vrea Grimand sange arzator si o piatra arzatoare?",a="Grimand vrea sa testeze o tehnica de faurire a armurii dezvoltata de Furen Longbeard. Sangele arzator si roca incinsa ofera caldura supranaturala necesara pentru a fauri si a cali placi de armura specializate.",al={"de ce sange arzator","la ce foloseste piatra arzatoare","scopul misiunii"}},{q="Unde gasesc worgenii Nightbane care poarta aceste materiale?",a="Poti gasi materialele in Duskwood, la Roland’s Doom, o mina abandonata din sud-estul tinutului, la sud-vest de Darkshire. Worgen Nightbane misuna prin tuneluri si poarta sangele arzator.",al={"unde sunt worgen","locatia lui roland's doom","unde se afla burning blood"}},{q="Cine tine piatra arzanda?",a="Gutspill, un lider puternic printre worgenii Nightbane, poarta roca incinsa in adancurile din Roland’s Doom.",al={"cine are burning rock","gutspill","locatia lui gutspill"}},{q="Care este relatia dintre Grimand Elmore si Furen Longbeard?",a="Furen Longbeard este fostul elev al lui Grimand Elmore. Grimand este de obicei sceptic fata de ideile din afara, dar cele mai recente metode ale lui Furen de confectionare a armurilor l-au convins sa le testeze personal.",al={"grimand si furen","cine este furen longbeard"}},{q="Ce se intampla dupa ce aduci inapoi sangele si piatra?",a="Grimand incepe sa faureasca armura dupa ce primeste reactivii de foc, pentru a testa metodele lui Furen. Ii promite piesa terminata aventurierului care a adunat materialele.",al={"urmatoarea misiune","recompensa","ce confectioneaza grimand"}}},fx={["50895b50"]={q="La ce foloseste Burning Blood?",a="Grimand Elmore are nevoie de sangele arzator pentru a testa o tehnica exotica de faurire, initiata de fostul sau elev, Furen Longbeard. Folosindu-se de caldura nefireasca si arzatoare care strabate venele worgenilor din Duskwood, Grimand intentioneaza sa caleasca o armura speciala, pentru a vedea daca metalurgia lui Furen are intr-adevar valoare.",al={"obiectul de misiune Burning Blood","la ce foloseste Burning Blood","de ce Burning Blood"}},["8a0ab7ce"]={q="La ce foloseste Burning Rock?",a="Grimand are nevoie de roca arzatoare ca ingredient esential pentru a testa metodele lui Furen Longbeard de confectionare a armurilor. Extrasa de la Gutspill, conducatorul haitei de worgen din adancul Roland's Doom, piatra dogoritoare ofera caldura elementala bruta si proprietatile arcane necesare pentru a fauri coiful intarit in foc.",al={"folosirea pietrei arzande","de ce piatra arzanda","ce face Grimand cu piatra arzanda"}},["0438723a"]={q="Cine sunt worgenii Nightbane din Duskwood?",a="Nightbane sunt umanoizi salbatici, asemanatori lupilor, care bantuie padurile intunecate din Duskwood. Un grup dintre ei s-a adapostit in mina abandonata Roland's Doom, sub comanda infricosatorului Gutspill. Sangele lor neobisnuit de fierbinte si comorile lor inflacarate ii fac tinta armurierilor ambitiosi precum Grimand.",al={"cine sunt Worgen Nightbane","Worgen din Roland's Doom","Nightbane din Roland's Doom"}}},fp="13,176,22.471.0,28.390.0,22.221.0,55.196.0,62.189.0,27.109.0,68.186.0,48.168.0"}
P.entries["quest:1706"] = {n="Grimand's Armor",s="In Stormwind, Grimand's Armor prinde contur printr-o incercare a metodelor lui Furen Longbeard. Grimand Elmore faureste o coifura din materiale rare, menita sa reziste loviturilor nimicitoare in lupta. Pentru un Warrior din Alliance, ea marcheaza un pas spre maiestrie.",h="In Stormwind, Grimand's Armor prinde contur printr-o incercare a metodelor lui Furen Longbeard.",kw={"armura","coif","sange arzator","cartierul piticilor","furen longbeard","grimand elmore","stormwind","misiune de razboinic"},ang={["class:Warrior"]="Ca Warrior din Alliance, ajungi la o etapa definitorie a pregatirii tale: o coifura rezistenta, forjata sa suporte loviturile puternice din lupta de pe linia frontului.",["faction:Alliance"]="Grimand Elmore se inspira din planurile lui Furen Longbeard, in timp ce fierarii pitici din Dwarven District, in Stormwind, isi impartasesc descoperirile pentru a inarma razboinicii Alliance.",["profession:Blacksmithing"]="Schimbul ii aduce impreuna pe doi fierari dwarven in Dwarven District din Stormwind, care folosesc reactivi neobisnuiti pentru a cali metalul."},sec={{t="Inovatia unui maestru, pusa la incercare",b="Grimand Elmore pune la incercare metodele indraznete de fierarie ale lui Furen Longbeard in atelierul sau din Dwarven District, Stormwind. Grimand se indoise de teoriile maestrului armurier Dwarf. Pentru a le testa, un Warrior aduna componente rare elementale si de la fiare din tinuturi ostile, apoi i le aduce lui Grimand. Acesta foloseste materialele pentru a fauri un coif intarit, menit sa reziste la lovituri zdrobitoare."},{t="Faurirea Aegisului",b="Coiful terminat de Grimand dovedeste ca observatiile metalurgice ale lui Furen au fost corecte. El trateaza metalul astfel incat sa reziste presiunii si loviturilor care ar deforma otelul obisnuit. Grimand ii daruieste coiful warrior-ului care l-a ajutat, cinstind mestesugul lui Furen si hotararea warrior-ului. Armura il poate ajuta sa tina linia intai impotriva celor mai mari amenintari ale Azeroth."}},faq={{q="Care este scopul acestei misiuni?",a="Grimand Elmore termina o coifura tratata special, folosind materialele rare pe care le-ai adunat si punand la incercare metodele experimentale de fierarie ale lui Furen Longbeard. Aceasta este ultima predare de obiecte dintr-o importanta serie de instruire pentru Warrior.",al={"scopul armurii lui Grimand","de ce armura lui Grimand","ce imi da Grimand"}},{q="Cine este Grimand Elmore?",a="Grimand Elmore este un priceput fauritor de arme dwarf in Dwarven District din Stormwind. Lucreaza alaturi de colegi din Ironforge pentru a-i ajuta pe razboinicii promitatori sa obtina armuri specializate.",al={"cine este Grimand","rolul lui Grimand Elmore","unde se afla Grimand"}},{q="Cine este Furen Longbeard si de ce este pomenit?",a="Furen Longbeard este un maestru armurier Dwarf din Dwarven District al Stormwind. A conceput o metoda de a intari armura impotriva tensiunilor uriase, dar Grimand s-a indoit de afirmatiile sale pana cand ai adus materiale pentru a o testa.",al={"cine este furen","tehnica lui furen","furen longbeard"}},{q="Ce misiune duce direct la aceasta?",a="Aceasta urmeaza dupa 'Burning Blood'. In acea misiune, razboinicul ii aduce lui Grimand ultimul reactiv rar, Burning Blood, de la worgenii Nightbane din Roland's Doom, in Duskwood, pentru ca acesta sa poata raci si cali metalul.",al={"cerinte preliminare pentru armura lui grimand","misiunea Sangele Arzator","ce misiune vine inaintea acesteia"}},{q="Poate orice clasa sa indeplineasca aceasta misiune?",a="Nu. Acest lant este destinat Warrior din Alliance aflati in jurul nivelului treizeci si marcheaza un rit de trecere catre armura de zale rezistenta.",al={"este Grimand's Armor doar pentru Warrior","cine poate folosi armura lui Grimand"}},{q="Unde are loc predarea?",a="Duci coiful la Grimand Elmore, la nicovala sa, in Stormwind City's Dwarven District.",al={"unde predai armura lui Grimand","locatia lui Grimand in Stormwind"}}},fx={c92a0d61={q="De ce vrea Grimand Elmore ca acest lucru sa fie facut?",a="Grimand Elmore pune la incercarea suprema tehnicile revolutionare de fierarie ale lui Furen Longbeard. La inceput sceptic ca metodele lui Furen ar putea da rezultate superioare, Grimand a avut nevoie de componente rare si puternice pentru a fauri singur setul. Terminand armura si dovedind ca poate rezista unor lovituri incredibile, el confirma descoperirea colegului sau fierar, echipand totodata un razboinic incercat pentru lupta.",al={"de ce sa confectionezi armura lui grimand","motivul lui grimand elmore","de ce sa forjezi armura"}}},fp="15,236,28.378.0,17.351.0,34.203.0,22.168.0,47.208.0,40.196.0,34.125.0,35.87.0"}
P.entries["quest:1707"] = {n="Water Pouch Bounty",s="Spigot Operator Luglunket din Gadgetzan vrea sacii cu apa ai nomazilor Wastewander, furati de acestia, oriunde i-ai gasi prin desert. Gadgetzan Water Company ofera la schimb un pachet oficial de provizii pentru fiecare cinci saci.",h="Spigot Operator Luglunket din Gadgetzan vrea sacii cu apa ai nomazilor Wastewander, furati de acestia...",kw={"Gadgetzan","Luglunket","Tanaris","Wastewander","compania de apa","burduf cu apa"},sec={{t="Apa care ii apartine lui Gadgetzan",b="Luglunket, un operator de robinet cu multa experienta, n-ar vrea nimic mai mult decat sa primeasca sacii cu apa ai celor Wastewander pe care ii gasesti prin desert. Apa era a celor din Gadgetzan de la bun inceput, iar nomazii pur si simplu au furat-o. Pentru fiecare cinci saci adusi, Gadgetzan Water Company ofera un pachet oficial de provizii, iar tu contribui la eforturile celor din Gadgetzan de a se ajuta singuri."},{t="Sa tot vina",b="Luglunket se bucura pentru fiecare saculet recuperat, fiindca fiecare ii indeparteaza pe toti de dezastru. Luglunket promite sa te rasplateasca pentru fiecare cinci saculeti pe care ii aduci."}},faq={{q="Cine este Spigot Operator Luglunket?",a="Un operator experimentat de robinete din Gadgetzan, care cere pungi cu apa Wastewander.",al={"cine este luglunket","rolul lui luglunket","operatorul robinetului"}},{q="De ce vrea Luglunket pungile cu apa Wastewander?",a="Apa apartine chiar lui Gadgetzan, iar nomazii au furat-o.",al={"de ce burdufuri cu apa","de ce sa ucizi wastewander","povestea apei wastewander"}},{q="Unde pot fi gasite pungile cu apa Wastewander?",a="In desert, in mainile nomazilor Wastewander care le-au furat.",al={"unde gasesc burdufurile cu apa","locatia burdufurilor Wastewander","cine lasa burdufuri cu apa"}},{q="Ce ofera Gadgetzan Water Company in schimbul pungilor?",a="Un pachet oficial de ingrijire pentru fiecare grup de cinci pungi.",al={"pachet de ingrijire","ce primesc pentru saculeti"}}},fp="18,219,31.357.0,16.177.1,33.79.0,50.54.0,45.73.0,60.55.0"}
