P.entries["quest:1712"] = {n="Cyclonian"}
P.entries["quest:1713"] = {n="The Summoning",s="Summoning este o incercare razboiniceasca initiata de misticul Bath'rah Windwatcher pentru a-l chema pe Cyclonian, stapanul vanturilor. Invocand si ucigand elementarul furtunos, un razboinic obtine Whirlwind Heart, cu care isi poate insufleti arma cu forta furtunii.",h="Summoning este o incercare razboiniceasca initiata de misticul Bath'rah Windwatcher pentru a-l chema pe...",kw={"bath'rah windwatcher","bathrah","cyclonian","elementar","invocarea","misiune de razboinic","inima vartejului","stapanul vantului"},ang={["class:Warrior"]="Infruntarea lui Cyclonian si obtinerea Inimii Vartejului reprezinta o proba definitorie pentru razboinicii aspiranti, aducandu-le o arma infuzata cu puterea bruta a furtunii.",["race:Troll"]="Bath'rah Windwatcher canalizeaza arte primordiale stravechi, departe de civilizatie, pentru a porunci elementarilor vantului, reflectand traditiile mistice profunde ale shamanilor si vrajitorilor voodoo Troll."},sec={{t="Chemarea furtunii",b="Invocarea incununeaza pregatirile lui Bath'rah Windwatcher. Misticul pustnic pregateste un ritual stravechi pentru a-l chema in lumea muritorilor pe Cyclonian, un elementar fioros cunoscut drept lordul vantului. Invocatorul nu vrea sa negocieze cu furtuna, ci sa o supuna, insarcinand un campion capabil sa doboare creatura chiar in clipa in care prinde forma."},{t="Inima furtunii",b="In centrul confruntarii se afla Inima Vartejului, vartejul de putere care sustine forma fizica a lui Cyclonian. Dupa ce lordul vantului este infrant si inima lui smulsa, Bath'rah foloseste vijelia furioasa captiva in ea. Acest nucleu elemental nestatornic este catalizatorul care insufla unei arme forta neingradita a furtunii."}},faq={{q="Cine este Cyclonian?",a="Cyclonian este un elemental puternic, cunoscut drept stapanul vantului. Cand este invocat prin ritualul lui Bath'rah Windwatcher, se intrupeaza ca o furtuna naprasnica, ce trebuie infranta pentru a obtine esenta sigilata in miezul sau.",al={"cine este cyclonian","ce este cyclonian","legenda lui cyclonian"}},{q="Ce este Whirlwind Heart?",a="Whirlwind Heart este nucleul elemental al lui Cyclonian. Bath'rah Windwatcher are nevoie de el pentru a lega energiile invartite si nimicitoare ale lordului vanturilor chiar de o arma puternica.",al={"ce este Whirlwind Heart","de ce este nevoie de Whirlwind Heart","la ce foloseste Whirlwind Heart"}},{q="Cine este Bath'rah Windwatcher?",a="Bath'rah Windwatcher este un mistic troll care locuieste in salbaticie si detine cunostintele necesare pentru a-l invoca pe Cyclonian. El ii indruma pe razboinici in cadrul ritualului si foloseste inima elementalului invins pentru a fauri arme puternice.",al={"cine este Bathrah","Bathrah Windwatcher","cine da misiunea The Summoning"}},{q="De ce este invocat Cyclonian?",a="Scopul invocarii lui Cyclonian este sa-l infrunti pe stapanul vanturilor in lupta, sa-l ucizi si sa-i recoltezi inima elementala. Esenta este apoi folosita pentru a insufla unei arme furia nestavilita a vartejului.",al={"de ce sa-l invoci pe Cyclonian","scopul invocarii","motivul invocarii"}},{q="Ce se intampla dupa ce Cyclonian este invins?",a="Dupa ce Cyclonian este invins si inima sa a vartejului este dusa la Bath'rah, misticul poate valorifica energiile elementale capturate pentru a insufla unei arme puterea furtunilor lui Cyclonian.",al={"ce se intampla dupa ce-l invingi pe Cyclonian","povestea recompensei lui Cyclonian","dupa invocare"}},{q="Unde are loc invocarea?",a="Ritualul are loc in tabara lui Bath'rah Windwatcher, unde misticul aduna concentrarea primordiala necesara pentru a-l atrage pe Cyclonian din taramul elementar in lumea fizica.",al={"unde are loc ritualul","locatia invocarii"}}},fp="13,254,19.374.0,22.345.0,17.216.0,28.178.0,28.217.0,32.204.0,41.185.0,36.180.0"}
P.entries["quest:1714"] = {n="Essence of the Exile",s="Essence of the Exile este un ritual misterios de transmutatie, centrat pe un cazan care bolboroseste si scoate aburi. Adaugand talismane in adancurile lichide ale cazanului, calatorii declanseaza o reactie violenta, care produce un bulgare de roca topita, in clocot. Reprezinta o convergenta puternica de reactivi instabili si putere elementala.",h="Essence of the Exile este un ritual misterios de transmutatie, centrat pe un cazan care bolboroseste si...",kw={"bula","cazan","talismane","Essence of the Exile","roca topita","transmutatie","vapori"},ang={["class:Mage"]="Cazanele alchimice si transmutarile elementale canalizeaza adesea magie bruta si volatila pentru a lega esente disparate intr-o forma solida.",["class:Shaman"]="Lucrul cu esentele elementale - chiar si prin cazane bolborositoare in care fierbe roca topita - necesita intelegerea fortelor elementale primordiale implicate."},sec={{t="Un Cauldron ademenitor",b="Essence of the Exile implica o transmutare stranie, centrata in jurul unui cazan misterios, bolborositor. Vasul emana vapori ademenitori, ispitindu-i pe calatori sa-i cerceteze adancurile clocotitoare. Acesta functioneaza ca un vas elemental, capabil sa reactioneze intens cu anumite talismane fermecate."},{t="Creuzetul topit",b="Cand amuletele necesare sunt scufundate in cazan, se lasa incet spre fund. Pe masura ce amestecul reactioneaza, o bula mare se ridica prin lichidul vascos si se sparge, dezvaluind un bulgare clocotitor de roca topita, faurit din materialele combinate."}},faq={{q="Ce este Essence of the Exile?",a="Essence of the Exile este un ritual misterios, infaptuit la un cazan bolborositor. Cand sunt aruncate talismane in adancurile sale involburate, are loc o transmuntatie instabila, care produce un bulgare de roca topita ce clocoteste.",al={"ce este essence of the exile","misiunea essence of the exile"}},{q="Ce se intampla cand amuletele sunt puse in cazan?",a="Cazanul bolboroseste, degajand vapori care ii atrag pe calatori. Cand amuletele sunt aruncate inauntru, se scufunda incet pana la fund, apoi o bula mare sparge suprafata lichidului si lasa in urma piatra topita.",al={"ce se intampla la cazan","cum functioneaza cazanul"}},{q="Ce produce cazanul?",a="Dupa ce talismanele se scufunda in lichidul aburind din cazan si o bula mare se sparge la suprafata, din vas iese la iveala o masa de roca topita, involburata.",al={"ce se obtine din cazan","ce obtii din Essence of the Exile"}},{q="Unde se afla cazanul folosit pentru acest ritual?",a="Ritualul are loc chiar langa un cazan clocotind, ai carui vapori fierbinti ii ademenesc pe cei care se apropie, acesta servind drept altar al transmutarii.",al={"locatia cazanului","unde gasesc cazanul"}},{q="De ce sunt puse amuletele in cazan?",a="Talismanele sunt reactivi care se consuma in adancul cazanului. Scufundarea lor in lichidul incins declanseaza formarea rocii topite.",al={"la ce folosesc talismanele","de ce se pun talismanele in cazan"}},{q="De ce clocoteste cazanul fara incetare?",a="Lichidul care bolboroseste si vaporii ademenitori indica o reactie chimica sau elementala activa si puternica, pe cale sa izbucneasca in vas, gata sa transforme orice patrunde in adancurile sale.",al={"de ce bolboroseste","ce sunt vaporii"}}},fp="20,311,20.290.0,19.255.0,33.213.0,52.203.0,31.166.0,43.142.0,40.146.0,40.173.0"}
